  -- 07. Farmacopeas oficiales en Colombia: USP, Ph. Eur., FEUM y otras
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"¿Cuál farmacopea, y qué edición?","texto":"Un analista nuevo encuentra que la monografía de un activo en la USP y en la Farmacopea Europea tienen límites de impurezas distintos. Pregunta cuál debe usar. La respuesta depende de lo que declara el registro sanitario del producto, de lo que la normativa colombiana reconoce como farmacopea oficial y de la edición vigente. Usar la equivocada puede llevar a liberar o rechazar un lote por la razón incorrecta."},"objetivos":["Explicar qué es una farmacopea y qué contiene.","Reconocer las farmacopeas de referencia más usadas en Colombia.","Aplicar la regla de usar la farmacopea y la edición que correspondan a lo registrado."],"conceptos":[{"icono":"BookOpen","termino":"Farmacopea","definicion":"Compendio oficial de normas de calidad: monografías de sustancias y productos, capítulos generales de métodos y textos de referencia."},{"icono":"Globe","termino":"Farmacopeas de referencia","definicion":"En Colombia se trabaja con farmacopeas extranjeras reconocidas como oficiales por la normativa sanitaria, como la de Estados Unidos (USP), la Europea (Ph. Eur.), la Británica y la Mexicana (FEUM), entre otras."},{"icono":"CalendarClock","termino":"Edición vigente","definicion":"Las farmacopeas se actualizan con frecuencia. Se debe usar la edición y el suplemento oficiales que correspondan."},{"icono":"Files","termino":"Capítulos generales","definicion":"Textos de métodos comunes (disolución, uniformidad, microbiología, cromatografía) que las monografías citan."}],"secciones":[{"titulo":"Qué es una farmacopea","parrafos":["Una farmacopea es un compendio oficial de normas de calidad. Contiene **monografías**, que definen para cada sustancia o producto sus ensayos y límites (identificación, valoración, impurezas, disolución, entre otros), y **capítulos generales**, que describen métodos comunes como la cromatografía, la disolución, la uniformidad de unidades de dosificación o los ensayos microbiológicos. Muchas farmacopeas tienen además estándares de referencia oficiales asociados a sus métodos.","Colombia no publica hoy una farmacopea nacional propia: la normativa sanitaria reconoce como oficiales farmacopeas extranjeras, entre ellas la de los Estados Unidos (USP), la Europea (Ph. Eur.), la Británica, la Mexicana (FEUM) y otras. Antes de usar una, verifica que esté dentro de las reconocidas y que sea la que declara el registro sanitario del producto."]},{"titulo":"La edición vigente y la trazabilidad","parrafos":["Las farmacopeas se actualizan con frecuencia: ediciones, suplementos y revisiones. Un cambio en una monografía puede modificar un límite, un método o un estándar. Por eso el laboratorio debe tener un sistema para **detectar cambios**, evaluarlos por control de cambios y actualizar sus especificaciones y métodos cuando corresponda. En las hojas de trabajo y en los certificados conviene registrar la farmacopea y su edición.","Cuando un producto declara una farmacopea en su registro, el laboratorio usa esa monografía; si el método farmacopeico se usa sin modificaciones, se **verifica** en el laboratorio, como viste en el curso de Validaciones. Si dos farmacopeas difieren, no se elige la más conveniente: se usa la declarada y, si se quiere cambiar, se gestiona como un cambio regulatorio."]}],"errores":[{"error":"Usar ediciones desactualizadas.","correccion":"Mantén un sistema de vigilancia farmacopeica y control de cambios."},{"error":"Elegir la farmacopea según convenga.","correccion":"Usa la declarada en el registro sanitario."}],"comprueba":[{"pregunta":"¿Qué contiene una farmacopea?","respuesta":"Monografías de sustancias y productos, capítulos generales de métodos y, en muchos casos, estándares de referencia asociados."},{"pregunta":"¿Qué farmacopea se usa para liberar un producto?","respuesta":"La declarada en su registro sanitario, en la edición vigente, siempre que sea reconocida como oficial."}],"resumen":["La farmacopea aporta **monografías y capítulos generales**.","En Colombia se usan farmacopeas **reconocidas como oficiales**, como USP, Ph. Eur., BP y FEUM.","Se usa la **declarada en el registro** y en su **edición vigente**."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"}],"imagenes":[{"ubicacion":"En la sección de farmacopeas","descripcion":"Estantería ilustrada con libros etiquetados USP, Ph. Eur., BP y FEUM, y un marcador que señala «edición vigente».","alt":"Farmacopeas de referencia usadas en Colombia"}],"keywords":["farmacopeas oficiales en colombia","usp farmacopea","farmacopea europea","feum farmacopea mexicana","qué es una farmacopea","edición vigente de la farmacopea"],"mapa":{"centro":"La farmacopea en el laboratorio","ramas":[{"titulo":"Contenido","icono":"BookOpen","nodos":["Monografías","Capítulos generales","Estándares de referencia asociados"]},{"titulo":"En Colombia","icono":"Globe","nodos":["Farmacopeas reconocidas como oficiales","USP, Ph. Eur., BP, FEUM y otras","Lo declarado en el registro"]},{"titulo":"Vigencia","icono":"CalendarClock","nodos":["Edición y suplementos","Fecha oficial","Control de cambios"]},{"titulo":"Uso","icono":"ClipboardCheck","nodos":["Especificación basada en la monografía","Verificación del método","Trazabilidad de la edición"]}]},"proceso":{"titulo":"Gestionar la actualización de una monografía","intro":"","pasos":[{"titulo":"Vigilar publicaciones","detalle":"Revisa con una frecuencia definida las nuevas ediciones y suplementos de las farmacopeas que usas.","icono":"Search","evidencia":"Registro de vigilancia farmacopeica."},{"titulo":"Identificar cambios relevantes","detalle":"Compara la monografía nueva con la vigente en tu especificación.","icono":"FileSearch","evidencia":"Tabla comparativa."},{"titulo":"Evaluar impacto","detalle":"Analiza si cambian límites, métodos o estándares, y su efecto en productos y registros.","icono":"AlertTriangle","evidencia":"Evaluación de impacto."},{"titulo":"Gestionar el cambio","detalle":"Actualiza especificaciones y métodos por control de cambios, con verificación si aplica.","icono":"GitBranch","evidencia":"Control de cambios cerrado."},{"titulo":"Entrenar y aplicar","detalle":"Entrena a los analistas y aplica la nueva versión desde su fecha oficial.","icono":"GraduationCap","evidencia":"Registro de entrenamiento."}]},"caso":{"titulo":"Dos monografías, dos límites","contexto":"El registro sanitario de un producto declara la USP. Un analista nota que la Farmacopea Europea tiene un límite de una impureza más amplio y propone usarlo porque el lote actual lo cumple.","pregunta":"¿Qué corresponde?","opciones":[{"texto":"Usar el límite europeo porque también es oficial.","correcta":false,"retro":"Elegir la farmacopea más conveniente para que un lote cumpla no es aceptable; se usa la declarada en el registro."},{"texto":"Evaluar el lote con la monografía USP declarada en el registro; si se quiere cambiar de farmacopea, gestionarlo como un cambio regulatorio.","correcta":true,"retro":"La coherencia con el registro sanitario manda. Un cambio de referencia farmacopeica es un cambio, no una elección del momento."},{"texto":"Usar el límite promedio entre ambas.","correcta":false,"retro":"No existe un límite promedio oficial."}]}}$j$::jsonb;
