  -- 08. Cómo leer y aplicar una monografía farmacopeica
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Lo que la monografía no dice explícitamente","texto":"Una analista lee en la monografía de unas tabletas: «Disolución: no menos del 80 % (Q) en 30 minutos». Prepara seis tabletas, obtiene 78 %, 85 %, 88 %, 90 %, 86 % y 84 %, y reporta «no cumple» por la unidad de 78 %. Se equivocó: la monografía remite a un capítulo general con criterios por etapas. Leer una monografía es leer también lo que remite."},"objetivos":["Identificar las partes de una monografía y lo que cada una exige.","Relacionar la monografía con los capítulos generales que cita.","Aplicar las advertencias generales al interpretar un resultado."],"conceptos":[{"icono":"FileText","termino":"Partes de la monografía","definicion":"Definición y contenido declarado, envasado y almacenamiento, estándares de referencia, identificación, valoración, impurezas y ensayos específicos de la forma farmacéutica."},{"icono":"Network","termino":"Capítulos generales citados","definicion":"La monografía remite a capítulos que definen el método y, a veces, los criterios de aceptación completos, como en disolución o uniformidad."},{"icono":"BookOpen","termino":"Advertencias generales","definicion":"Reglas que aplican a toda la farmacopea: cómo redondear, qué significa «aproximadamente», tolerancias de pesada, temperaturas de almacenamiento."},{"icono":"Calculator","termino":"Redondeo","definicion":"Los resultados se redondean según las reglas de la farmacopea antes de compararlos con el límite, no antes."}],"secciones":[{"titulo":"Las partes de una monografía","parrafos":["Una monografía de producto suele empezar con la **definición** (qué es y el contenido aceptable del activo frente a lo declarado), sigue con **envasado y almacenamiento** y con los **estándares de referencia** necesarios, y luego describe los **ensayos**: identificación, valoración, impurezas o sustancias relacionadas, y los ensayos propios de la forma farmacéutica, como disolución y uniformidad de unidades de dosificación en tabletas, o pH y volumen en soluciones.","Cada ensayo indica el método o remite a un **capítulo general**, y define las condiciones (columna, fase móvil, longitud de onda, medio de disolución) y los requisitos de **idoneidad del sistema**. La lectura cuidadosa evita errores: un detalle como la temperatura de la columna o el tiempo de equilibrio puede cambiar el resultado."]},{"titulo":"Lo que la monografía remite y las reglas comunes","parrafos":["Muchos criterios completos no están en la monografía sino en el capítulo general. En el caso inicial, el capítulo de disolución define criterios por **etapas**: en la primera, cada unidad debe dar al menos Q + 5 %; si no se cumple, se pasa a una segunda etapa con más unidades y criterios sobre el promedio y los valores individuales, y así hasta una tercera. Reportar «no cumple» por una unidad en la primera etapa es un error de lectura: lo correcto era continuar a la siguiente etapa.","Las **advertencias generales** definen reglas que aplican a toda la farmacopea: cómo redondear los resultados antes de compararlos con el límite, qué tolerancia admite una pesada indicada como «aproximadamente», qué significan los términos de almacenamiento o de solubilidad. Un laboratorio que no las conoce interpreta mal resultados que están bien medidos."]}],"errores":[{"error":"Leer solo la monografía y no los capítulos que cita.","correccion":"Abre siempre los capítulos generales referenciados."},{"error":"Redondear resultados intermedios.","correccion":"Redondea según las advertencias generales, al final, antes de comparar con el límite."}],"comprueba":[{"pregunta":"¿Qué partes tiene una monografía de producto?","respuesta":"Definición y contenido, envasado y almacenamiento, estándares, identificación, valoración, impurezas y ensayos de la forma farmacéutica."},{"pregunta":"¿Para qué sirven las advertencias generales?","respuesta":"Definen reglas comunes de interpretación, como el redondeo y las tolerancias."}],"resumen":["Una monografía se lee **completa**: encabezado, ensayos y capítulos citados.","Muchos criterios completos están en los **capítulos generales**.","Las **advertencias generales** gobiernan la interpretación."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"}],"imagenes":[{"ubicacion":"En la sección de partes","descripcion":"Página de monografía ilustrada con secciones coloreadas y flechas hacia capítulos generales en la parte inferior.","alt":"Partes de una monografía farmacopeica y sus capítulos generales"}],"keywords":["cómo leer una monografía usp","monografía farmacopeica partes","capítulos generales usp","advertencias generales farmacopea","aplicar monografía en control de calidad"],"mapa":{"centro":"Leer una monografía completa","ramas":[{"titulo":"Encabezado","icono":"FileText","nodos":["Definición y contenido declarado","Envasado y almacenamiento","Estándares requeridos"]},{"titulo":"Ensayos","icono":"FlaskConical","nodos":["Identificación","Valoración","Impurezas","Ensayos de la forma farmacéutica"]},{"titulo":"Lo que remite","icono":"Network","nodos":["Capítulos generales","Criterios por etapas","Idoneidad del sistema"]},{"titulo":"Reglas comunes","icono":"BookOpen","nodos":["Advertencias generales","Redondeo","Tolerancias"]}]},"proceso":{"titulo":"Leer una monografía antes de analizar","intro":"","pasos":[{"titulo":"Leer el encabezado","detalle":"Anota el contenido aceptable, el almacenamiento y los estándares requeridos.","icono":"FileText","evidencia":"Hoja de trabajo con datos del encabezado."},{"titulo":"Listar los ensayos","detalle":"Enumera cada ensayo con su método y su criterio.","icono":"ClipboardList","evidencia":"Lista de ensayos."},{"titulo":"Abrir los capítulos citados","detalle":"Lee los capítulos generales a los que remite cada ensayo, incluidos los criterios por etapas.","icono":"Network","evidencia":"Referencias de capítulos anotadas."},{"titulo":"Revisar las advertencias generales","detalle":"Confirma las reglas de redondeo, tolerancias y términos que aplican.","icono":"BookOpen","evidencia":"Notas de interpretación."},{"titulo":"Preparar la idoneidad","detalle":"Prepara las soluciones de idoneidad del sistema y sus criterios.","icono":"Gauge","evidencia":"Criterios de idoneidad en la hoja."}]},"caso":{"titulo":"Una unidad baja en disolución","contexto":"En la primera etapa de un ensayo de disolución con Q = 80 %, cinco unidades dan entre 84 % y 90 % y una da 78 %.","pregunta":"¿Cuál es la decisión correcta?","opciones":[{"texto":"Reportar que no cumple por la unidad de 78 %.","correcta":false,"retro":"La primera etapa no se cumplió, pero el capítulo general prevé una segunda etapa antes de concluir."},{"texto":"Continuar a la segunda etapa según el capítulo general de disolución y evaluar con sus criterios.","correcta":true,"retro":"El capítulo general define el criterio completo por etapas; se aplica antes de concluir."},{"texto":"Repetir solo la unidad de 78 %.","correcta":false,"retro":"Repetir una unidad no está previsto; el procedimiento es pasar a la siguiente etapa."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Cómo leer y aplicar una monografía farmacopeica$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Cómo leer y aplicar una monografía farmacopeica$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 09. Establecimiento de especificaciones (ICH Q6A)
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un límite que nadie supo defender","texto":"En la evaluación de un registro, el evaluador pregunta por qué el límite de una impureza es 0,5 %. El equipo responde que «así venía en el documento del proyecto anterior». No había datos de lotes ni estudios de estabilidad ni análisis de seguridad que lo justificaran. Una especificación no se copia: se construye con datos. ICH Q6A explica cómo."},"objetivos":["Diferenciar los ensayos universales de los específicos según ICH Q6A.","Justificar criterios de aceptación con datos de desarrollo, lotes y estabilidad.","Reconocer cuándo usar especificaciones de liberación y de vida útil distintas."],"conceptos":[{"icono":"Layers","termino":"Ensayos universales","definicion":"Los que aplican a todo producto: descripción, identificación, valoración e impurezas."},{"icono":"Puzzle","termino":"Ensayos específicos","definicion":"Dependen de la forma farmacéutica: disolución, uniformidad, agua, límites microbianos, pH, entre otros."},{"icono":"LineChart","termino":"Justificación","definicion":"Cada criterio se sustenta en datos de lotes de desarrollo y de escala, estabilidad, capacidad del método y relevancia clínica o de seguridad."},{"icono":"CalendarClock","termino":"Liberación y vida útil","definicion":"Pueden tener criterios distintos cuando el atributo cambia durante el almacenamiento, siempre justificado."}],"secciones":[{"titulo":"Ensayos universales y específicos","parrafos":["ICH Q6A propone ensayos **universales** para todos los productos y principios activos: **descripción**, **identificación**, **valoración** e **impurezas**. Luego agrega ensayos **específicos** según la forma farmacéutica: para formas orales sólidas, por ejemplo, disolución o desintegración, dureza y friabilidad cuando sean relevantes, uniformidad de unidades de dosificación, contenido de agua y límites microbianos; para líquidos orales, pH, uniformidad en envases multidosis, contenido de conservante, entre otros.","La guía incluye **árboles de decisión** que ayudan a decidir, por ejemplo, si un ensayo de disolución debe tener un punto o varios, si se requiere un ensayo de polimorfismo o si se pueden omitir ciertos ensayos microbianos con base en datos."]},{"titulo":"Justificar los límites","parrafos":["Un criterio de aceptación se **justifica** con datos: los resultados de los lotes de desarrollo y de escala, la variabilidad del proceso, la capacidad del método analítico, los datos de estabilidad y la relevancia clínica o de seguridad. Para impurezas, los límites se apoyan en los umbrales de ICH Q3A y Q3B y en la calificación de seguridad. Un límite demasiado amplio no protege al paciente; uno demasiado estrecho rechaza lotes buenos por la variabilidad normal.","La guía admite criterios distintos para **liberación** y para **vida útil** cuando un atributo cambia durante el almacenamiento, por ejemplo un contenido que disminuye ligeramente: el límite de liberación más estrecho asegura que el producto llegue al final de su vida útil dentro del límite de vida útil. Esa diferencia debe justificarse con datos de estabilidad. Las especificaciones se revisan cuando se acumula experiencia de fabricación."]}],"errores":[{"error":"Copiar límites de otro producto.","correccion":"Justifica cada límite con datos del propio producto."},{"error":"Ignorar la variabilidad del método al fijar límites.","correccion":"Considera la capacidad del método junto con la del proceso."}],"comprueba":[{"pregunta":"¿Cuáles son los ensayos universales de ICH Q6A?","respuesta":"Descripción, identificación, valoración e impurezas."},{"pregunta":"¿Por qué pueden diferir los límites de liberación y de vida útil?","respuesta":"Porque algunos atributos cambian durante el almacenamiento; un límite de liberación más estrecho asegura el cumplimiento durante toda la vida útil."}],"resumen":["Q6A: ensayos **universales** más ensayos **específicos** de la forma.","Cada límite se **justifica con datos**.","Liberación y vida útil pueden tener **criterios distintos**, justificados."],"referencias":[{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"},{"cita":"ICH. Q3A(R2) Impurities in New Drug Substances (EMA, Step 5).","url":"https://ema.europa.eu/en/documents/scientific-guideline/ich-q-3-r2-impurities-new-drug-substances-step-5_en.pdf"},{"cita":"ICH. Q1A(R2) Stability Testing of New Drug Substances and Products.","url":"https://database.ich.org/sites/default/files/Q1A%28R2%29%20Guideline.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"Junto al caso","descripcion":"Gráfico de estabilidad ilustrado: contenido que desciende en el tiempo, con bandas de límite de liberación y de vida útil en colores de marca.","alt":"Límites de liberación y de vida útil frente a la tendencia de estabilidad"}],"keywords":["ich q6a en español","especificaciones ich q6a","ensayos universales y específicos","justificación de especificaciones","especificación de liberación y vida útil","cómo establecer especificaciones farmacéuticas"],"mapa":{"centro":"Construir una especificación","ramas":[{"titulo":"Qué ensayos","icono":"Layers","nodos":["Universales","Específicos de la forma","Árboles de decisión de Q6A"]},{"titulo":"Con qué datos","icono":"LineChart","nodos":["Lotes de desarrollo y escala","Estabilidad","Capacidad del método"]},{"titulo":"Con qué límites","icono":"Target","nodos":["Relevancia clínica","Seguridad (ICH Q3)","Farmacopea"]},{"titulo":"En qué momento","icono":"CalendarClock","nodos":["Liberación","Vida útil","Revisión periódica"]}]},"proceso":{"titulo":"Proponer una especificación para un producto nuevo","intro":"","pasos":[{"titulo":"Definir el perfil de calidad","detalle":"Identifica los atributos críticos de calidad del producto.","icono":"Target","evidencia":"Perfil de calidad."},{"titulo":"Elegir los ensayos","detalle":"Aplica los ensayos universales y los específicos de la forma, con los árboles de decisión de Q6A.","icono":"Layers","evidencia":"Lista de ensayos justificada."},{"titulo":"Reunir datos","detalle":"Compila resultados de lotes, estabilidad y validación de métodos.","icono":"Database","evidencia":"Tabla de datos de lotes."},{"titulo":"Proponer límites","detalle":"Establece criterios con base en datos, seguridad, farmacopea y relevancia clínica.","icono":"Target","evidencia":"Propuesta de límites con justificación."},{"titulo":"Definir liberación y vida útil","detalle":"Si el atributo cambia, define criterios para cada momento y justifícalos.","icono":"CalendarClock","evidencia":"Especificaciones de liberación y vida útil."},{"titulo":"Revisar con experiencia","detalle":"Revisa las especificaciones con los datos de fabricación comercial.","icono":"RefreshCw","evidencia":"Revisión periódica."}]},"caso":{"titulo":"Un contenido que baja con el tiempo","contexto":"Los datos de estabilidad muestran que el contenido de un activo baja en promedio 2 % durante la vida útil. El límite de vida útil es 90,0–110,0 %.","pregunta":"¿Qué límite de liberación es razonable proponer?","opciones":[{"texto":"El mismo 90,0–110,0 %: si cumple al liberar, cumple siempre.","correcta":false,"retro":"Un lote liberado en 90,5 % podría terminar por debajo de 90,0 % antes de vencer."},{"texto":"Un límite de liberación más estrecho en el extremo inferior, por ejemplo 95,0–105,0 %, justificado con la pérdida observada y la variabilidad del método.","correcta":true,"retro":"Así el producto conserva margen para seguir cumpliendo el límite de vida útil, y la justificación queda en los datos."},{"texto":"Un límite de liberación más amplio para no rechazar lotes.","correcta":false,"retro":"Ampliar la liberación aumenta el riesgo de que el producto no cumpla durante su vida útil."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Establecimiento de especificaciones (ICH Q6A)$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Establecimiento de especificaciones (ICH Q6A)$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
