  -- 10. Planes de muestreo y tamaño de muestra
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Tres cajas de la parte de arriba","texto":"Para analizar un lote de 2.000 cajas de producto terminado, alguien toma tres cajas de la parte superior del primer estibado, porque son las más fáciles de alcanzar. Si hubo un problema al final del envasado, esas cajas nunca lo mostrarán. El resultado del laboratorio solo vale tanto como la muestra que lo produjo. Muestrear bien es la primera condición de un análisis confiable."},"objetivos":["Explicar qué hace representativa a una muestra.","Describir planes de muestreo para materias primas y producto terminado.","Reconocer los requisitos de muestras de retención."],"conceptos":[{"icono":"Target","termino":"Muestra representativa","definicion":"Porción de un lote que refleja sus características, tomada según un plan que considere la homogeneidad del material y los riesgos."},{"icono":"Sigma","termino":"Plan de muestreo","definicion":"Define cuántos contenedores o unidades se muestrean, de dónde, con qué técnica y cuánta muestra se toma."},{"icono":"Shuffle","termino":"Muestreo aleatorio o estratificado","definicion":"Selección al azar o por partes del lote (inicio, mitad, final) para evitar sesgos."},{"icono":"Archive","termino":"Muestra de retención","definicion":"Cantidad reservada de cada lote para análisis futuros, conservada en las condiciones del producto durante el tiempo definido."}],"secciones":[{"titulo":"Qué hace representativa a una muestra","parrafos":["Una muestra es representativa cuando sus características reflejan las del lote. Eso depende de la **homogeneidad** del material, del **número** de unidades o contenedores muestreados, de **dónde** se toman y de la **técnica**. La guía de la OMS sobre muestreo (TRS 929, Anexo 4) describe planes para materias primas según la homogeneidad del lote y la confianza en el proveedor, como los planes basados en la raíz cuadrada del número de contenedores, y enfatiza la seguridad, la limpieza de las herramientas y la protección de la muestra.","Para producto terminado, el plan suele **estratificar** el muestreo a lo largo del proceso (inicio, mitad y final de la compresión o del envasado) para que la muestra incluya posibles variaciones en el tiempo. Para atributos que se inspeccionan por conteo, como defectos de envase, se usan planes de muestreo por atributos con niveles de inspección y de calidad aceptable definidos."]},{"titulo":"Cantidad, identificación y retención","parrafos":["La cantidad de muestra debe alcanzar para todos los ensayos de la especificación, para posibles repeticiones dentro de una investigación y para la **muestra de retención**. Cada muestra se rotula con el material, el lote, la fecha, el punto de muestreo y quién la tomó, y se registra su cadena de custodia hasta el laboratorio.","Las BPM piden conservar **muestras de retención** de cada lote de producto terminado y de las materias primas, en cantidad suficiente para al menos un análisis completo, en las condiciones de almacenamiento del producto y durante el tiempo definido por la normativa y la empresa. Sirven para investigar quejas, desviaciones o dudas sobre un lote ya distribuido."]}],"errores":[{"error":"Muestrear por comodidad.","correccion":"Sigue un plan aleatorio o estratificado escrito."},{"error":"Muestra insuficiente para repeticiones.","correccion":"Calcula la cantidad para todos los ensayos, posibles investigaciones y retención."}],"comprueba":[{"pregunta":"¿Qué hace representativa a una muestra?","respuesta":"Un plan que considere la homogeneidad, el número de unidades, dónde se toman y la técnica."},{"pregunta":"¿Para qué sirven las muestras de retención?","respuesta":"Para investigar quejas, desviaciones o dudas sobre un lote ya distribuido."}],"resumen":["Un resultado vale **lo que vale su muestra**.","El muestreo sigue un **plan** aleatorio o estratificado.","Las **muestras de retención** permiten investigar después."],"referencias":[{"cita":"OMS. TRS 929, Anexo 4: WHO guidelines for sampling of pharmaceutical products and related materials.","url":"https://www.who.int/publications/m/item/annex-4-trs-929"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"En la sección de representatividad","descripcion":"Línea de envasado ilustrada con tres puntos de muestreo marcados (inicio, mitad, final) y un reloj sobre cada uno.","alt":"Muestreo estratificado de un lote durante el envasado"}],"keywords":["plan de muestreo farmacéutico","tamaño de muestra control de calidad","muestreo representativo","muestreo estratificado","muestras de retención","trs 929 anexo 4 muestreo"],"mapa":{"centro":"Una muestra que represente el lote","ramas":[{"titulo":"Cuánto","icono":"Sigma","nodos":["Número de contenedores o unidades","Cantidad para ensayos y repeticiones","Retención"]},{"titulo":"De dónde","icono":"MapPin","nodos":["Aleatorio","Estratificado por inicio, mitad y final","Puntos de riesgo"]},{"titulo":"Cómo","icono":"TestTube","nodos":["Técnica y herramientas limpias","Área de muestreo","Identificación de la muestra"]},{"titulo":"Referencias","icono":"BookOpen","nodos":["OMS TRS 929, Anexo 4","Normas de muestreo por atributos","Procedimiento interno"]}]},"proceso":{"titulo":"Muestreo estratificado de un lote de tabletas envasadas","intro":"","pasos":[{"titulo":"Definir el plan","detalle":"Establece cuántas unidades tomar en cada momento del envasado según el procedimiento.","icono":"Sigma","evidencia":"Plan de muestreo aprobado."},{"titulo":"Tomar al inicio","detalle":"Muestrea las primeras unidades después del ajuste de la línea.","icono":"Timer","evidencia":"Registro con hora de muestreo."},{"titulo":"Tomar a mitad","detalle":"Muestrea en la mitad del proceso, sin elegir unidades «bonitas».","icono":"Shuffle","evidencia":"Registro con hora."},{"titulo":"Tomar al final","detalle":"Muestrea las últimas unidades del lote.","icono":"Flag","evidencia":"Registro con hora."},{"titulo":"Rotular y custodiar","detalle":"Identifica cada muestra y entrégala al laboratorio con su cadena de custodia.","icono":"Tag","evidencia":"Rótulos y cadena de custodia."},{"titulo":"Reservar la retención","detalle":"Separa la muestra de retención en las condiciones del producto.","icono":"Archive","evidencia":"Registro de retenciones."}]},"caso":{"titulo":"Las cajas más accesibles","contexto":"El auxiliar de almacén toma las muestras de producto terminado de las cajas del estibado superior porque «es más rápido y todas son del mismo lote».","pregunta":"¿Qué corriges?","opciones":[{"texto":"Nada: todas las cajas son del mismo lote.","correcta":false,"retro":"Ser del mismo lote no garantiza homogeneidad en el tiempo de envasado; las variaciones se concentran en momentos concretos."},{"texto":"El muestreo debe seguir un plan aleatorio o estratificado que represente todo el lote, idealmente durante el proceso; se reentrena y se revisa el procedimiento.","correcta":true,"retro":"La representatividad depende del plan, no de la comodidad."},{"texto":"Tomar más cajas del estibado superior.","correcta":false,"retro":"Más muestras sesgadas siguen siendo sesgadas."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Planes de muestreo y tamaño de muestra$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Planes de muestreo y tamaño de muestra$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 11. Control de calidad de materias primas
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un certificado perfecto y un material equivocado","texto":"Un proveedor entrega un activo con un certificado de análisis impecable. El laboratorio, por presión de tiempo, aprueba con base en el certificado y una prueba de identidad por punto de fusión. Meses después, una investigación revela que el material tenía otra forma polimórfica, con menor solubilidad: los lotes fabricados con él tuvieron disolución baja. Controlar una materia prima es más que confirmar su nombre."},"objetivos":["Describir los ensayos habituales de una materia prima activa y de un excipiente.","Explicar cuándo puede usarse el certificado del proveedor y con qué condiciones.","Relacionar las propiedades de la materia prima con el desempeño del producto."],"conceptos":[{"icono":"Fingerprint","termino":"Identidad","definicion":"Confirmación de que el material es lo que dice ser, con técnicas específicas como la espectroscopia infrarroja."},{"icono":"Target","termino":"Pureza y valoración","definicion":"Contenido del componente principal e impurezas, incluidos solventes residuales y metales cuando aplica."},{"icono":"Atom","termino":"Propiedades fisicoquímicas","definicion":"Tamaño de partícula, forma polimórfica, densidad o humedad, que pueden afectar la fabricación y la disolución."},{"icono":"BadgeCheck","termino":"Uso del certificado del proveedor","definicion":"Posible para algunos ensayos si el proveedor está calificado y se verifica periódicamente su confiabilidad, pero la identidad se confirma en el laboratorio."}],"secciones":[{"titulo":"Qué se controla y por qué","parrafos":["Una materia prima activa se controla normalmente con **identificación** (por ejemplo, espectroscopia infrarroja comparada con un estándar), **valoración**, **impurezas** o sustancias relacionadas, **solventes residuales**, contenido de **agua** y otros ensayos de su monografía o especificación. Para los excipientes se aplican sus monografías, con atención a contaminantes conocidos: la glicerina y otros, por ejemplo, se controlan por dietilenglicol y etilenglicol.","Además de la calidad química, importan las **propiedades fisicoquímicas** que afectan el proceso y el desempeño: tamaño de partícula y forma polimórfica del activo (que influyen en la disolución), densidad y fluidez (que influyen en la compresión) y humedad. Si el desarrollo mostró que una propiedad es crítica, debe estar en la especificación aunque la monografía no la exija, como en el caso del polimorfo."]},{"titulo":"El certificado del proveedor","parrafos":["Las BPM permiten, en ciertas condiciones, apoyarse en el **certificado de análisis del proveedor** para algunos ensayos: el proveedor debe estar **calificado** (evaluación, auditoría cuando corresponda, historial), y el laboratorio debe verificar periódicamente la confiabilidad del certificado analizando lotes completos. Aun así, la **identidad** se confirma en el laboratorio sobre las muestras, según el procedimiento.","El laboratorio también revisa la coherencia del certificado: que corresponda al lote recibido, que use métodos equivalentes y que los resultados sean consistentes con el historial. Un certificado que parece «demasiado perfecto» o idéntico lote tras lote merece atención: la integridad de los datos del proveedor también se evalúa."]}],"errores":[{"error":"Aprobar solo con el certificado del proveedor.","correccion":"Confirma la identidad y verifica periódicamente lotes completos."},{"error":"Ignorar propiedades físicas críticas.","correccion":"Incluye en la especificación las propiedades que el desarrollo identificó como críticas."}],"comprueba":[{"pregunta":"¿Qué condiciones permiten usar el certificado del proveedor?","respuesta":"Proveedor calificado y verificación periódica de la confiabilidad del certificado; la identidad se confirma en el laboratorio."},{"pregunta":"¿Por qué importa la forma polimórfica?","respuesta":"Porque puede cambiar la solubilidad y la disolución del producto."}],"resumen":["Se controlan **identidad, pureza y propiedades críticas**.","El certificado del proveedor se usa **con calificación y verificación**.","La identidad se **confirma siempre** en el laboratorio."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"},{"cita":"OMS. TRS 929, Anexo 4: WHO guidelines for sampling of pharmaceutical products and related materials.","url":"https://www.who.int/publications/m/item/annex-4-trs-929"}],"imagenes":[{"ubicacion":"En la sección de propiedades","descripcion":"Dos cristales ilustrados de la misma molécula con formas distintas y una flecha hacia curvas de disolución diferentes.","alt":"Polimorfismo y su efecto en la disolución"}],"keywords":["control de calidad de materias primas","análisis de materias primas farmacéuticas","identidad de materias primas","certificado de análisis del proveedor","polimorfismo farmacéutico","calificación de proveedores de materias primas"],"mapa":{"centro":"Controlar una materia prima","ramas":[{"titulo":"Identidad","icono":"Fingerprint","nodos":["IR u otra técnica específica","Por contenedor según procedimiento"]},{"titulo":"Pureza","icono":"Search","nodos":["Valoración","Impurezas y solventes","Microbiología si aplica"]},{"titulo":"Propiedades","icono":"Atom","nodos":["Tamaño de partícula","Polimorfismo","Humedad y densidad"]},{"titulo":"Proveedor","icono":"BadgeCheck","nodos":["Calificación","Uso del certificado","Verificación periódica"]}]},"proceso":{"titulo":"Análisis de una materia prima activa","intro":"","pasos":[{"titulo":"Revisar el certificado","detalle":"Verifica que corresponda al lote, al proveedor calificado y a la especificación.","icono":"FileSearch","evidencia":"Revisión del certificado."},{"titulo":"Confirmar identidad","detalle":"Analiza la identidad de las muestras según el procedimiento, con técnica específica.","icono":"Fingerprint","evidencia":"Espectros y resultados de identidad."},{"titulo":"Ejecutar ensayos de la especificación","detalle":"Valoración, impurezas, agua, solventes y propiedades críticas.","icono":"FlaskConical","evidencia":"Resultados analíticos."},{"titulo":"Evaluar propiedades críticas","detalle":"Tamaño de partícula, polimorfismo u otras si el desarrollo las identificó.","icono":"Atom","evidencia":"Resultados de propiedades."},{"titulo":"Aprobar o rechazar","detalle":"Con todos los resultados conformes, se aprueba con fecha de reanálisis.","icono":"BadgeCheck","evidencia":"Dictamen y rótulo de estado."}]},"caso":{"titulo":"El proveedor de toda la vida","contexto":"Un proveedor con diez años de historial impecable cambia su sitio de fabricación del activo. Sus certificados siguen igual de perfectos.","pregunta":"¿Qué hace el laboratorio?","opciones":[{"texto":"Seguir aprobando con el certificado: el proveedor es confiable.","correcta":false,"retro":"Un cambio de sitio es un cambio relevante: la confiabilidad se demostró para el sitio anterior."},{"texto":"Gestionar el cambio: analizar lotes completos del nuevo sitio, incluidas propiedades críticas como polimorfismo y tamaño de partícula, y reevaluar la calificación del proveedor.","correcta":true,"retro":"El cambio de sitio puede cambiar el perfil de impurezas o las propiedades físicas; se verifica con datos antes de confiar en el certificado."},{"texto":"Pedir al proveedor un certificado firmado por su gerente.","correcta":false,"retro":"Más firmas no aportan evidencia técnica."}]}}$j$::jsonb;
