  -- 12. Control de calidad de material de envase y empaque
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El frasco que dejaba pasar la humedad","texto":"Un producto higroscópico perdía potencia antes de su vencimiento solo en un lote de frascos. El activo y el proceso estaban bien. El problema estaba en el envase: un lote de frascos con una tapa que no sellaba según lo especificado. El material de envase no es un accesorio: protege al producto durante toda su vida útil y lleva la información que el paciente necesita."},"objetivos":["Diferenciar envase primario, secundario y material impreso.","Describir los ensayos de control del material de envase.","Aplicar planes de inspección por atributos a defectos de envase."],"conceptos":[{"icono":"Package","termino":"Envase primario","definicion":"El que está en contacto directo con el producto: frasco, blíster, ampolla, tapón. Debe proteger y no interactuar con el producto."},{"icono":"Box","termino":"Envase secundario","definicion":"El que contiene al primario, como la plegadiza. Protege y lleva información."},{"icono":"Tag","termino":"Material impreso","definicion":"Etiquetas, plegadizas e insertos cuyo texto y arte deben coincidir con lo aprobado."},{"icono":"Search","termino":"Defectos","definicion":"Se clasifican como críticos, mayores o menores según su riesgo, y se inspeccionan con planes por atributos."}],"secciones":[{"titulo":"Qué se controla","parrafos":["El material de envase se controla según su función. Para el **envase primario** importan la identidad del material (vidrio, tipo de plástico, elastómero), las **dimensiones críticas** que aseguran el cierre y el funcionamiento en la línea, la **hermeticidad** del sistema de cierre, y su compatibilidad con el producto, que se demostró en el desarrollo con estudios de estabilidad en ese envase. Para el vidrio de inyectables, la farmacopea define tipos y ensayos.","Para el **material impreso**, el control verifica que el texto, el arte, los colores, los códigos y la legibilidad coincidan exactamente con la versión aprobada, que a su vez coincide con el registro sanitario. Un error en una concentración o en una advertencia puede causar un error de medicación."]},{"titulo":"Defectos y planes de inspección","parrafos":["Los defectos se clasifican por su riesgo. Un defecto **crítico** puede afectar la seguridad del paciente o la integridad del producto: por ejemplo, una concentración mal impresa o un frasco con fisura. Un defecto **mayor** puede afectar la función o el uso: una tapa que no cierra bien. Un defecto **menor** afecta la apariencia sin consecuencia funcional.","La inspección se hace con **planes de muestreo por atributos**, que definen cuántas unidades inspeccionar y cuántos defectos de cada clase se aceptan, con criterios más estrictos para los críticos. Si el lote supera los límites, se rechaza o se gestiona con el proveedor. El historial de cada proveedor alimenta su calificación y la frecuencia de inspección."]}],"errores":[{"error":"Inspeccionar el material impreso sin un estándar aprobado.","correccion":"Compara siempre contra la versión aprobada vigente."},{"error":"Tratar todos los defectos igual.","correccion":"Clasifícalos por riesgo y aplica criterios distintos."}],"comprueba":[{"pregunta":"¿Qué diferencia hay entre envase primario y secundario?","respuesta":"El primario está en contacto con el producto; el secundario contiene al primario."},{"pregunta":"Da un ejemplo de defecto crítico.","respuesta":"Una concentración mal impresa o un frasco con fisura."}],"resumen":["El envase **protege** al producto y **informa** al paciente.","Se controlan materiales, dimensiones, cierre e **impresos**.","Los defectos se clasifican y se inspeccionan **por atributos**."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Despiece ilustrado de un producto: blíster (primario), plegadiza (secundario) e inserto, con etiquetas en colores de marca.","alt":"Envase primario, secundario y material impreso"}],"keywords":["control de calidad material de envase","envase primario y secundario","inspección de material de empaque","defectos críticos mayores menores envase","control de calidad material impreso"],"mapa":{"centro":"Control del material de envase","ramas":[{"titulo":"Identidad y materiales","icono":"Package","nodos":["Material correcto","Especificación del proveedor","Compatibilidad con el producto"]},{"titulo":"Dimensiones y función","icono":"Ruler","nodos":["Medidas críticas","Cierre y hermeticidad","Funcionamiento en línea"]},{"titulo":"Impresos","icono":"Tag","nodos":["Texto y arte aprobados","Códigos y colores","Legibilidad"]},{"titulo":"Defectos","icono":"Search","nodos":["Críticos, mayores, menores","Plan por atributos","Decisión del lote"]}]},"proceso":{"titulo":"Inspección de un lote de plegadizas","intro":"","pasos":[{"titulo":"Verificar la recepción","detalle":"Confirma proveedor aprobado, lote, cantidad y estado del embalaje.","icono":"Truck","evidencia":"Registro de recepción."},{"titulo":"Muestrear por atributos","detalle":"Toma el número de unidades que indica el plan de inspección.","icono":"Sigma","evidencia":"Plan aplicado."},{"titulo":"Comparar con el arte aprobado","detalle":"Verifica texto, colores, códigos y dimensiones contra el estándar aprobado.","icono":"FileSearch","evidencia":"Lista de verificación."},{"titulo":"Clasificar defectos","detalle":"Cuenta los defectos críticos, mayores y menores.","icono":"AlertTriangle","evidencia":"Conteo de defectos."},{"titulo":"Decidir","detalle":"Aprueba o rechaza según los límites del plan.","icono":"Gavel","evidencia":"Dictamen y rótulo de estado."}]},"caso":{"titulo":"Una sola plegadiza con otra concentración","contexto":"En la inspección de un lote de plegadizas de 500 mg, aparece una plegadiza impresa con 250 mg. Las demás muestras están bien.","pregunta":"¿Cómo se maneja?","opciones":[{"texto":"Aceptar el lote: es un solo defecto.","correcta":false,"retro":"Una concentración equivocada es un defecto crítico; su presencia indica una posible mezcla en la imprenta."},{"texto":"Clasificarlo como crítico, rechazar o retener el lote, notificar al proveedor e investigar el alcance de la mezcla.","correcta":true,"retro":"Los defectos críticos suelen tener aceptación cero: un solo hallazgo puede significar muchas más unidades mezcladas."},{"texto":"Retirar la plegadiza y aprobar el resto.","correcta":false,"retro":"Retirar la unidad encontrada no garantiza que no haya otras en el lote."}]}}$j$::jsonb;
