  END IF;

  -- 13. Estándares de referencia primarios y secundarios: tipos, calificación y manejo
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Todo resultado se compara con algo","texto":"Una valoración por HPLC no mide el contenido de forma absoluta: compara la respuesta de la muestra con la de un estándar de pureza conocida. Si el estándar se degradó o se usó vencido, todos los resultados del día están mal, aunque el equipo, el método y el analista sean impecables. El estándar de referencia es el ancla de la medición."},"objetivos":["Diferenciar estándares primarios y secundarios.","Describir la calificación de un estándar secundario frente a uno primario.","Aplicar buenas prácticas de almacenamiento, uso y control de vigencia."],"conceptos":[{"icono":"Award","termino":"Estándar primario","definicion":"Sustancia de referencia de alta pureza, establecida por una farmacopea u organismo reconocido, que se usa sin calificación adicional para el propósito indicado."},{"icono":"BadgeCheck","termino":"Estándar secundario","definicion":"Estándar de trabajo calificado por el laboratorio frente a un primario, para uso rutinario."},{"icono":"CalendarClock","termino":"Vigencia","definicion":"Periodo en que el estándar se considera apto: lote vigente del primario o fecha de recalificación del secundario."},{"icono":"Thermometer","termino":"Condiciones","definicion":"Almacenamiento según la etiqueta (temperatura, luz, humedad) y manipulación que evite contaminación o degradación."}],"secciones":[{"titulo":"Primarios y secundarios","parrafos":["Un **estándar primario** es una sustancia de referencia de alta pureza establecida por una farmacopea u organismo reconocido, que se usa sin necesidad de calificación adicional para el propósito para el que fue establecido. Los estándares de las farmacopeas son el ejemplo más común. La guía de la OMS sobre sustancias químicas de referencia (TRS 943, Anexo 3) describe cómo se establecen, mantienen y distribuyen.","Como los primarios son costosos y escasos, el laboratorio suele preparar **estándares secundarios** o de trabajo: lotes de la sustancia caracterizados y **calificados frente al primario**. La calificación incluye identidad, pureza y la asignación del contenido o potencia con un número suficiente de determinaciones, y define una fecha de recalificación. El secundario solo vale mientras su calificación esté vigente."]},{"titulo":"Manejo y control de vigencia","parrafos":["Los estándares se almacenan según las condiciones de su etiqueta, se manipulan para evitar contaminación (por ejemplo, sin devolver material sobrante al frasco) y, si la monografía lo indica, se secan antes de usarlos. Cada uso se **registra**: quién, cuándo, cuánto y para qué análisis, de modo que si un estándar resulta defectuoso se pueda identificar qué resultados se afectaron.","Usar un estándar **vencido** o con la recalificación vencida es una desviación, aunque los resultados parezcan correctos. El caso integrador de este curso lo muestra: un lote que cumple todos los ensayos no puede liberarse si el estándar usado tenía su recalificación vencida, hasta evaluar el impacto con un estándar vigente."]}],"errores":[{"error":"Devolver material sobrante al frasco del estándar.","correccion":"Toma la cantidad necesaria y desecha el sobrante."},{"error":"No registrar los usos del estándar.","correccion":"Registra cada uso para poder rastrear el impacto de un estándar defectuoso."}],"comprueba":[{"pregunta":"¿Qué diferencia hay entre un estándar primario y uno secundario?","respuesta":"El primario lo establece un organismo reconocido y se usa sin calificación adicional; el secundario se califica frente al primario."},{"pregunta":"¿Qué pasa si se usa un estándar con la recalificación vencida?","respuesta":"Es una desviación: hay que evaluar el impacto con evidencia antes de usar los resultados."}],"resumen":["El estándar es el **ancla** de la medición.","Los **secundarios** se califican frente a primarios y se recalifican.","Vigencia, condiciones y **registro de uso** se controlan siempre."],"referencias":[{"cita":"OMS. TRS 943, Anexo 3: General guidelines for the establishment, maintenance and distribution of chemical reference substances.","url":"https://www.who.int/docs/default-source/medicines/norms-and-standards/guidelines/quality-control/trs943-annex3-establishmentmaintenance-distribution-chemica-reference-substances.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"}],"imagenes":[{"ubicacion":"En la sección de primarios y secundarios","descripcion":"Dos frascos ilustrados: uno con sello de farmacopea (primario) y otro con etiqueta interna (secundario), unidos por una flecha de calificación.","alt":"Calificación de un estándar secundario frente a uno primario"}],"keywords":["estándar de referencia primario y secundario","calificación de estándares secundarios","sustancias de referencia farmacéuticas","estándar de trabajo laboratorio","trs 943 anexo 3","manejo de estándares de referencia"],"mapa":{"centro":"El ancla de la medición","ramas":[{"titulo":"Primarios","icono":"Award","nodos":["Farmacopeas u organismos reconocidos","Uso sin calificación adicional","Lote vigente"]},{"titulo":"Secundarios","icono":"BadgeCheck","nodos":["Calificados frente al primario","Uso rutinario","Recalificación periódica"]},{"titulo":"Manejo","icono":"Thermometer","nodos":["Condiciones de la etiqueta","Registro de uso","Secado si la monografía lo pide"]},{"titulo":"Riesgos","icono":"AlertTriangle","nodos":["Vencimiento","Degradación","Contaminación"]}]},"proceso":{"titulo":"Calificación de un estándar secundario","intro":"","pasos":[{"titulo":"Seleccionar el lote candidato","detalle":"Elige un lote de la sustancia de alta pureza y suficiente cantidad.","icono":"Package","evidencia":"Identificación del lote candidato."},{"titulo":"Confirmar identidad","detalle":"Compara con el primario por técnicas específicas.","icono":"Fingerprint","evidencia":"Espectros comparados."},{"titulo":"Evaluar pureza","detalle":"Determina impurezas, agua y solventes.","icono":"Search","evidencia":"Resultados de pureza."},{"titulo":"Asignar contenido","detalle":"Valora frente al primario con réplicas suficientes y calcula el contenido asignado.","icono":"Calculator","evidencia":"Cálculo con estadística."},{"titulo":"Documentar y rotular","detalle":"Emite el certificado interno con contenido, condiciones y fecha de recalificación.","icono":"Tag","evidencia":"Certificado y rótulo."},{"titulo":"Controlar el uso","detalle":"Registra cada uso y recalifica antes de la fecha definida.","icono":"CalendarClock","evidencia":"Registro de uso y recalificación."}]},"caso":{"titulo":"El estándar vencido ayer","contexto":"Al revisar los datos de una valoración, el supervisor nota que el estándar secundario usado tenía su recalificación vencida desde el día anterior. Los resultados del lote cumplen.","pregunta":"¿Qué corresponde?","opciones":[{"texto":"Aceptar: un día no cambia nada.","correcta":false,"retro":"Sin evidencia, no se sabe si el estándar sigue siendo apto. Un día o un año, la vigencia es un criterio definido."},{"texto":"Abrir una desviación, evaluar el impacto repitiendo con un estándar vigente o recalificando el estándar, y solo con evidencia continuar con la liberación.","correcta":true,"retro":"La decisión se apoya en datos, no en la intuición de que «seguramente está bien»."},{"texto":"Cambiar la fecha de recalificación en el rótulo.","correcta":false,"retro":"Modificar el rótulo sin recalificar es una falla grave de integridad."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Estándares de referencia primarios y secundarios: tipos, calificación y manejo$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Estándares de referencia primarios y secundarios: tipos, calificación y manejo$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 14. Introducción a la unidad: identidad, pureza, potencia y desempeño
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Cada técnica responde una pregunta","texto":"En la mesa del laboratorio hay un espectrofotómetro infrarrojo, un HPLC, un titulador, un disolutor y un equipo Karl Fischer. Un analista nuevo los ve como máquinas distintas. Un analista experimentado los ve como respuestas a preguntas: ¿es la sustancia correcta?, ¿qué tan pura es?, ¿cuánto activo tiene?, ¿se liberará como debe? Esta unidad organiza las técnicas alrededor de esas preguntas."},"objetivos":["Relacionar cada técnica analítica con la pregunta de calidad que responde.","Reconocer los requisitos comunes a todo ensayo: método, equipo, estándar y analista.","Ubicar las clases de la unidad dentro de una especificación de producto terminado."],"conceptos":[{"icono":"Fingerprint","termino":"Identidad","definicion":"Técnicas que confirman qué sustancia es: espectroscopia infrarroja, tiempo de retención en HPLC, espectro UV, reacciones químicas."},{"icono":"Search","termino":"Pureza","definicion":"Técnicas que detectan y cuantifican lo que no debería estar: impurezas por HPLC, solventes residuales por cromatografía de gases, agua por Karl Fischer."},{"icono":"Target","termino":"Potencia","definicion":"Técnicas que cuantifican el activo: valoraciones volumétricas, HPLC, UV-Vis, y la uniformidad entre unidades."},{"icono":"Timer","termino":"Desempeño","definicion":"Ensayos que predicen el comportamiento en el paciente, como la disolución."}],"secciones":[{"titulo":"Las preguntas detrás de cada técnica","parrafos":["Una especificación de producto terminado combina ensayos que responden cuatro preguntas: **identidad** (¿es lo que dice ser?), **pureza** (¿qué más contiene y en qué cantidad?), **potencia** (¿cuánto activo tiene cada unidad?) y **desempeño** (¿liberará el activo como se espera?). Una misma técnica puede responder varias: un HPLC confirma la identidad por tiempo de retención, cuantifica el activo y separa las impurezas.","Todo ensayo comparte requisitos: un **método** validado o verificado, un **equipo** calificado y calibrado, un **estándar** de referencia vigente, **reactivos** preparados y rotulados correctamente, y un **analista** autorizado. Si falla uno, el resultado pierde su valor aunque el número parezca correcto.","En esta unidad recorrerás la identificación, la valoración volumétrica, las impurezas según ICH Q3, la disolución, la uniformidad de unidades de dosificación, el pH y el agua por Karl Fischer, y tres técnicas instrumentales: HPLC, UV-Vis y cromatografía de gases."]}],"errores":[{"error":"Ver los ensayos como trámites intercambiables.","correccion":"Relaciona cada ensayo con la pregunta de calidad que responde."},{"error":"Ejecutar un ensayo sin verificar sus requisitos.","correccion":"Confirma método, equipo, estándar, reactivos y analista antes de empezar."}],"comprueba":[{"pregunta":"¿Qué cuatro preguntas responde la especificación?","respuesta":"Identidad, pureza, potencia y desempeño."},{"pregunta":"¿Qué requisitos comparte todo ensayo?","respuesta":"Método validado, equipo calificado, estándar vigente, reactivos correctos y analista autorizado."}],"resumen":["Cada técnica responde una **pregunta de calidad**.","Todo ensayo descansa en **método, equipo, estándar, reactivos y analista**.","Una misma técnica puede responder **varias preguntas**."],"referencias":[{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Mesa de laboratorio ilustrada con IR, HPLC, titulador y disolutor, cada uno con una etiqueta de color de la pregunta que responde.","alt":"Técnicas analíticas organizadas por la pregunta de calidad que responden"}],"keywords":["técnicas analíticas control de calidad","análisis fisicoquímico de medicamentos","identidad pureza potencia","ensayos de producto terminado"],"mapa":{"centro":"Técnicas al servicio de la calidad","ramas":[{"titulo":"Identidad","icono":"Fingerprint","nodos":["Infrarrojo","HPLC y UV","Reacciones"]},{"titulo":"Pureza","icono":"Search","nodos":["Impurezas (ICH Q3)","Solventes residuales","Agua"]},{"titulo":"Potencia","icono":"Target","nodos":["Valoración","Uniformidad de dosis"]},{"titulo":"Desempeño","icono":"Timer","nodos":["Disolución","pH y otros ensayos"]}]},"proceso":{"titulo":"Preparar un ensayo con todos sus requisitos","intro":"","pasos":[{"titulo":"Leer el método","detalle":"Revisa la versión vigente y sus requisitos de idoneidad.","icono":"BookOpen","evidencia":"Método vigente."},{"titulo":"Verificar el equipo","detalle":"Confirma calificación, calibración y verificación del día.","icono":"Cpu","evidencia":"Bitácora y rótulo de estado."},{"titulo":"Verificar estándar y reactivos","detalle":"Confirma vigencia del estándar y preparación de soluciones.","icono":"TestTube","evidencia":"Registros de preparación."},{"titulo":"Ejecutar con registro contemporáneo","detalle":"Registra pesadas, diluciones y observaciones en el momento.","icono":"ClipboardList","evidencia":"Hoja de trabajo."},{"titulo":"Calcular y revisar","detalle":"Calcula, compara con el criterio y pasa a revisión.","icono":"Calculator","evidencia":"Cálculos revisados."}]},"caso":{"titulo":"El ensayo que «faltaba»","contexto":"Un lote de tabletas cumple identificación, valoración e impurezas. El jefe de producción pregunta por qué hace falta la disolución si «ya sabemos que tiene la cantidad correcta de activo».","pregunta":"¿Qué le respondes?","opciones":[{"texto":"Que la disolución es un trámite del registro.","correcta":false,"retro":"No es un trámite: responde una pregunta distinta, la del desempeño."},{"texto":"Que la valoración dice cuánto activo hay, pero no si se liberará en el cuerpo; la disolución predice ese desempeño.","correcta":true,"retro":"Cada ensayo responde una pregunta distinta; una tableta con la cantidad correcta puede no liberar el activo."},{"texto":"Que se puede omitir si la dureza es normal.","correcta":false,"retro":"La dureza no reemplaza la disolución."}]}}$j$::jsonb;
