    v_n := v_n + 1;
  END IF;

  -- 15. Ensayos de identificación (IR y otras técnicas)
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Polvo blanco no es identidad","texto":"Muchos activos y excipientes son polvos blancos, inodoros y de aspecto idéntico. Un punto de fusión puede coincidir por casualidad entre dos sustancias distintas. Por eso las farmacopeas prefieren técnicas que generan una «huella digital» de la molécula, como el espectro infrarrojo. Confirmar la identidad es el primer y más importante ensayo de cualquier material."},"objetivos":["Explicar el principio de la identificación por espectroscopia infrarroja.","Comparar técnicas de identificación según su especificidad.","Interpretar la concordancia de un espectro con el de referencia."],"conceptos":[{"icono":"Fingerprint","termino":"Espectro infrarrojo","definicion":"Registro de la absorción de radiación infrarroja por los enlaces de la molécula. La región de huella digital es característica de cada sustancia."},{"icono":"Scan","termino":"Concordancia","definicion":"El espectro de la muestra debe mostrar las mismas bandas, en las mismas posiciones e intensidades relativas, que el del estándar en las mismas condiciones."},{"icono":"Layers","termino":"Especificidad","definicion":"Capacidad de la técnica para distinguir la sustancia de otras parecidas. IR es muy específica; un color de reacción, poco."},{"icono":"Atom","termino":"Polimorfos","definicion":"Formas cristalinas de una misma sustancia que pueden dar espectros IR distintos en estado sólido."}],"secciones":[{"titulo":"El infrarrojo como huella digital","parrafos":["Cuando una molécula recibe radiación infrarroja, sus enlaces absorben energía a frecuencias características: estiramientos de O–H, N–H, C=O y otras vibraciones. El resultado es un **espectro** con bandas propias de cada sustancia, en especial en la región de huella digital, donde pequeñas diferencias estructurales cambian el patrón. Por eso las farmacopeas usan con frecuencia la espectroscopia infrarroja como ensayo de identificación principal.","La identificación se hace por **comparación**: el espectro de la muestra debe coincidir con el del estándar de referencia registrado en las mismas condiciones (preparación en pastilla de bromuro de potasio, reflectancia total atenuada u otra que indique el método). Si el espectro de un sólido no coincide, la farmacopea suele indicar cómo tratar la muestra y el estándar (por ejemplo, disolverlos y recristalizarlos de la misma manera), porque la diferencia puede deberse a **polimorfismo** y no a otra sustancia."]},{"titulo":"Otras técnicas y su lugar","parrafos":["No todas las técnicas tienen la misma **especificidad**. El tiempo de retención en HPLC confirma la identidad cuando coincide con el del estándar en las mismas condiciones, pero dos sustancias podrían eluir juntas; por eso a menudo se combina con el espectro UV del detector de arreglo de diodos. Las reacciones químicas y los ensayos de iones (cloruros, sodio) son útiles para sales y excipientes, pero rara vez bastan solas para un activo.","Las monografías suelen pedir **dos o más** ensayos de identificación cuando ninguno es suficientemente específico por sí solo. El laboratorio debe ejecutar todos los que exige la especificación: omitir uno porque «el otro ya coincidió» es un incumplimiento."]}],"errores":[{"error":"Comparar espectros obtenidos con técnicas distintas.","correccion":"Registra muestra y estándar con la misma técnica y condiciones."},{"error":"Usar solo el punto de fusión como identidad de un activo.","correccion":"Usa técnicas específicas como el infrarrojo y los ensayos que pida la monografía."}],"comprueba":[{"pregunta":"¿Por qué el infrarrojo es muy específico?","respuesta":"Porque genera un espectro característico de cada sustancia, en especial en la región de huella digital."},{"pregunta":"¿Qué puede explicar que el espectro de un sólido no coincida con el estándar?","respuesta":"El polimorfismo; por eso el método indica tratar muestra y estándar de la misma forma."}],"resumen":["La identidad se confirma con técnicas **específicas**, como el infrarrojo.","Se compara con el estándar **en las mismas condiciones**.","Se ejecutan **todos** los ensayos de identificación exigidos."],"referencias":[{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"}],"imagenes":[{"ubicacion":"En la sección del infrarrojo","descripcion":"Dos espectros IR superpuestos (muestra y estándar) con la región de huella digital resaltada en turquesa.","alt":"Comparación de espectros infrarrojos de muestra y estándar"}],"keywords":["ensayos de identificación farmacéutica","identificación por infrarrojo","espectroscopia ir control de calidad","huella digital ir","identidad de principio activo","ftir farmacéutico"],"mapa":{"centro":"Identificar una sustancia","ramas":[{"titulo":"Muy específicas","icono":"Fingerprint","nodos":["Infrarrojo","Raman","Espectrometría de masas"]},{"titulo":"Complementarias","icono":"Layers","nodos":["Tiempo de retención HPLC","Espectro UV","Rotación óptica"]},{"titulo":"Clásicas","icono":"FlaskConical","nodos":["Reacciones químicas","Punto de fusión","Ensayos de iones"]},{"titulo":"Cuidados","icono":"AlertTriangle","nodos":["Mismas condiciones que el estándar","Polimorfismo","Humedad de la muestra"]}]},"proceso":{"titulo":"Identificación por infrarrojo","intro":"","pasos":[{"titulo":"Verificar el equipo","detalle":"Confirma la verificación del número de onda con un patrón, como una película de poliestireno.","icono":"Gauge","evidencia":"Registro de verificación del equipo."},{"titulo":"Preparar el estándar","detalle":"Prepara el estándar con la técnica indicada por el método.","icono":"TestTube","evidencia":"Registro de preparación."},{"titulo":"Preparar la muestra","detalle":"Prepara la muestra exactamente igual que el estándar.","icono":"Pipette","evidencia":"Registro de preparación."},{"titulo":"Registrar los espectros","detalle":"Obtén ambos espectros en las mismas condiciones.","icono":"Activity","evidencia":"Espectros originales."},{"titulo":"Comparar","detalle":"Verifica que las bandas coincidan en posición e intensidad relativa.","icono":"Scan","evidencia":"Comparación documentada."},{"titulo":"Concluir","detalle":"Si no coincide, sigue las instrucciones del método antes de concluir; si persiste, investiga.","icono":"CheckCircle2","evidencia":"Conclusión registrada."}]},"caso":{"titulo":"Un espectro casi igual","contexto":"El espectro IR de un lote de activo coincide con el estándar en casi todas las bandas, pero hay diferencias en la región de huella digital. El certificado del proveedor indica la misma sustancia.","pregunta":"¿Qué haces?","opciones":[{"texto":"Aprobar porque casi todas las bandas coinciden.","correcta":false,"retro":"La región de huella digital es justamente la más específica; las diferencias deben explicarse."},{"texto":"Seguir las instrucciones del método para descartar polimorfismo (tratar muestra y estándar igual y repetir); si persiste la diferencia, investigar la identidad y la forma cristalina.","correcta":true,"retro":"Puede ser un polimorfo distinto, lo que también importa porque afecta la disolución."},{"texto":"Rechazar sin más análisis.","correcta":false,"retro":"Antes de rechazar, el método indica cómo descartar diferencias por la forma cristalina."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Ensayos de identificación (IR y otras técnicas)$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Ensayos de identificación (IR y otras técnicas)$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 16. Valoración por métodos volumétricos y potenciométricos
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Una bureta y un factor olvidado","texto":"Una valoración ácido-base de un activo da 103 % durante una semana completa. Nadie había vuelto a estandarizar la solución de hidróxido de sodio desde que se preparó: había absorbido dióxido de carbono del aire y su concentración real era menor que la escrita en el rótulo. Las técnicas volumétricas son simples, pero exigen el mismo rigor que cualquier técnica instrumental."},"objetivos":["Explicar el principio de una valoración volumétrica y el cálculo del contenido.","Aplicar la estandarización de soluciones volumétricas y el ensayo en blanco.","Describir la detección potenciométrica del punto final."],"conceptos":[{"icono":"Beaker","termino":"Valoración","definicion":"Reacción de la sustancia con una solución de concentración conocida hasta el punto de equivalencia, a partir del cual se calcula su contenido."},{"icono":"Calculator","termino":"Factor de la solución","definicion":"Relación entre la concentración real de la solución volumétrica y la nominal, obtenida al estandarizarla con un patrón primario."},{"icono":"Activity","termino":"Punto final potenciométrico","definicion":"Detección del punto de equivalencia por el cambio brusco del potencial medido con un electrodo, más objetiva que un indicador de color."},{"icono":"TestTube","termino":"Ensayo en blanco","definicion":"Valoración sin muestra para corregir el consumo de reactivo debido a los solventes y reactivos."}],"secciones":[{"titulo":"Principio y soluciones volumétricas","parrafos":["En una valoración, el analito reacciona con una **solución volumétrica** de concentración conocida hasta el **punto de equivalencia**. Con el volumen consumido, la equivalencia que indica el método (cuántos miligramos de sustancia corresponden a cada mililitro de solución de una normalidad dada) y el peso de la muestra, se calcula el contenido. Existen valoraciones ácido-base, redox, complexométricas y en medio no acuoso, entre otras.","La concentración real de la solución volumétrica se determina por **estandarización** con un patrón primario, y se expresa como un **factor** respecto a la concentración nominal. Las soluciones cambian con el tiempo (el hidróxido de sodio absorbe dióxido de carbono, el tiosulfato se descompone), por eso se re-estandarizan con la frecuencia definida, se rotulan con su factor, fecha y vigencia, y se almacenan como indica el método. El caso del 103 % es un error clásico de factor."]},{"titulo":"Punto final y blanco","parrafos":["El punto final se detecta con un **indicador** de color o por **potenciometría**: un electrodo mide el potencial durante la adición del titulante y el punto final se identifica por el cambio brusco de la curva, a menudo con la primera o segunda derivada. La potenciometría es más objetiva, funciona con muestras coloreadas o turbias y permite conservar la curva como registro.","El **ensayo en blanco** corrige el consumo de titulante que no se debe al analito, sino a solventes o reactivos. Se ejecuta en las mismas condiciones y su volumen se resta del de la muestra cuando el método lo indica. Olvidarlo sesga el resultado, especialmente en valoraciones no acuosas."]}],"errores":[{"error":"Usar soluciones volumétricas sin re-estandarizar.","correccion":"Estandariza con la frecuencia definida y rotula factor y vigencia."},{"error":"Omitir el blanco.","correccion":"Ejecuta el blanco cuando el método lo indique y corrige el volumen."}],"comprueba":[{"pregunta":"¿Qué es el factor de una solución volumétrica?","respuesta":"La relación entre su concentración real, obtenida al estandarizar, y la nominal."},{"pregunta":"¿Qué ventaja tiene el punto final potenciométrico?","respuesta":"Es más objetivo, sirve con muestras coloreadas o turbias y deja la curva como registro."}],"resumen":["La valoración calcula el contenido con **volumen, equivalencia, factor y peso**.","Las soluciones se **estandarizan** y tienen vigencia.","La potenciometría y el **blanco** hacen el resultado más confiable."],"referencias":[{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OPS, Red PARF. Buenas prácticas de la OMS para laboratorios de control de calidad de productos farmacéuticos (versión en español).","url":"https://www3.paho.org/hq/dmdocuments/2011/Espanol-control-calidad-laboratorios-farmaceuticos.pdf"}],"imagenes":[{"ubicacion":"En la sección del punto final","descripcion":"Curva de valoración potenciométrica con el salto de potencial y su primera derivada marcando el punto final.","alt":"Curva de valoración potenciométrica y su punto final"}],"keywords":["valoración volumétrica farmacéutica","titulación potenciométrica","estandarización de soluciones volumétricas","factor de solución valorada","ensayo en blanco titulación","valoración no acuosa"],"mapa":{"centro":"Valorar con rigor","ramas":[{"titulo":"Tipos","icono":"Beaker","nodos":["Ácido-base","Redox","Complexométrica","No acuosa"]},{"titulo":"Solución volumétrica","icono":"Calculator","nodos":["Preparación","Estandarización con patrón primario","Factor y vigencia"]},{"titulo":"Punto final","icono":"Activity","nodos":["Indicador de color","Potenciométrico","Curva de valoración"]},{"titulo":"Cálculo","icono":"Sigma","nodos":["Volumen corregido por el blanco","Equivalencia del método","Peso de muestra"]}]},"proceso":{"titulo":"Valoración potenciométrica de un activo","intro":"","pasos":[{"titulo":"Verificar la solución volumétrica","detalle":"Confirma su factor y su vigencia; si venció, estandariza de nuevo.","icono":"Calculator","evidencia":"Registro de estandarización."},{"titulo":"Calibrar el electrodo","detalle":"Calibra o verifica el electrodo según el procedimiento.","icono":"Gauge","evidencia":"Registro de calibración."},{"titulo":"Pesar la muestra","detalle":"Pesa la cantidad indicada con balanza calibrada y verificada.","icono":"Scale","evidencia":"Impreso de la balanza."},{"titulo":"Valorar","detalle":"Disuelve y valora registrando la curva de potencial.","icono":"Activity","evidencia":"Curva de valoración."},{"titulo":"Hacer el blanco","detalle":"Repite sin muestra en las mismas condiciones.","icono":"TestTube","evidencia":"Volumen del blanco."},{"titulo":"Calcular","detalle":"Aplica la equivalencia, el factor y la corrección del blanco.","icono":"Sigma","evidencia":"Cálculo revisado."}]},"caso":{"titulo":"Una semana de 103 %","contexto":"Durante una semana, todas las valoraciones de un activo dan entre 102,8 % y 103,3 %, con límite máximo de 102,0 %. Los lotes de semanas anteriores daban alrededor de 100 %.","pregunta":"¿Qué revisas primero?","opciones":[{"texto":"El proceso de fabricación del activo.","correcta":false,"retro":"Antes de culpar al material, hay que descartar un error del laboratorio que afecte todos los análisis."},{"texto":"La solución volumétrica: su factor, su fecha de estandarización y su almacenamiento, porque un error sistemático en todos los lotes apunta a algo común del análisis.","correcta":true,"retro":"Un sesgo igual en todos los resultados sugiere una causa común: el factor de la solución es el primer sospechoso."},{"texto":"Repetir hasta obtener 100 %.","correcta":false,"retro":"Repetir sin investigar no corrige el sesgo ni cumple el manejo de resultados fuera de especificación."}]}}$j$::jsonb;
