  -- 17. Impurezas y sustancias relacionadas (ICH Q3)
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un pico pequeño que importa","texto":"En el cromatograma de un activo aparece un pico nuevo de 0,12 %. El analista lo reporta como «impureza desconocida, cumple», porque el límite de impurezas totales es 1,0 %. Pero para un activo con dosis diaria baja, una impureza desconocida por encima de 0,10 % puede exigir identificación. Las impurezas se gobiernan con umbrales, y conocerlos cambia la decisión."},"objetivos":["Clasificar las impurezas según ICH Q3: orgánicas, inorgánicas y solventes residuales.","Aplicar los umbrales de reporte, identificación y calificación de ICH Q3A.","Diferenciar impurezas del principio activo y productos de degradación del producto."],"conceptos":[{"icono":"Search","termino":"Impurezas orgánicas","definicion":"Materiales de partida, subproductos, intermedios y productos de degradación relacionados con el activo."},{"icono":"Atom","termino":"Impurezas inorgánicas","definicion":"Reactivos, catalizadores, metales y sales del proceso de síntesis."},{"icono":"Wind","termino":"Solventes residuales","definicion":"Solventes orgánicos que quedan del proceso; se controlan según ICH Q3C."},{"icono":"Ruler","termino":"Umbrales","definicion":"Reporte, identificación y calificación: niveles por encima de los cuales una impureza debe reportarse, identificarse o justificarse en seguridad."}],"secciones":[{"titulo":"Tipos de impurezas y dónde aplican las guías","parrafos":["Las guías ICH Q3 clasifican las impurezas en **orgánicas** (materiales de partida, subproductos, intermedios y productos de degradación), **inorgánicas** (reactivos, catalizadores, metales) y **solventes residuales**. ICH **Q3A** trata las impurezas del principio activo nuevo; **Q3B**, los productos de degradación en el producto terminado; **Q3C**, los solventes residuales; y otras guías de la familia tratan elementos traza e impurezas mutagénicas.","En control de calidad, las impurezas orgánicas suelen determinarse por **HPLC** con un método indicador de estabilidad, que separa el activo de sus impurezas y productos de degradación. Se cuantifican frente a un estándar del activo o de la impureza, con factores de respuesta cuando corresponda, y se comparan con los límites individuales, de impurezas desconocidas y de impurezas totales."]},{"titulo":"Los umbrales de ICH Q3A","parrafos":["ICH Q3A define tres umbrales que dependen de la dosis diaria máxima. Para principios activos con dosis diaria máxima de hasta 2 g, el **umbral de reporte** es 0,05 %; el **umbral de identificación** es 0,10 % o 1,0 mg de ingesta diaria total, lo que sea menor; y el **umbral de calificación** es 0,15 % o 1,0 mg de ingesta diaria total, lo que sea menor. Una impureza por encima del umbral de identificación debe identificarse estructuralmente; por encima del de calificación, su seguridad debe justificarse con datos.","En el caso inicial, la impureza de 0,12 % supera el umbral de identificación de 0,10 %: no basta con decir que las totales cumplen. Además, un pico nuevo que no aparecía en el historial es una señal que merece investigación. Para el producto terminado, ICH Q3B define umbrales propios para productos de degradación, también en función de la dosis."]}],"errores":[{"error":"Mirar solo las impurezas totales.","correccion":"Evalúa cada impureza frente a su límite individual y a los umbrales."},{"error":"Ajustar la integración para reducir un pico.","correccion":"Integra con parámetros definidos y deja trazabilidad de cualquier cambio."}],"comprueba":[{"pregunta":"¿Cuáles son los umbrales de ICH Q3A para una dosis diaria de hasta 2 g?","respuesta":"Reporte 0,05 %; identificación 0,10 % o 1,0 mg/día; calificación 0,15 % o 1,0 mg/día, lo que sea menor."},{"pregunta":"¿Qué guía trata los solventes residuales?","respuesta":"ICH Q3C."}],"resumen":["Impurezas **orgánicas, inorgánicas y solventes**.","Umbrales de **reporte, identificación y calificación** guían la acción.","Un pico **nuevo** siempre merece investigación."],"referencias":[{"cita":"ICH. Q3A(R2) Impurities in New Drug Substances (EMA, Step 5).","url":"https://ema.europa.eu/en/documents/scientific-guideline/ich-q-3-r2-impurities-new-drug-substances-step-5_en.pdf"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"},{"cita":"ICH. Quality Guidelines (índice oficial de las guías Q).","url":"https://www.ich.org/page/quality-guidelines"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"En la sección de umbrales","descripcion":"Regla vertical ilustrada con tres marcas (0,05 %, 0,10 %, 0,15 %) y acciones asociadas: reportar, identificar, calificar.","alt":"Umbrales de impurezas de ICH Q3A"}],"keywords":["impurezas ich q3a","umbrales de identificación de impurezas","sustancias relacionadas hplc","productos de degradación ich q3b","solventes residuales ich q3c","impurezas farmacéuticas clasificación"],"mapa":{"centro":"Impurezas según ICH Q3","ramas":[{"titulo":"Tipos","icono":"Layers","nodos":["Orgánicas","Inorgánicas","Solventes residuales"]},{"titulo":"Umbrales Q3A","icono":"Ruler","nodos":["Reporte","Identificación","Calificación"]},{"titulo":"Dónde","icono":"Pill","nodos":["Principio activo (Q3A)","Producto terminado (Q3B)","Solventes (Q3C)"]},{"titulo":"Cómo","icono":"Microscope","nodos":["HPLC con estándares","Métodos indicadores de estabilidad","Límites de la especificación"]}]},"proceso":{"titulo":"Evaluar un pico de impureza en un cromatograma","intro":"","pasos":[{"titulo":"Confirmar la idoneidad","detalle":"Verifica resolución, sensibilidad y precisión del sistema según el método.","icono":"Gauge","evidencia":"Resultados de idoneidad."},{"titulo":"Integrar con criterio","detalle":"Integra según el procedimiento, sin ajustes manuales no justificados.","icono":"Activity","evidencia":"Parámetros de integración y pista de auditoría."},{"titulo":"Cuantificar","detalle":"Calcula el porcentaje con el estándar y el factor de respuesta que indique el método.","icono":"Calculator","evidencia":"Cálculo."},{"titulo":"Comparar con umbrales","detalle":"Compara con los umbrales de reporte, identificación y calificación y con los límites de la especificación.","icono":"Ruler","evidencia":"Evaluación documentada."},{"titulo":"Comparar con el historial","detalle":"Revisa si el pico es nuevo o si aumentó frente a lotes anteriores.","icono":"LineChart","evidencia":"Tendencia de impurezas."},{"titulo":"Decidir o investigar","detalle":"Si supera umbrales o es nuevo, investiga y escala según el procedimiento.","icono":"AlertTriangle","evidencia":"Investigación o conclusión."}]},"caso":{"titulo":"El pico de 0,12 %","contexto":"En un activo con dosis diaria máxima de 500 mg aparece una impureza desconocida de 0,12 %. El límite de impurezas totales es 1,0 % y se cumple.","pregunta":"¿Cómo se interpreta?","opciones":[{"texto":"Cumple, porque las totales están bajo 1,0 %.","correcta":false,"retro":"Los límites totales no reemplazan los umbrales individuales: 0,12 % supera el umbral de identificación de 0,10 %."},{"texto":"Supera el umbral de identificación de ICH Q3A; debe compararse con la especificación de impurezas desconocidas, investigarse su origen y, si se mantiene, identificarse.","correcta":true,"retro":"Los umbrales guían la acción: identificar lo que supera 0,10 % y justificar lo que supera el de calificación."},{"texto":"Ignorarlo porque es desconocido.","correcta":false,"retro":"Desconocido es precisamente lo que exige atención cuando supera los umbrales."}]}}$j$::jsonb;
