  -- 18. Prueba de disolución
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"La tableta que no se disolvía a tiempo","texto":"Un lote de tabletas tiene el contenido correcto, la dureza normal y desintegra en minutos. Sin embargo, en la prueba de disolución apenas libera el 70 % a los 30 minutos. El paciente tomaría la dosis completa, pero su cuerpo no la absorbería como debe. La disolución es el ensayo de laboratorio que más se acerca a lo que pasa en el organismo."},"objetivos":["Explicar el propósito de la prueba de disolución y sus condiciones.","Aplicar los criterios de aceptación por etapas (S1, S2 y S3).","Reconocer las fuentes de variabilidad del ensayo."],"conceptos":[{"icono":"Timer","termino":"Disolución","definicion":"Cantidad de activo que pasa a solución en un medio y tiempo definidos. Predice la liberación del activo en el organismo."},{"icono":"Settings","termino":"Aparatos","definicion":"Los más usados son la canastilla (aparato 1) y la paleta (aparato 2), a 37 ± 0,5 °C y con velocidad de rotación definida."},{"icono":"Target","termino":"Q","definicion":"Cantidad de activo disuelto, expresada como porcentaje de lo declarado, que fija la monografía para un tiempo dado."},{"icono":"Layers","termino":"Etapas S1, S2, S3","definicion":"Criterios progresivos con 6, 12 y 24 unidades, que permiten aceptar lotes con variabilidad normal y detectar los que no liberan bien."}],"secciones":[{"titulo":"Condiciones del ensayo","parrafos":["La prueba de disolución mide qué porcentaje del activo pasa a solución en un **medio** definido (por ejemplo, ácido clorhídrico diluido o un buffer de fosfato), con un **volumen**, un **aparato**, una **velocidad** de rotación y una **temperatura** de 37 ± 0,5 °C. Los aparatos más usados son la **canastilla** (aparato 1) y la **paleta** (aparato 2). Las muestras se toman en los tiempos indicados, se filtran con un filtro validado y se cuantifican, normalmente por UV o HPLC.","El ensayo es sensible a detalles: el **medio desgasificado** (las burbujas sobre la tableta alteran la liberación), la altura y el centrado de la paleta, las vibraciones del equipo y el momento exacto del muestreo. Por eso el equipo se califica mecánicamente y, cuando aplica, se verifica su desempeño, y el procedimiento controla cada paso."]},{"titulo":"Criterios por etapas","parrafos":["Para formas de liberación inmediata, la monografía fija un valor **Q** (por ejemplo, 80 %) en un tiempo dado, y el capítulo general define los criterios por etapas. En la **etapa S1** se analizan 6 unidades y cada una debe dar al menos Q + 5 %. Si no se cumple, se pasa a la **etapa S2** con 6 unidades más: el promedio de las 12 debe ser al menos Q y ninguna unidad menor que Q − 15 %. Si no se cumple, se pasa a la **etapa S3** con 12 unidades más: el promedio de las 24 debe ser al menos Q, no más de 2 unidades pueden estar por debajo de Q − 15 % y ninguna por debajo de Q − 25 %.","Solo se concluye que el lote no cumple si falla la etapa S3. Pasar de etapa no es una investigación: es parte del procedimiento. Pero un lote que llega con frecuencia a S2 o S3 es una señal de variabilidad que conviene vigilar en las tendencias."]}],"errores":[{"error":"Usar medio sin desgasificar.","correccion":"Desgasifica según el procedimiento para evitar burbujas que alteran la liberación."},{"error":"Concluir en S1 sin pasar a las siguientes etapas.","correccion":"Aplica los criterios por etapas del capítulo general."}],"comprueba":[{"pregunta":"¿Cuál es el criterio de S1?","respuesta":"Cada una de las 6 unidades debe dar al menos Q + 5 %."},{"pregunta":"¿Cuándo se concluye que un lote no cumple disolución?","respuesta":"Cuando falla la etapa S3."}],"resumen":["La disolución **predice la liberación** del activo en el cuerpo.","Condiciones controladas: **aparato, medio, velocidad y 37 °C**.","Criterios por **etapas S1, S2 y S3**."],"referencias":[{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"}],"imagenes":[{"ubicacion":"En la sección de condiciones","descripcion":"Vaso de disolución ilustrado con paleta, tableta en el fondo, termómetro a 37 °C y cánula de muestreo.","alt":"Aparato de disolución con paleta"},{"ubicacion":"En la sección de criterios","descripcion":"Escalera de tres peldaños (S1, S2, S3) con el número de unidades y el criterio de cada uno.","alt":"Criterios por etapas de la prueba de disolución"}],"keywords":["prueba de disolución","disolución usp 711","criterios s1 s2 s3 disolución","aparato 2 paleta disolución","q en disolución","ensayo de disolución tabletas"],"mapa":{"centro":"La prueba de disolución","ramas":[{"titulo":"Condiciones","icono":"Settings","nodos":["Aparato y velocidad","Medio y volumen","37 ± 0,5 °C"]},{"titulo":"Criterios","icono":"Target","nodos":["S1: cada unidad ≥ Q+5 %","S2: promedio de 12 ≥ Q","S3: promedio de 24 ≥ Q"]},{"titulo":"Variabilidad","icono":"AlertTriangle","nodos":["Desgasificación del medio","Centrado y altura","Vibraciones"]},{"titulo":"Cuantificación","icono":"Microscope","nodos":["UV o HPLC","Filtración validada","Estándar vigente"]}]},"proceso":{"titulo":"Ejecutar una disolución con aparato 2","intro":"","pasos":[{"titulo":"Preparar y desgasificar el medio","detalle":"Prepara el medio indicado y desgasifícalo según el procedimiento.","icono":"Droplets","evidencia":"Registro de preparación del medio."},{"titulo":"Verificar el equipo","detalle":"Confirma altura y centrado de las paletas, velocidad y temperatura.","icono":"Gauge","evidencia":"Verificación del disolutor."},{"titulo":"Introducir las unidades","detalle":"Coloca una unidad por vaso e inicia el tiempo.","icono":"Pill","evidencia":"Hora de inicio."},{"titulo":"Muestrear","detalle":"Toma la muestra en el tiempo indicado, de la zona definida, y filtra.","icono":"Pipette","evidencia":"Registro de tiempos de muestreo."},{"titulo":"Cuantificar","detalle":"Analiza las muestras frente al estándar.","icono":"Microscope","evidencia":"Datos analíticos."},{"titulo":"Evaluar por etapas","detalle":"Aplica S1 y, si no cumple, continúa a S2 y S3.","icono":"Layers","evidencia":"Evaluación documentada."}]},"caso":{"titulo":"Seis unidades en primera etapa","contexto":"Q = 80 % a 30 minutos. En S1 se obtienen 88 %, 86 %, 83 %, 90 %, 87 % y 84 %.","pregunta":"¿Cuál es la conclusión?","opciones":[{"texto":"Cumple S1.","correcta":false,"retro":"En S1 cada unidad debe dar al menos Q + 5 % = 85 %; hay dos unidades por debajo (83 % y 84 %)."},{"texto":"No cumple S1: se continúa a S2 con seis unidades más y se evalúa el promedio de 12 y los valores individuales.","correcta":true,"retro":"El procedimiento prevé la siguiente etapa antes de concluir."},{"texto":"No cumple: se rechaza el lote.","correcta":false,"retro":"No se puede rechazar sin completar las etapas que define el capítulo general."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Prueba de disolución$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Prueba de disolución$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 19. Uniformidad de unidades de dosificación
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El promedio perfecto que escondía un problema","texto":"La valoración de un lote de tabletas de baja dosis da 100,2 %: perfecto. Pero al analizar las tabletas una por una, algunas tienen 85 % y otras 115 %. El promedio esconde que un paciente puede recibir mucho menos o mucho más de lo indicado. La uniformidad de unidades de dosificación mide lo que el promedio no ve."},"objetivos":["Diferenciar los métodos de uniformidad de contenido y variación de peso.","Calcular e interpretar el valor de aceptación (AV).","Aplicar los criterios de las etapas L1 y L2."],"conceptos":[{"icono":"Target","termino":"Uniformidad de contenido","definicion":"Valoración individual de cada unidad. Se exige cuando el activo es una fracción pequeña de la unidad o la dosis es baja."},{"icono":"Scale","termino":"Variación de peso","definicion":"Estimación del contenido de cada unidad a partir de su peso y del contenido promedio, aplicable cuando el activo es una fracción alta y homogénea."},{"icono":"Calculator","termino":"Valor de aceptación (AV)","definicion":"Índice que combina la desviación del promedio frente al valor de referencia y la dispersión entre unidades."},{"icono":"Layers","termino":"L1 y L2","definicion":"Etapas: con 10 unidades, AV ≤ 15,0; si no, con 30 unidades, AV ≤ 15,0 y ninguna unidad fuera de ±25 % del valor de referencia."}],"secciones":[{"titulo":"Dos métodos para una misma pregunta","parrafos":["La uniformidad de unidades de dosificación verifica que cada unidad contenga una cantidad de activo cercana a la declarada. La farmacopea admite dos métodos. La **uniformidad de contenido** valora cada unidad individualmente y se exige, por ejemplo, cuando la dosis es baja o el activo representa una fracción pequeña del peso de la unidad, porque allí la mezcla puede no ser homogénea. La **variación de peso** estima el contenido de cada unidad a partir de su peso y del contenido promedio del lote, y aplica cuando el activo es una fracción alta y homogénea, según los criterios del capítulo general.","En el caso inicial, un activo en dosis baja exige uniformidad de contenido: el promedio de 100,2 % no dice nada sobre unidades de 85 % y 115 %."]},{"titulo":"El valor de aceptación y las etapas","parrafos":["El resultado se evalúa con el **valor de aceptación (AV)**, que combina cuánto se aleja el promedio del valor de referencia y cuánta dispersión hay entre unidades (a mayor desviación estándar, mayor AV). En la etapa **L1** se analizan 10 unidades y el lote cumple si el AV es menor o igual a 15,0. Si no cumple, en la etapa **L2** se analizan 20 unidades más: el AV de las 30 debe ser menor o igual a 15,0 y ninguna unidad puede estar fuera de ±25 % del valor de referencia.","Una falla de uniformidad apunta casi siempre al proceso: mezcla insuficiente, **segregación** del polvo durante el transporte o en la tolva, o variación de peso en la compresión. Por eso, en la validación del proceso se estudia la uniformidad de la mezcla y de las unidades a lo largo del lote, y en rutina se vigila la tendencia del AV."]}],"errores":[{"error":"Usar variación de peso donde corresponde uniformidad de contenido.","correccion":"Aplica los criterios del capítulo general para elegir el método."},{"error":"Mirar solo el promedio.","correccion":"La dispersión entre unidades es lo que mide este ensayo."}],"comprueba":[{"pregunta":"¿Cuál es el criterio de L1?","respuesta":"Con 10 unidades, AV ≤ 15,0."},{"pregunta":"¿Qué agrega L2?","respuesta":"Con 30 unidades, AV ≤ 15,0 y ninguna unidad fuera de ±25 % del valor de referencia."}],"resumen":["La uniformidad mide **cada unidad**, no el promedio.","El **AV** combina desviación del promedio y dispersión.","Etapas **L1 (10)** y **L2 (30)**; las fallas suelen venir del proceso."],"referencias":[{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"FDA. Process Validation: General Principles and Practices (2011).","url":"https://www.fda.gov/media/71021/download"}],"imagenes":[{"ubicacion":"En la sección de métodos","descripcion":"Diez tabletas ilustradas con porcentajes distintos sobre cada una y una línea de promedio, para mostrar cómo el promedio esconde la dispersión.","alt":"Dispersión de contenido entre tabletas frente al promedio"}],"keywords":["uniformidad de unidades de dosificación","uniformidad de contenido","variación de peso tabletas","valor de aceptación av usp 905","criterios l1 l2 uniformidad","uniformidad de dosis"],"mapa":{"centro":"Que cada unidad tenga la dosis","ramas":[{"titulo":"Métodos","icono":"Target","nodos":["Uniformidad de contenido","Variación de peso","Cuándo aplica cada uno"]},{"titulo":"Cálculo","icono":"Calculator","nodos":["Promedio","Desviación estándar","Valor de aceptación"]},{"titulo":"Etapas","icono":"Layers","nodos":["L1: 10 unidades, AV ≤ 15,0","L2: 30 unidades, AV ≤ 15,0","Ninguna fuera de ±25 %"]},{"titulo":"Causas de falla","icono":"AlertTriangle","nodos":["Mezcla no homogénea","Segregación","Variación de peso"]}]},"proceso":{"titulo":"Uniformidad de contenido en tabletas de baja dosis","intro":"","pasos":[{"titulo":"Seleccionar las unidades","detalle":"Toma unidades representativas del lote según el plan de muestreo.","icono":"Sigma","evidencia":"Registro de muestreo."},{"titulo":"Valorar 10 unidades","detalle":"Analiza cada unidad por separado con el método validado.","icono":"FlaskConical","evidencia":"Resultados individuales."},{"titulo":"Calcular el AV","detalle":"Calcula promedio, desviación estándar y valor de aceptación.","icono":"Calculator","evidencia":"Cálculo del AV."},{"titulo":"Evaluar L1","detalle":"Si AV ≤ 15,0, cumple; si no, pasa a L2.","icono":"Layers","evidencia":"Evaluación L1."},{"titulo":"Evaluar L2","detalle":"Analiza 20 unidades más y evalúa AV de 30 y el límite de ±25 %.","icono":"Target","evidencia":"Evaluación L2."},{"titulo":"Analizar tendencias","detalle":"Registra el AV para detectar cambios en el proceso.","icono":"LineChart","evidencia":"Tendencia del AV."}]},"caso":{"titulo":"Un AV de 16,8 en L1","contexto":"En L1, el AV de un lote es 16,8. El promedio es 99,5 % y la dispersión es más alta que en lotes anteriores.","pregunta":"¿Qué corresponde?","opciones":[{"texto":"Rechazar el lote.","correcta":false,"retro":"No cumplir L1 no significa no cumplir: se continúa a L2."},{"texto":"Continuar a L2 con 20 unidades más y evaluar; además, informar a producción que la dispersión aumentó para revisar mezcla y compresión.","correcta":true,"retro":"Se completa el procedimiento y se usa la señal de dispersión para prevenir problemas."},{"texto":"Repetir L1 con otras 10 unidades.","correcta":false,"retro":"El procedimiento no prevé repetir L1; prevé ampliar a L2."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Uniformidad de unidades de dosificación$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Uniformidad de unidades de dosificación$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
