    v_n := v_n + 1;
  END IF;

  -- 20. Ensayos generales: pH y determinación de agua (Karl Fischer)
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Dos medidas que parecen fáciles","texto":"El pH de un jarabe da 5,9 un día y 6,4 al siguiente con la misma muestra. El electrodo no se había calibrado con soluciones que encerraran el valor medido. El contenido de agua de un activo higroscópico sube porque el frasco se abrió en un día húmedo antes de pesar. El pH y el agua son ensayos cotidianos, pero sus errores son silenciosos y frecuentes."},"objetivos":["Aplicar la calibración del pH-metro con buffers que encierren el valor medido.","Explicar el principio de la determinación de agua por Karl Fischer.","Elegir entre Karl Fischer volumétrico y coulométrico."],"conceptos":[{"icono":"Gauge","termino":"pH","definicion":"Medida de la acidez o basicidad. Afecta la estabilidad, la solubilidad y la tolerancia del producto."},{"icono":"Ruler","termino":"Calibración del pH-metro","definicion":"Con al menos dos soluciones amortiguadoras de referencia cuyo pH encierre el valor esperado, a temperatura controlada."},{"icono":"Droplets","termino":"Karl Fischer","definicion":"Reacción específica del agua con yodo y dióxido de azufre en presencia de una base y un alcohol. Mide agua, no otros volátiles."},{"icono":"Zap","termino":"Volumétrico y coulométrico","definicion":"El volumétrico añade un reactivo titulado y sirve para contenidos medios y altos; el coulométrico genera el yodo eléctricamente y es ideal para trazas."}],"secciones":[{"titulo":"pH: calibrar bien","parrafos":["El pH se mide con un electrodo de vidrio y un medidor que se **calibra** con soluciones amortiguadoras de referencia. La práctica correcta es usar al menos dos buffers cuyo pH **encierre** el valor esperado de la muestra, a la misma temperatura (o con compensación de temperatura), y verificar la pendiente del electrodo. Los buffers tienen vigencia y no se reutilizan después de usarlos.","El electrodo se mantiene hidratado y limpio, se enjuaga entre mediciones y se espera a que la lectura se estabilice. En el caso inicial, una calibración con buffers que no encerraban el valor y un electrodo lento explican la variación. El pH importa porque afecta la estabilidad del activo, la eficacia de los conservantes y la tolerancia en la piel o en el ojo."]},{"titulo":"Karl Fischer: medir solo agua","parrafos":["La determinación de agua por **Karl Fischer** se basa en una reacción específica del agua con yodo y dióxido de azufre en presencia de una base y un alcohol. A diferencia de la **pérdida por secado**, que mide todo lo que se evapora en las condiciones del ensayo, Karl Fischer mide **solo agua**. Por eso los dos resultados no son intercambiables.","En la versión **volumétrica**, se añade un reactivo cuyo **factor** (miligramos de agua por mililitro) se determina con un patrón; es adecuada para contenidos medios y altos. En la **coulométrica**, el yodo se genera eléctricamente y es ideal para **trazas** de agua. En ambos casos se controla la deriva del sistema, se protege la muestra de la humedad ambiental y se pesa con rapidez. Para muestras que no se disuelven o que reaccionan con el reactivo, se usa un horno que libera el agua hacia la celda."]}],"errores":[{"error":"Calibrar con buffers que no encierran el valor medido.","correccion":"Usa al menos dos buffers que encierren el pH esperado."},{"error":"Comparar Karl Fischer con pérdida por secado.","correccion":"Son ensayos distintos: usa el que pide la especificación."}],"comprueba":[{"pregunta":"¿Qué mide Karl Fischer que no mide la pérdida por secado?","respuesta":"Mide específicamente agua; la pérdida por secado mide todos los volátiles."},{"pregunta":"¿Cuándo se prefiere Karl Fischer coulométrico?","respuesta":"Para contenidos de agua muy bajos (trazas)."}],"resumen":["El pH-metro se calibra con buffers que **encierran** el valor.","Karl Fischer mide **solo agua**.","Volumétrico para contenidos medios y altos; **coulométrico para trazas**."],"referencias":[{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"}],"imagenes":[{"ubicacion":"En la sección de Karl Fischer","descripcion":"Celda de Karl Fischer ilustrada con electrodo, bureta y entrada de muestra, en colores de marca.","alt":"Equipo de titulación Karl Fischer"}],"keywords":["determinación de agua karl fischer","karl fischer volumétrico y coulométrico","calibración de ph metro","medición de ph farmacéutico","pérdida por secado vs karl fischer"],"mapa":{"centro":"Dos ensayos cotidianos","ramas":[{"titulo":"pH","icono":"Gauge","nodos":["Calibrar con buffers que encierren el valor","Controlar temperatura","Electrodo en buen estado"]},{"titulo":"Karl Fischer","icono":"Droplets","nodos":["Reacción específica del agua","Factor del reactivo","Blanco y deriva"]},{"titulo":"Elegir técnica","icono":"Zap","nodos":["Volumétrico: contenidos medios y altos","Coulométrico: trazas"]},{"titulo":"Errores comunes","icono":"AlertTriangle","nodos":["Muestra expuesta a humedad","Buffers vencidos","Agitación insuficiente"]}]},"proceso":{"titulo":"Determinación de agua por Karl Fischer volumétrico","intro":"","pasos":[{"titulo":"Acondicionar la celda","detalle":"Lleva la celda a punto final y verifica que la deriva sea estable y baja.","icono":"Settings","evidencia":"Registro de deriva."},{"titulo":"Determinar el factor","detalle":"Titula un patrón de agua y calcula el factor del reactivo.","icono":"Calculator","evidencia":"Registro del factor."},{"titulo":"Pesar la muestra rápido","detalle":"Pesa e introduce la muestra minimizando su exposición al aire.","icono":"Scale","evidencia":"Peso registrado."},{"titulo":"Titular","detalle":"Titula hasta el punto final detectado por el electrodo.","icono":"Droplets","evidencia":"Volumen consumido."},{"titulo":"Calcular","detalle":"Calcula el porcentaje de agua con el factor y el peso.","icono":"Sigma","evidencia":"Cálculo revisado."}]},"caso":{"titulo":"Agua alta en un día de lluvia","contexto":"El contenido de agua de un activo higroscópico da 0,9 % cuando el límite es 0,5 %. El frasco de muestra estuvo abierto varios minutos en el área de pesaje en un día muy húmedo.","pregunta":"¿Qué haces?","opciones":[{"texto":"Reportar 0,9 % y rechazar.","correcta":false,"retro":"Antes de concluir, se investiga si hubo un error de laboratorio evidente, como la exposición de la muestra."},{"texto":"Iniciar la investigación de resultado fuera de especificación: documentar la exposición a la humedad como posible causa de laboratorio y, solo si se demuestra, invalidar y repetir con la técnica correcta.","correcta":true,"retro":"Un resultado fuera de especificación se investiga; una causa de laboratorio se demuestra, no se supone."},{"texto":"Secar la muestra y repetir.","correcta":false,"retro":"Secar alteraría la muestra; además, cualquier repetición debe ir dentro de la investigación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Ensayos generales: pH y determinación de agua (Karl Fischer)$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Ensayos generales: pH y determinación de agua (Karl Fischer)$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
