  -- 22. Espectrofotometría UV-Vis
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Una absorbancia de 1,8","texto":"Una analista mide una solución y obtiene una absorbancia de 1,8. Calcula el contenido y obtiene 92 %. Al diluir la muestra a la mitad y medir de nuevo, el resultado sube a 99 %. A absorbancias altas, la relación entre señal y concentración deja de ser lineal. La espectrofotometría UV-Vis es rápida y útil, pero solo si se trabaja dentro de su zona confiable."},"objetivos":["Aplicar la ley de Lambert-Beer y sus límites.","Describir la calificación de un espectrofotómetro.","Reconocer los usos y limitaciones del UV-Vis en control de calidad."],"conceptos":[{"icono":"Sun","termino":"Ley de Lambert-Beer","definicion":"A = ε · b · c: la absorbancia es proporcional a la absortividad, al paso óptico y a la concentración, dentro de un rango."},{"icono":"LineChart","termino":"Zona lineal","definicion":"Rango de absorbancias en el que la relación es lineal; fuera de él, la respuesta se curva."},{"icono":"Gauge","termino":"Calificación del equipo","definicion":"Exactitud de longitud de onda, exactitud fotométrica, luz parásita y resolución, verificadas con patrones."},{"icono":"AlertTriangle","termino":"Especificidad limitada","definicion":"Todo lo que absorbe a esa longitud de onda contribuye a la señal, incluidos excipientes o productos de degradación."}],"secciones":[{"titulo":"Principio y zona confiable","parrafos":["La espectrofotometría UV-Vis mide cuánta luz absorbe una solución a una longitud de onda. Según la **ley de Lambert-Beer**, la absorbancia (A) es proporcional a la absortividad de la sustancia (ε), al paso óptico de la celda (b) y a la concentración (c). Con un estándar de concentración conocida medido en las mismas condiciones, se calcula la concentración de la muestra.","La relación es lineal solo dentro de un **rango**. A absorbancias altas, la luz parásita y otros efectos hacen que la respuesta se curve, como en el caso inicial; por eso los métodos fijan concentraciones de trabajo que caen en la zona validada y, si una muestra da una absorbancia fuera de ella, se diluye según el procedimiento. Se mide frente a un **blanco** del solvente, con celdas limpias de material adecuado (cuarzo en el ultravioleta)."]},{"titulo":"Calificación y limitaciones","parrafos":["El espectrofotómetro se califica y se verifica con patrones: **exactitud de longitud de onda**, **exactitud fotométrica**, **luz parásita** y resolución, según la farmacopea y el procedimiento del laboratorio. Un equipo con la longitud de onda desplazada puede medir en el flanco del pico de absorción y dar resultados inestables.","Su principal limitación es la **especificidad**: todo lo que absorbe a esa longitud de onda suma a la señal. Por eso el UV-Vis se usa en valoraciones de productos simples, en la cuantificación de muestras de disolución cuando el método está validado para ello, y como apoyo de identidad por el espectro; mientras que para impurezas o productos de degradación se prefieren técnicas separativas como el HPLC."]}],"errores":[{"error":"Medir absorbancias fuera del rango validado.","correccion":"Diluye para trabajar en la zona lineal del método."},{"error":"Usar celdas de vidrio en el ultravioleta.","correccion":"Usa cuarzo en el ultravioleta y celdas limpias y emparejadas."}],"comprueba":[{"pregunta":"¿Qué dice la ley de Lambert-Beer?","respuesta":"Que la absorbancia es proporcional a la absortividad, al paso óptico y a la concentración, dentro de un rango."},{"pregunta":"¿Cuál es la principal limitación del UV-Vis?","respuesta":"Su especificidad: todo lo que absorbe a esa longitud de onda contribuye a la señal."}],"resumen":["UV-Vis cuantifica con **A = ε · b · c** dentro de la zona lineal.","El equipo se **califica** en longitud de onda, absorbancia y luz parásita.","Su punto débil es la **especificidad** en matrices complejas."],"referencias":[{"cita":"Universitat de València. Absorbancia: cuadernillo de teoría de espectrofotometría.","url":"https://www.uv.es/qflab/2023_24/descargas/cuadernillos/qf1/castellano/Teoria/Absorbancia.pdf"},{"cita":"ICH. Q2(R2) Validation of Analytical Procedures (2023).","url":"https://database.ich.org/sites/default/files/ICH_Q2%28R2%29_Guideline_2023_1130.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"En la sección de principio","descripcion":"Haz de luz ilustrado atravesando una celda con solución, con la intensidad que disminuye y la ecuación A = ε · b · c.","alt":"Principio de la espectrofotometría UV-Vis y la ley de Lambert-Beer"}],"keywords":["espectrofotometría uv vis farmacéutica","ley de lambert beer","valoración por uv","calificación de espectrofotómetro","absorbancia y concentración","uv vis control de calidad"],"mapa":{"centro":"Medir con luz","ramas":[{"titulo":"Principio","icono":"Sun","nodos":["A = ε · b · c","Longitud de onda de máxima absorción","Blanco del solvente"]},{"titulo":"Zona confiable","icono":"LineChart","nodos":["Absorbancias del rango validado","Diluir si es alta","Celdas limpias y adecuadas"]},{"titulo":"Equipo","icono":"Gauge","nodos":["Longitud de onda","Exactitud fotométrica","Luz parásita"]},{"titulo":"Usos","icono":"Microscope","nodos":["Valoración simple","Disolución","Identificación por espectro"]}]},"proceso":{"titulo":"Valoración por UV-Vis","intro":"","pasos":[{"titulo":"Verificar el equipo","detalle":"Confirma la calificación y la verificación de longitud de onda y absorbancia.","icono":"Gauge","evidencia":"Registro de verificación."},{"titulo":"Preparar blanco, estándar y muestra","detalle":"Usa el mismo solvente y diluciones del método.","icono":"Beaker","evidencia":"Registros de preparación."},{"titulo":"Ajustar con el blanco","detalle":"Lleva el equipo a cero con el blanco del solvente.","icono":"Settings","evidencia":"Lectura del blanco."},{"titulo":"Medir estándar y muestra","detalle":"Mide a la longitud de onda indicada, en celdas limpias.","icono":"Sun","evidencia":"Lecturas registradas."},{"titulo":"Verificar la zona lineal","detalle":"Confirma que las absorbancias estén dentro del rango validado.","icono":"LineChart","evidencia":"Verificación anotada."},{"titulo":"Calcular","detalle":"Calcula el contenido con las absorbancias y las diluciones.","icono":"Calculator","evidencia":"Cálculo revisado."}]},"caso":{"titulo":"Un placebo que absorbe","contexto":"Un laboratorio quiere valorar por UV un jarabe con varios excipientes coloreados, usando el método simple de la materia prima.","pregunta":"¿Qué riesgo hay?","opciones":[{"texto":"Ninguno: si el activo absorbe, el método funciona.","correcta":false,"retro":"Los excipientes coloreados pueden absorber a la misma longitud de onda y sumar señal."},{"texto":"Falta de especificidad: hay que demostrar con el placebo que los excipientes no interfieren o usar un método separativo validado para el producto.","correcta":true,"retro":"La especificidad se demuestra; en matrices complejas suele preferirse el HPLC."},{"texto":"Basta con restar el blanco del solvente.","correcta":false,"retro":"El blanco del solvente no corrige la absorción de los excipientes de la muestra."}]}}$j$::jsonb;
