  -- 23. Cromatografía de gases (CG) y solventes residuales
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Lo que quedó de la síntesis","texto":"Para fabricar un activo se usan solventes: metanol, acetona, diclorometano. Al final del proceso se secan, pero algo siempre queda. Algunos son poco tóxicos; otros, como el benceno, deben evitarse. Medir cuánto queda de cada uno es la tarea de la cromatografía de gases, y decidir cuánto es aceptable es la tarea de la guía ICH Q3C."},"objetivos":["Explicar el principio de la cromatografía de gases con muestreo por espacio de cabeza.","Aplicar la clasificación de solventes residuales de ICH Q3C.","Interpretar un resultado de solventes frente a sus límites."],"conceptos":[{"icono":"Wind","termino":"Cromatografía de gases","definicion":"Separación de compuestos volátiles arrastrados por un gas a través de una columna; cada uno sale en un tiempo de retención propio."},{"icono":"FlaskRound","termino":"Espacio de cabeza","definicion":"Técnica que calienta la muestra en un vial cerrado y analiza el vapor que contiene los solventes, sin inyectar la matriz."},{"icono":"Flame","termino":"Detector de ionización de llama","definicion":"Detector habitual para solventes orgánicos: sensible y de respuesta amplia."},{"icono":"Layers","termino":"Clases de ICH Q3C","definicion":"Clase 1: solventes a evitar; clase 2: solventes a limitar según su exposición diaria permitida; clase 3: solventes de baja toxicidad."}],"secciones":[{"titulo":"Cómo se miden","parrafos":["La **cromatografía de gases** separa compuestos volátiles arrastrados por un gas portador a través de una columna. Para solventes residuales se usa con frecuencia el muestreo por **espacio de cabeza**: la muestra se disuelve o dispersa en un vial cerrado, se calienta y se inyecta solo el vapor, que contiene los solventes, sin introducir la matriz no volátil al equipo. El **detector de ionización de llama** es el más común para solventes orgánicos.","Como en el HPLC, la corrida exige **idoneidad del sistema** (por ejemplo, resolución entre solventes críticos y precisión) y se cuantifica frente a estándares de los solventes de interés. La farmacopea describe procedimientos generales de identificación y cuantificación de solventes residuales que deben verificarse con la matriz de cada producto."]},{"titulo":"Las clases de ICH Q3C","parrafos":["ICH Q3C clasifica los solventes por su riesgo. Los de **clase 1** deben **evitarse** por ser cancerígenos conocidos o sospechados o dañinos para el ambiente, como el benceno; solo se aceptan si su uso es inevitable y está justificado, con límites muy bajos. Los de **clase 2** deben **limitarse**: cada uno tiene una exposición diaria permitida y un límite de concentración asociado; ejemplos son el metanol, el diclorometano o el acetonitrilo. Los de **clase 3** tienen baja toxicidad, como el etanol o la acetona, y en general se aceptan hasta 0,5 % sin justificación adicional.","La especificación del activo o del producto incluye los solventes que se usan o pueden estar presentes según el proceso. Si un fabricante cambia su ruta de síntesis y usa un solvente nuevo, la especificación y el método deben revisarse: un solvente que no se busca no se encuentra."]}],"errores":[{"error":"Buscar solo los solventes de siempre.","correccion":"Revisa la especificación cuando cambia el proceso del proveedor."},{"error":"Tratar todos los solventes con el mismo límite.","correccion":"Aplica la clase y el límite de ICH Q3C para cada solvente."}],"comprueba":[{"pregunta":"¿Qué ventaja tiene el espacio de cabeza?","respuesta":"Analiza solo el vapor con los solventes, sin introducir la matriz no volátil al equipo."},{"pregunta":"¿Qué caracteriza a los solventes de clase 3?","respuesta":"Baja toxicidad; en general se aceptan hasta 0,5 % sin justificación adicional."}],"resumen":["La CG con **espacio de cabeza** mide solventes residuales.","ICH Q3C: **clase 1 evitar, clase 2 limitar, clase 3 baja toxicidad**.","Si cambia el proceso, **cambia lo que hay que buscar**."],"referencias":[{"cita":"ICH. Quality Guidelines (índice oficial de las guías Q).","url":"https://www.ich.org/page/quality-guidelines"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"En la sección de técnica","descripcion":"Vial de espacio de cabeza ilustrado con muestra en el fondo y vapor arriba, conectado a una columna en un horno y a un detector de llama.","alt":"Cromatografía de gases con muestreo por espacio de cabeza"}],"keywords":["cromatografía de gases farmacéutica","solventes residuales ich q3c","clases de solventes residuales","headspace gc solventes","espacio de cabeza cromatografía","usp 467 solventes residuales"],"mapa":{"centro":"Solventes residuales","ramas":[{"titulo":"Técnica","icono":"Wind","nodos":["Cromatografía de gases","Espacio de cabeza","Detector de ionización de llama"]},{"titulo":"Clase 1","icono":"XCircle","nodos":["Evitar","Ejemplo: benceno","Solo si es inevitable y justificado"]},{"titulo":"Clase 2","icono":"AlertTriangle","nodos":["Limitar","Exposición diaria permitida","Ejemplos: metanol, diclorometano"]},{"titulo":"Clase 3","icono":"CheckCircle2","nodos":["Baja toxicidad","Hasta 0,5 % sin justificación","Ejemplos: etanol, acetona"]}]},"proceso":{"titulo":"Análisis de solventes residuales por espacio de cabeza","intro":"","pasos":[{"titulo":"Identificar los solventes a buscar","detalle":"Revisa el proceso de síntesis y la especificación para saber qué solventes pueden estar.","icono":"Search","evidencia":"Lista de solventes del proceso."},{"titulo":"Preparar estándares","detalle":"Prepara soluciones estándar de cada solvente a sus límites.","icono":"TestTube","evidencia":"Registro de preparación."},{"titulo":"Preparar viales","detalle":"Pesa la muestra en el vial, añade el diluyente y sella.","icono":"FlaskRound","evidencia":"Pesos y registro."},{"titulo":"Verificar idoneidad","detalle":"Evalúa resolución y precisión del sistema.","icono":"Gauge","evidencia":"Resultados de idoneidad."},{"titulo":"Analizar y cuantificar","detalle":"Corre la secuencia y calcula cada solvente frente a su estándar.","icono":"Calculator","evidencia":"Cromatogramas y cálculos."},{"titulo":"Comparar con límites","detalle":"Evalúa cada solvente frente a su límite según su clase y la especificación.","icono":"Layers","evidencia":"Evaluación documentada."}]},"caso":{"titulo":"Un solvente nuevo en el certificado","contexto":"El certificado de un nuevo lote de activo menciona tolueno como solvente residual. Tu especificación y tu método solo buscan metanol y acetona.","pregunta":"¿Qué haces?","opciones":[{"texto":"Aprobar: tu método no detecta tolueno.","correcta":false,"retro":"Que el método no lo busque no significa que no esté."},{"texto":"Gestionar el cambio con el proveedor: confirmar el cambio de proceso, incluir el tolueno (clase 2) en la especificación, verificar el método para detectarlo y analizar el lote antes de aprobar.","correcta":true,"retro":"Un solvente nuevo implica un cambio de proceso del proveedor y una revisión de la especificación."},{"texto":"Aceptar el valor del certificado sin más.","correcta":false,"retro":"El cambio debe evaluarse y el solvente controlarse con un método propio verificado."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Cromatografía de gases (CG) y solventes residuales$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Cromatografía de gases (CG) y solventes residuales$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 24. Introducción a la unidad: calidad microbiológica y estabilidad en el tiempo
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Un jarabe que cumplía el día de su liberación","texto":"Un jarabe sale del laboratorio cumpliendo todo: contenido, pH, recuento microbiano. Un año después, en la casa de un paciente en tierra caliente, el frasco abierto muestra hongos y el contenido del activo bajó. Nada de eso se veía el día de la liberación. Esta unidad trata de dos preguntas que el análisis inicial no responde: ¿está libre de microorganismos dañinos? y ¿seguirá cumpliendo durante toda su vida útil?"},"objetivos":["Explicar por qué la calidad microbiológica se controla aun en productos no estériles.","Relacionar la estabilidad con la vida útil y las condiciones climáticas.","Ubicar los ensayos microbiológicos y de estabilidad de la unidad."],"conceptos":[{"icono":"Bug","termino":"Calidad microbiológica","definicion":"Límites de microorganismos en productos no estériles y ausencia total en productos estériles, según su vía de administración."},{"icono":"CalendarClock","termino":"Estabilidad","definicion":"Capacidad del producto de mantener sus especificaciones durante su vida útil en las condiciones de almacenamiento declaradas."},{"icono":"Thermometer","termino":"Condiciones climáticas","definicion":"Temperatura y humedad del lugar donde se comercializa el producto, que definen las condiciones de los estudios de estabilidad."},{"icono":"ShieldCheck","termino":"Aptitud del método","definicion":"En microbiología, demostrar que el método recupera microorganismos en presencia del producto, que puede tener actividad antimicrobiana."}],"secciones":[{"titulo":"Microbiología: no solo para estériles","parrafos":["Los productos **no estériles**, como tabletas, jarabes o cremas, no necesitan estar libres de microorganismos, pero sí deben cumplir **límites** según su vía de administración y estar libres de **microorganismos específicos** que representen un riesgo, como Escherichia coli en productos orales. Los productos **estériles** deben estar libres de microorganismos viables y, en el caso de los parenterales, controlar las **endotoxinas**.","Un requisito común a todos los ensayos microbiológicos es la **aptitud del método**: demostrar que, en presencia del producto, el método recupera los microorganismos. Muchos productos tienen conservantes o activos con actividad antimicrobiana que pueden ocultar una contaminación si no se neutralizan."]},{"titulo":"Estabilidad: la calidad en el tiempo","parrafos":["La **estabilidad** demuestra que el producto conserva sus especificaciones durante su vida útil en las condiciones de almacenamiento declaradas, en el envase en que se comercializa. Los estudios siguen la guía ICH Q1A y la guía de la OMS (TRS 1010, Anexo 10), y en Colombia la Resolución 3157 de 2018 y su modificación, la Resolución 1839 de 2020, para medicamentos de síntesis química. Las condiciones dependen de la **zona climática**: Colombia se trabaja con las condiciones de la zona IVb, cálida y muy húmeda.","En esta unidad verás los recuentos microbianos, la ausencia de microorganismos específicos, la prueba de esterilidad, las endotoxinas, el diseño de estudios de estabilidad y la zona climática IVb con la normativa colombiana."]}],"errores":[{"error":"Pensar que la microbiología solo aplica a estériles.","correccion":"Los no estériles tienen límites y microorganismos específicos según su vía."},{"error":"Asumir que lo que cumple al liberar cumplirá siempre.","correccion":"La estabilidad demuestra el cumplimiento durante toda la vida útil."}],"comprueba":[{"pregunta":"¿Qué es la aptitud del método en microbiología?","respuesta":"Demostrar que el método recupera microorganismos en presencia del producto."},{"pregunta":"¿Qué zona climática se usa para Colombia?","respuesta":"La zona IVb, cálida y muy húmeda."}],"resumen":["Los no estériles tienen **límites microbianos**; los estériles, **ausencia** y endotoxinas.","La **estabilidad** sostiene la calidad durante la vida útil.","Colombia trabaja con la **zona climática IVb**."],"referencias":[{"cita":"ICH. Q1A(R2) Stability Testing of New Drug Substances and Products.","url":"https://database.ich.org/sites/default/files/Q1A%28R2%29%20Guideline.pdf"},{"cita":"OMS. TRS 1010, Anexo 10: Stability testing of active pharmaceutical ingredients and finished pharmaceutical products (2018).","url":"https://extranet.who.int/prequal/sites/default/files/document_files/TRS1010_Annex10.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3157 de 2018: guía para los estudios de estabilidad de medicamentos de síntesis química.","url":"https://sidn.ramajudicial.gov.co/SIDN/NORMATIVA/TEXTOS_COMPLETOS/8_RESOLUCIONES/RESOLUCIONES%202018/MSPS%20Resoluci%C3%B3n%203157%20de%202018%20(Gu%C3%ADa%20para%20el%20desarrollo%20y%20presentaci%C3%B3n%20de%20los%20estudios%20de%20estabilidad%20de%20medicamentos%20de%20s%C3%ADntesis%20qu%C3%ADmica).pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1839 de 2020, que modifica la Resolución 3157 de 2018.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-1839-de-2020.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Frasco de jarabe ilustrado con una línea de tiempo de 24 meses y dos iconos: un microscopio y un termómetro con humedad.","alt":"Calidad microbiológica y estabilidad a lo largo de la vida útil"}],"keywords":["calidad microbiológica de medicamentos","estabilidad de medicamentos","microbiología farmacéutica no estériles","vida útil de medicamentos","control microbiológico farmacéutico"],"mapa":{"centro":"Calidad que se sostiene","ramas":[{"titulo":"No estériles","icono":"Bug","nodos":["Recuento de aerobios","Hongos y levaduras","Microorganismos específicos"]},{"titulo":"Estériles","icono":"Syringe","nodos":["Prueba de esterilidad","Endotoxinas"]},{"titulo":"Estabilidad","icono":"CalendarClock","nodos":["ICH Q1A","Zona climática IVb","Vida útil"]},{"titulo":"Bases comunes","icono":"ShieldCheck","nodos":["Métodos aptos","Medios con promoción de crecimiento","Tendencias"]}]},"proceso":{"titulo":"Cómo se garantiza la calidad durante la vida útil","intro":"","pasos":[{"titulo":"Diseñar en el desarrollo","detalle":"Se eligen fórmula, conservantes y envase pensando en la estabilidad y la microbiología.","icono":"Lightbulb","evidencia":"Estudios de desarrollo."},{"titulo":"Demostrar la estabilidad","detalle":"Se ejecutan estudios en condiciones de largo plazo y aceleradas.","icono":"CalendarClock","evidencia":"Protocolos e informes de estabilidad."},{"titulo":"Liberar con límites","detalle":"Cada lote cumple sus límites microbiológicos y fisicoquímicos al liberarse.","icono":"BadgeCheck","evidencia":"Certificado de análisis."},{"titulo":"Vigilar en el tiempo","detalle":"El programa de estabilidad continua y las tendencias confirman la vida útil.","icono":"LineChart","evidencia":"Estabilidad continua."}]},"caso":{"titulo":"Una crema sin ensayos microbiológicos","contexto":"Un fabricante propone eliminar el recuento microbiano de una crema tópica porque «la crema no es estéril y nunca ha dado problemas».","pregunta":"¿Qué respondes?","opciones":[{"texto":"Aceptar: los productos no estériles no necesitan microbiología.","correcta":false,"retro":"Los no estériles tienen límites microbianos y de microorganismos específicos según su vía de administración."},{"texto":"Mantener los ensayos que exige la especificación: los productos tópicos tienen límites y exigen la ausencia de microorganismos como Staphylococcus aureus y Pseudomonas aeruginosa.","correcta":true,"retro":"La ausencia de problemas pasados no elimina el riesgo ni el requisito."},{"texto":"Reemplazarlo por una prueba de pH.","correcta":false,"retro":"El pH no informa sobre la carga microbiana."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: calidad microbiológica y estabilidad en el tiempo$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: calidad microbiológica y estabilidad en el tiempo$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
