    v_n := v_n + 1;
  END IF;

  -- 25. Recuento microbiano: aerobios totales, hongos y levaduras
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"«Menos de 10» no siempre es menos de 10","texto":"Un analista reporta «menos de 10 UFC/g» para un jarabe con conservantes. Nunca demostró que su método recuperara microorganismos en presencia de esos conservantes. Si el conservante inhibía el crecimiento en la placa, el jarabe pudo estar contaminado y el resultado seguir diciendo «menos de 10». El recuento microbiano vale lo que vale su aptitud demostrada."},"objetivos":["Describir el recuento de microorganismos aerobios totales y de hongos y levaduras.","Aplicar los criterios de aceptación según la vía de administración.","Explicar la prueba de aptitud del método y la promoción de crecimiento de los medios."],"conceptos":[{"icono":"Bug","termino":"TAMC","definicion":"Recuento total de microorganismos aerobios, normalmente en agar caseína soya, expresado en UFC por gramo o mililitro."},{"icono":"Leaf","termino":"TYMC","definicion":"Recuento total de hongos y levaduras, normalmente en agar Sabouraud dextrosa."},{"icono":"ShieldCheck","termino":"Aptitud del método","definicion":"Demostración de que el método recupera microorganismos de prueba en presencia del producto, neutralizando su actividad antimicrobiana."},{"icono":"Ruler","termino":"Criterios de aceptación","definicion":"Límites según la vía de administración; por ejemplo, para preparaciones orales no acuosas, 10³ UFC/g de aerobios y 10² UFC/g de hongos y levaduras."}],"secciones":[{"titulo":"Qué se mide y cómo","parrafos":["El recuento microbiano cuantifica los microorganismos viables de un producto no estéril. El **recuento total de aerobios (TAMC)** se hace normalmente en agar caseína soya incubado a 30–35 °C, y el **recuento total de hongos y levaduras (TYMC)**, en agar Sabouraud dextrosa a 20–25 °C. Los métodos incluyen la siembra en placa, la **filtración por membrana** (útil cuando el producto tiene actividad antimicrobiana, porque permite lavarlo) y el método del número más probable para algunos casos.","Los **criterios de aceptación** dependen de la vía de administración. Por ejemplo, para preparaciones orales no acuosas, los capítulos de farmacopea establecen 10³ UFC/g de aerobios y 10² UFC/g de hongos y levaduras, con ausencia de Escherichia coli en 1 g; para preparaciones orales acuosas, 10² UFC/mL y 10¹ UFC/mL, con ausencia de E. coli en 1 mL. Al interpretar, un criterio de 10¹ admite hasta 20 UFC, uno de 10² hasta 200 y uno de 10³ hasta 2.000."]},{"titulo":"La aptitud del método","parrafos":["Antes de usar un método de recuento con un producto, se demuestra su **aptitud**: se inoculan microorganismos de prueba en una cantidad baja conocida en presencia del producto y se verifica que se recuperan en una proporción aceptable frente a un control sin producto. Si no se recuperan, se ajusta el método para **neutralizar** la actividad antimicrobiana: dilución, neutralizantes químicos, filtración con lavados o una combinación.","Además, cada lote de medio de cultivo se verifica con la prueba de **promoción del crecimiento**. Sin estas demostraciones, un «menos de 10» puede ocultar una contaminación, como en el caso inicial. Los resultados se analizan en **tendencias**: un aumento gradual puede anunciar un problema de agua, de materias primas o de higiene."]}],"errores":[{"error":"Usar un método sin aptitud demostrada con el producto.","correccion":"Demuestra la aptitud para cada producto y cada cambio de fórmula."},{"error":"No verificar los medios.","correccion":"Verifica la promoción de crecimiento de cada lote de medio."}],"comprueba":[{"pregunta":"¿A qué temperaturas se incuban los recuentos de aerobios y de hongos y levaduras?","respuesta":"Aerobios a 30–35 °C; hongos y levaduras a 20–25 °C."},{"pregunta":"¿Hasta cuántas UFC admite un criterio de 10²?","respuesta":"Hasta 200 UFC."}],"resumen":["TAMC y TYMC cuantifican la **carga microbiana** de los no estériles.","Los criterios dependen de la **vía de administración**.","Sin **aptitud del método**, el recuento no es confiable."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"}],"imagenes":[{"ubicacion":"En la sección de métodos","descripcion":"Dos cajas de Petri ilustradas: una con colonias bacterianas (agar caseína soya) y otra con hongos (agar Sabouraud), con sus temperaturas de incubación.","alt":"Recuento de aerobios totales y de hongos y levaduras"}],"keywords":["recuento microbiano farmacéutico","tamc tymc","recuento de aerobios totales","hongos y levaduras medicamentos","aptitud del método microbiológico","límites microbianos usp 1111"],"mapa":{"centro":"Contar microorganismos con confianza","ramas":[{"titulo":"Qué se cuenta","icono":"Bug","nodos":["Aerobios totales (TAMC)","Hongos y levaduras (TYMC)"]},{"titulo":"Cómo","icono":"TestTube","nodos":["Placa vertida o extendida","Filtración por membrana","Número más probable"]},{"titulo":"Aptitud","icono":"ShieldCheck","nodos":["Microorganismos de prueba","Neutralización","Recuperación aceptable"]},{"titulo":"Criterios","icono":"Ruler","nodos":["Según vía de administración","Interpretación con factor","Tendencias"]}]},"proceso":{"titulo":"Recuento microbiano de un jarabe","intro":"","pasos":[{"titulo":"Confirmar la aptitud","detalle":"Verifica que exista una aptitud aprobada del método para ese producto.","icono":"ShieldCheck","evidencia":"Informe de aptitud del método."},{"titulo":"Verificar los medios","detalle":"Confirma la promoción de crecimiento del lote de medio.","icono":"TestTube","evidencia":"Registro de promoción de crecimiento."},{"titulo":"Preparar la muestra","detalle":"Prepara la dilución con el neutralizante definido en la aptitud.","icono":"Beaker","evidencia":"Registro de preparación."},{"titulo":"Sembrar","detalle":"Siembra o filtra según el método, con controles negativos.","icono":"Microscope","evidencia":"Registro de siembra."},{"titulo":"Incubar","detalle":"Incuba aerobios a 30–35 °C y hongos y levaduras a 20–25 °C por el tiempo definido.","icono":"Thermometer","evidencia":"Registros de incubación."},{"titulo":"Contar e interpretar","detalle":"Cuenta las colonias, calcula UFC con el factor de dilución y compara con los criterios.","icono":"Calculator","evidencia":"Resultados y evaluación."}]},"caso":{"titulo":"Un jarabe con conservante nuevo","contexto":"Un jarabe cambió de conservante. El laboratorio sigue usando el mismo método de recuento, cuya aptitud se demostró con la fórmula anterior.","pregunta":"¿Qué falta?","opciones":[{"texto":"Nada: el método ya estaba validado.","correcta":false,"retro":"La aptitud se demuestra para cada producto; un conservante nuevo puede inhibir el crecimiento de otra forma."},{"texto":"Repetir la aptitud del método con la nueva fórmula y, si hace falta, ajustar la neutralización antes de reportar recuentos.","correcta":true,"retro":"Sin aptitud demostrada con la fórmula nueva, los recuentos pueden subestimar la contaminación."},{"texto":"Reportar los recuentos con una nota de precaución.","correcta":false,"retro":"Una nota no reemplaza la demostración técnica de que el método funciona."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Recuento microbiano: aerobios totales, hongos y levaduras$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Recuento microbiano: aerobios totales, hongos y levaduras$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 26. Ausencia de microorganismos específicos (patógenos)
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"No se trata de cuántos, sino de cuáles","texto":"Un jarabe para niños puede tener algunos microorganismos dentro del límite permitido. Pero si uno de ellos es Escherichia coli, el lote no cumple, aunque el recuento total sea bajo: su presencia indica contaminación de origen fecal. Los ensayos de microorganismos específicos buscan presencia o ausencia de los que no deben estar."},"objetivos":["Identificar los microorganismos específicos según la vía de administración.","Describir el flujo de un ensayo de ausencia: enriquecimiento, siembra selectiva y confirmación.","Interpretar un resultado presuntivo positivo."],"conceptos":[{"icono":"Bug","termino":"Microorganismos específicos","definicion":"Escherichia coli, Salmonella, Pseudomonas aeruginosa, Staphylococcus aureus, Candida albicans, bacterias gramnegativas tolerantes a bilis y clostridios, según el producto."},{"icono":"FlaskConical","termino":"Enriquecimiento","definicion":"Incubación en un caldo que permite que el microorganismo, si está, crezca hasta niveles detectables."},{"icono":"Filter","termino":"Medio selectivo","definicion":"Medio que favorece el crecimiento del microorganismo buscado e inhibe otros, con reacciones características."},{"icono":"CheckCircle2","termino":"Confirmación","definicion":"Pruebas de identificación de las colonias sospechosas para confirmar o descartar el microorganismo."}],"secciones":[{"titulo":"Cuáles buscar","parrafos":["Los capítulos de farmacopea y la especificación definen qué microorganismos deben estar **ausentes** en una cantidad de producto, según la vía de administración. Para preparaciones **orales**, la ausencia de **Escherichia coli** es el requisito habitual, y en ciertos productos de origen natural se agrega Salmonella. Para preparaciones **cutáneas** y de mucosas se buscan **Staphylococcus aureus** y **Pseudomonas aeruginosa**; para las vaginales se agrega **Candida albicans**. Las bacterias gramnegativas tolerantes a bilis y los clostridios aplican en productos específicos.","Estos microorganismos se buscan porque indican un riesgo concreto: contaminación de origen fecal (E. coli), patógenos de piel y mucosas o microorganismos resistentes y oportunistas."]},{"titulo":"El flujo de un ensayo de ausencia","parrafos":["El ensayo tiene tres pasos. El **enriquecimiento** incuba la muestra en un caldo que permite crecer al microorganismo, si está presente, aunque haya pocos. Luego se siembra en un **medio selectivo** que favorece al microorganismo buscado e inhibe a otros, y donde sus colonias tienen un aspecto característico. Finalmente, las colonias sospechosas se **confirman** con pruebas de identificación.","Como en los recuentos, el método necesita **aptitud** demostrada con el producto y controles positivos y negativos en cada análisis. Un **resultado presuntivo** (colonias con aspecto característico) no es un resultado final: se confirma. Si se confirma la presencia, el producto no cumple y se abre una investigación sobre el origen de la contaminación: materias primas, agua, equipos o personal."]}],"errores":[{"error":"Confundir recuento dentro de límite con ausencia de patógenos.","correccion":"Son ensayos distintos y ambos deben cumplirse."},{"error":"Reportar un presuntivo como resultado final.","correccion":"Confirma la identidad de las colonias antes de concluir."}],"comprueba":[{"pregunta":"¿Qué microorganismo se busca habitualmente en productos orales?","respuesta":"Escherichia coli."},{"pregunta":"¿Cuáles son los tres pasos del ensayo de ausencia?","respuesta":"Enriquecimiento, siembra en medio selectivo y confirmación."}],"resumen":["Importa **cuáles** microorganismos, no solo cuántos.","Flujo: **enriquecimiento, medio selectivo y confirmación**.","Un presuntivo **se confirma**; un positivo **se investiga**."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"},{"cita":"ICH. Q6A Specifications: Test Procedures and Acceptance Criteria for New Drug Substances and New Drug Products (EMA).","url":"https://www.ema.europa.eu/en/ich-q6a-specifications-test-procedures-acceptance-criteria-new-drug-substances-new-drug-products-chemical-substances-scientific-guideline"}],"imagenes":[{"ubicacion":"Junto al mapa de proceso","descripcion":"Secuencia ilustrada: tubo con caldo de enriquecimiento, caja con agar selectivo y colonias características, y una lupa de confirmación.","alt":"Flujo del ensayo de ausencia de microorganismos específicos"}],"keywords":["ausencia de microorganismos específicos","escherichia coli en medicamentos","usp 62 microorganismos específicos","staphylococcus aureus pseudomonas aeruginosa","patógenos en productos farmacéuticos","microbiología de productos no estériles"],"mapa":{"centro":"Ausencia de microorganismos específicos","ramas":[{"titulo":"Vía oral","icono":"Pill","nodos":["Escherichia coli","Salmonella en algunos productos"]},{"titulo":"Vía tópica y mucosas","icono":"Hand","nodos":["Staphylococcus aureus","Pseudomonas aeruginosa","Candida albicans en vaginales"]},{"titulo":"Flujo","icono":"Workflow","nodos":["Enriquecimiento","Medio selectivo","Confirmación"]},{"titulo":"Bases","icono":"ShieldCheck","nodos":["Aptitud del método","Controles positivos y negativos","Medios verificados"]}]},"proceso":{"titulo":"Búsqueda de Escherichia coli en un producto oral","intro":"","pasos":[{"titulo":"Preparar la muestra","detalle":"Prepara la cantidad indicada con el neutralizante de la aptitud.","icono":"Beaker","evidencia":"Registro de preparación."},{"titulo":"Enriquecer","detalle":"Incuba en caldo caseína soya y luego en el caldo selectivo indicado.","icono":"FlaskConical","evidencia":"Registros de incubación."},{"titulo":"Sembrar en medio selectivo","detalle":"Siembra en el agar selectivo e incuba.","icono":"Filter","evidencia":"Registro de siembra."},{"titulo":"Observar colonias","detalle":"Busca colonias con el aspecto característico.","icono":"Search","evidencia":"Observación registrada."},{"titulo":"Confirmar","detalle":"Identifica las colonias sospechosas con pruebas de confirmación.","icono":"CheckCircle2","evidencia":"Resultado de identificación."},{"titulo":"Concluir","detalle":"Reporta ausencia o presencia en la cantidad analizada.","icono":"FileCheck","evidencia":"Resultado final."}]},"caso":{"titulo":"Colonias sospechosas en el agar","contexto":"En la búsqueda de E. coli en un jarabe aparecen colonias con aspecto compatible en el medio selectivo. El recuento total del lote está dentro del límite.","pregunta":"¿Qué corresponde?","opciones":[{"texto":"Liberar porque el recuento total cumple.","correcta":false,"retro":"El recuento total no reemplaza el ensayo de ausencia; la presencia de E. coli hace que el producto no cumpla."},{"texto":"Retener el lote, confirmar la identidad de las colonias y, si se confirma, declarar no conforme e investigar el origen.","correcta":true,"retro":"Un presuntivo se confirma; una confirmación positiva implica no conformidad e investigación."},{"texto":"Repetir el ensayo desde el inicio hasta obtener ausencia.","correcta":false,"retro":"Repetir para obtener otro resultado sin confirmar el primero es inaceptable."}]}}$j$::jsonb;
