  END IF;

  -- 27. Prueba de esterilidad
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Catorce días de espera","texto":"Un lote de inyectables espera la prueba de esterilidad durante al menos catorce días de incubación. Si al día once aparece turbidez en un tubo, la pregunta inmediata es si el lote está contaminado o si se contaminó la prueba. Esa pregunta se responde con lo que se hizo antes: el ambiente, la técnica, los controles. La prueba de esterilidad es tan confiable como las condiciones en que se ejecuta."},"objetivos":["Describir los métodos de la prueba de esterilidad y sus condiciones de incubación.","Explicar sus límites estadísticos y su lugar en la liberación.","Interpretar un crecimiento y las condiciones para invalidar una prueba."],"conceptos":[{"icono":"Filter","termino":"Filtración por membrana","definicion":"Método preferido cuando el producto lo permite: se filtra, se lava la membrana para eliminar la actividad antimicrobiana y se incuba en los medios."},{"icono":"FlaskConical","termino":"Inoculación directa","definicion":"El producto se agrega directamente a los medios cuando no puede filtrarse."},{"icono":"Thermometer","termino":"Medios e incubación","definicion":"Medio de tioglicolato a 30–35 °C y caldo caseína soya a 20–25 °C, durante no menos de 14 días."},{"icono":"AlertTriangle","termino":"Invalidación","definicion":"Solo cuando se demuestra de forma inequívoca un fallo de la prueba (ambiente, técnica, materiales); no basta con sospecharlo."}],"secciones":[{"titulo":"Cómo se hace","parrafos":["La prueba de esterilidad busca microorganismos viables en un número definido de unidades del lote. El método preferido es la **filtración por membrana**: el producto pasa por un filtro que retiene los microorganismos, la membrana se lava para eliminar la actividad antimicrobiana y se incuba en los medios. Cuando el producto no puede filtrarse, se usa la **inoculación directa** en los medios. En ambos casos se demuestra la **aptitud** del método con el producto.","Se usan dos medios: el **medio de tioglicolato**, incubado a 30–35 °C, que favorece bacterias aerobias y anaerobias, y el **caldo caseína soya**, incubado a 20–25 °C, que favorece hongos y bacterias aerobias. La incubación dura **no menos de 14 días**. La prueba se ejecuta en un ambiente que no la contamine, como un aislador o una cabina de grado A con entorno B, con monitoreo y controles negativos."]},{"titulo":"Límites e interpretación","parrafos":["La prueba de esterilidad tiene un **límite estadístico**: analiza una muestra pequeña, por lo que solo detecta contaminaciones relativamente frecuentes. Por eso, como viste en el curso de BPM, la esterilidad de un lote se asegura con el proceso validado, y la prueba confirma.","Si aparece crecimiento, el resultado se considera positivo salvo que se demuestre de forma **inequívoca** que la prueba falló: por ejemplo, monitoreo de la prueba fuera de límite, control negativo contaminado o un error de técnica documentado, y que el microorganismo encontrado se relacione con esa falla. Sospechar un error no basta. Un positivo confirmado implica que el lote no cumple y una investigación que incluye la fabricación."]}],"errores":[{"error":"Invalidar positivos por sospecha.","correccion":"Invalida solo con evidencia inequívoca de falla de la prueba."},{"error":"Confiar en la prueba como garantía de esterilidad.","correccion":"La esterilidad se asegura con el proceso validado; la prueba confirma."}],"comprueba":[{"pregunta":"¿Qué medios y temperaturas se usan?","respuesta":"Tioglicolato a 30–35 °C y caldo caseína soya a 20–25 °C."},{"pregunta":"¿Cuánto dura la incubación?","respuesta":"No menos de 14 días."}],"resumen":["Filtración por membrana o inoculación directa, **dos medios y 14 días**.","La prueba tiene un **límite estadístico**: confirma, no asegura.","Un positivo se **invalida solo con evidencia** inequívoca."],"referencias":[{"cita":"Comisión Europea. EU GMP Annex 1: Manufacture of Sterile Medicinal Products (2022).","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"},{"cita":"OMS. TRS 1044, Anexo 2: WHO good manufacturing practices for sterile pharmaceutical products (2022).","url":"https://www.who.int/publications/m/item/trs1044-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"En la sección de método","descripcion":"Aislador ilustrado con un sistema de filtración por membrana y dos tubos de medio, uno amarillento (tioglicolato) y otro claro (caseína soya).","alt":"Prueba de esterilidad por filtración por membrana en un aislador"}],"keywords":["prueba de esterilidad","usp 71 esterilidad","filtración por membrana esterilidad","medio tioglicolato caseína soya","invalidación prueba de esterilidad","esterilidad de inyectables"],"mapa":{"centro":"La prueba de esterilidad","ramas":[{"titulo":"Métodos","icono":"Filter","nodos":["Filtración por membrana","Inoculación directa","Aptitud con el producto"]},{"titulo":"Incubación","icono":"Thermometer","nodos":["Tioglicolato 30–35 °C","Caseína soya 20–25 °C","Mínimo 14 días"]},{"titulo":"Ambiente","icono":"Wind","nodos":["Aislador o grado A con entorno B","Monitoreo durante la prueba","Controles negativos"]},{"titulo":"Límites","icono":"AlertTriangle","nodos":["Muestra pequeña","Baja probabilidad de detectar","No reemplaza al proceso"]}]},"proceso":{"titulo":"Prueba de esterilidad por filtración","intro":"","pasos":[{"titulo":"Preparar el ambiente","detalle":"Prepara el aislador o la cabina, con monitoreo activo.","icono":"Wind","evidencia":"Registro de monitoreo de la prueba."},{"titulo":"Verificar medios y aptitud","detalle":"Confirma la promoción de crecimiento y la aptitud con el producto.","icono":"ShieldCheck","evidencia":"Registros de verificación."},{"titulo":"Filtrar y lavar","detalle":"Filtra el número de unidades indicado y lava la membrana.","icono":"Filter","evidencia":"Registro de la prueba."},{"titulo":"Incubar en dos medios","detalle":"Incuba en tioglicolato a 30–35 °C y en caseína soya a 20–25 °C.","icono":"Thermometer","evidencia":"Registros de incubación."},{"titulo":"Observar durante 14 días","detalle":"Revisa los medios periódicamente en busca de turbidez.","icono":"Search","evidencia":"Observaciones registradas."},{"titulo":"Concluir o investigar","detalle":"Sin crecimiento, cumple; con crecimiento, se identifica y se investiga.","icono":"FileCheck","evidencia":"Resultado o investigación."}]},"caso":{"titulo":"Turbidez al día once","contexto":"Al día once aparece turbidez en el tubo de caseína soya de una prueba de esterilidad. El monitoreo del aislador durante la prueba fue conforme y el control negativo no tiene crecimiento.","pregunta":"¿Cómo se interpreta?","opciones":[{"texto":"Invalidar la prueba porque probablemente se contaminó en el laboratorio.","correcta":false,"retro":"Sin evidencia de falla de la prueba (monitoreo y control negativo conformes), no hay base para invalidarla."},{"texto":"Tratar el resultado como positivo: identificar el microorganismo e iniciar la investigación que incluya la fabricación del lote.","correcta":true,"retro":"Solo se invalida con evidencia inequívoca; aquí la evidencia apunta a que la prueba fue válida."},{"texto":"Repetir la prueba y usar el segundo resultado.","correcta":false,"retro":"La repetición solo procede si la primera se invalidó con evidencia."}]}}$j$::jsonb;
