  END IF;

  -- 28. Endotoxinas bacterianas (LAL)
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Estéril y aun así con fiebre","texto":"Un lote de solución inyectable cumple la prueba de esterilidad: no hay microorganismos vivos. Sin embargo, varios pacientes presentan fiebre y escalofríos después de recibirlo. La causa son endotoxinas: restos de bacterias gramnegativas que sobrevivieron como moléculas aunque las bacterias murieran. Por eso los parenterales tienen un ensayo propio para endotoxinas."},"objetivos":["Explicar qué son las endotoxinas y por qué se controlan en los parenterales.","Describir los métodos del ensayo con lisado de amebocitos de Limulus (LAL).","Calcular e interpretar el límite de endotoxinas y la máxima dilución válida."],"conceptos":[{"icono":"Bug","termino":"Endotoxinas","definicion":"Lipopolisacáridos de la pared de bacterias gramnegativas. Son pirógenos: causan fiebre y, en dosis altas, reacciones graves."},{"icono":"TestTube","termino":"LAL","definicion":"Lisado de amebocitos del cangrejo herradura (Limulus) que reacciona con las endotoxinas. Se usa en métodos de gel, turbidimétricos y cromogénicos."},{"icono":"Calculator","termino":"Límite de endotoxinas","definicion":"Se calcula como K/M: K es el umbral pirógeno por kilogramo (por ejemplo, 5 UE/kg para la mayoría de las vías parenterales) y M la dosis máxima por kilogramo por hora."},{"icono":"Ruler","termino":"Máxima dilución válida","definicion":"La mayor dilución de la muestra que aún permite detectar el límite de endotoxinas con la sensibilidad del método."}],"secciones":[{"titulo":"Qué son y cómo se detectan","parrafos":["Las **endotoxinas** son lipopolisacáridos de la membrana externa de las bacterias gramnegativas. Son **pirógenos**: inyectados, producen fiebre y, en cantidades mayores, reacciones graves. Resisten la esterilización por calor húmedo convencional, por eso su control empieza en el agua para inyectables, en los componentes despirogenizados y en el proceso, y se verifica en el producto.","El ensayo más usado emplea el **lisado de amebocitos de Limulus (LAL)**, que reacciona con las endotoxinas. Hay técnicas de **gel** (formación de un coágulo, cualitativa o semicuantitativa), **turbidimétricas** (medición del aumento de turbidez) y **cromogénicas** (desarrollo de color). Las farmacopeas también reconocen alternativas basadas en reactivos recombinantes, que no dependen de la extracción de sangre del cangrejo, con su propia validación."]},{"titulo":"Límites, dilución e interferencias","parrafos":["El **límite de endotoxinas** de un producto se calcula como **K/M**, donde K es el umbral de dosis pirógena por kilogramo de peso (por ejemplo, 5 UE/kg para la mayoría de las vías parenterales y un valor mucho menor para la vía intratecal) y M es la dosis máxima del producto por kilogramo por hora. Con ese límite y la sensibilidad del método se calcula la **máxima dilución válida**: diluir ayuda a eliminar interferencias, pero no se puede diluir tanto que el límite quede por debajo de lo que el método detecta.","Muchos productos **interfieren** con la reacción, inhibiéndola o potenciándola. Por eso se demuestra que el método funciona con el producto (prueba de interferencia) y, en cada análisis, se incluye un **control positivo de producto**: muestra con una cantidad conocida de endotoxina que debe recuperarse dentro del rango aceptable. Sin esa recuperación, un resultado bajo no es confiable."]}],"errores":[{"error":"Confundir esterilidad con ausencia de endotoxinas.","correccion":"Son atributos distintos con ensayos distintos."},{"error":"Diluir más allá de la máxima dilución válida.","correccion":"Calcula la máxima dilución válida y respétala."}],"comprueba":[{"pregunta":"¿Cómo se calcula el límite de endotoxinas?","respuesta":"Como K/M: umbral pirógeno por kilogramo dividido por la dosis máxima por kilogramo por hora."},{"pregunta":"¿Para qué sirve el control positivo de producto?","respuesta":"Para demostrar que el producto no inhibe ni potencia la reacción en cada análisis."}],"resumen":["Las endotoxinas son **pirógenos** que sobreviven a la muerte bacteriana.","Se detectan con **LAL** (gel, turbidimétrico, cromogénico) o alternativas recombinantes.","Límite **K/M**, máxima dilución válida y **control positivo** de producto."],"referencias":[{"cita":"Comisión Europea. EU GMP Annex 1: Manufacture of Sterile Medicinal Products (2022).","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"},{"cita":"OMS. TRS 1044, Anexo 2: WHO good manufacturing practices for sterile pharmaceutical products (2022).","url":"https://www.who.int/publications/m/item/trs1044-annex2"},{"cita":"OMS. TRS 1033, Anexo 3: Good manufacturing practices: water for pharmaceutical use (2021).","url":"https://www.who.int/publications/m/item/annex-3-trs-1033"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"En la sección de detección","descripcion":"Bacteria gramnegativa ilustrada liberando moléculas de lipopolisacárido y, al lado, un tubo con reacción LAL que cambia de color.","alt":"Endotoxinas bacterianas y su detección con LAL"}],"keywords":["endotoxinas bacterianas","ensayo lal","límite de endotoxinas k/m","máxima dilución válida","pirógenos inyectables","usp 85 endotoxinas"],"mapa":{"centro":"Control de endotoxinas","ramas":[{"titulo":"Qué son","icono":"Bug","nodos":["Lipopolisacáridos de gramnegativas","Pirógenos","Resisten la esterilización convencional"]},{"titulo":"Métodos","icono":"TestTube","nodos":["Gel","Turbidimétrico","Cromogénico","Alternativas recombinantes"]},{"titulo":"Cálculos","icono":"Calculator","nodos":["Límite = K/M","Máxima dilución válida","Sensibilidad del lisado"]},{"titulo":"Controles","icono":"ShieldCheck","nodos":["Interferencia del producto","Control positivo de producto","Curva estándar"]}]},"proceso":{"titulo":"Ensayo cinético cromogénico de endotoxinas","intro":"","pasos":[{"titulo":"Calcular límite y dilución","detalle":"Calcula el límite K/M y la máxima dilución válida.","icono":"Calculator","evidencia":"Cálculos documentados."},{"titulo":"Preparar la curva estándar","detalle":"Prepara diluciones del estándar de endotoxina en agua libre de endotoxinas.","icono":"LineChart","evidencia":"Registro de la curva."},{"titulo":"Preparar muestras y control positivo","detalle":"Diluye la muestra y prepara el control positivo de producto.","icono":"TestTube","evidencia":"Registro de preparación."},{"titulo":"Correr el ensayo","detalle":"Incuba en el lector con el reactivo y registra la cinética.","icono":"Activity","evidencia":"Datos del lector."},{"titulo":"Verificar validez","detalle":"Confirma la linealidad de la curva y la recuperación del control positivo.","icono":"ShieldCheck","evidencia":"Criterios de validez cumplidos."},{"titulo":"Calcular y concluir","detalle":"Calcula UE por unidad y compara con el límite.","icono":"FileCheck","evidencia":"Resultado y conclusión."}]},"caso":{"titulo":"Un resultado bajo sospechoso","contexto":"Un ensayo de endotoxinas da un resultado muy bajo para un lote, pero la recuperación del control positivo de producto es del 20 %, fuera del rango aceptable.","pregunta":"¿Se puede reportar el resultado?","opciones":[{"texto":"Sí, porque el resultado está muy por debajo del límite.","correcta":false,"retro":"Una recuperación del 20 % indica que el producto inhibe la reacción: el resultado bajo puede esconder endotoxinas."},{"texto":"No: el ensayo no es válido por inhibición; hay que ajustar la dilución dentro de la máxima válida o tratar la muestra y repetir.","correcta":true,"retro":"Sin recuperación aceptable del control positivo, el resultado no demuestra la ausencia de endotoxinas."},{"texto":"Sí, si la prueba de esterilidad cumplió.","correcta":false,"retro":"La esterilidad no informa sobre endotoxinas."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Endotoxinas bacterianas (LAL)$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Endotoxinas bacterianas (LAL)$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 29. Diseño de estudios de estabilidad según ICH Q1A
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"Una vida útil escrita en el estuche","texto":"El estuche de un medicamento dice «vence en 24 meses» y «almacenar a temperatura no mayor de 30 °C». Esas dos frases son promesas al paciente. Detrás de ellas hay un estudio de estabilidad que muestreó lotes durante años en cámaras controladas. Diseñar bien ese estudio es lo que permite cumplir la promesa."},"objetivos":["Describir los elementos de un estudio de estabilidad según ICH Q1A.","Diferenciar estudios de largo plazo, intermedios y acelerados.","Identificar qué es un cambio significativo y sus consecuencias."],"conceptos":[{"icono":"CalendarClock","termino":"Largo plazo","definicion":"Estudio en las condiciones de almacenamiento recomendadas, durante al menos el periodo de vida útil propuesto."},{"icono":"Flame","termino":"Acelerado","definicion":"Estudio a 40 °C y 75 % de humedad relativa durante 6 meses, para evaluar el efecto de excursiones y apoyar la vida útil."},{"icono":"Thermometer","termino":"Intermedio","definicion":"Condición que se usa cuando el acelerado muestra un cambio significativo y el largo plazo se hace a 25 °C."},{"icono":"AlertTriangle","termino":"Cambio significativo","definicion":"Por ejemplo, un cambio de 5 % en la valoración frente al inicial, un producto de degradación por encima de su límite o una falla de disolución, aspecto o pH."},{"icono":"Layers","termino":"Lotes y envases","definicion":"Normalmente al menos tres lotes, de escala piloto o mayor, en el envase en que se comercializará."}],"secciones":[{"titulo":"Los elementos del diseño","parrafos":["ICH Q1A(R2) establece cómo diseñar los estudios de estabilidad de principios activos y productos nuevos. Se estudian normalmente **al menos tres lotes** de escala piloto o mayor, fabricados con el proceso que se usará, en el **envase de comercialización**. Se analizan los atributos que pueden cambiar con el tiempo y afectar la calidad, la seguridad o la eficacia: valoración, productos de degradación, disolución, aspecto, pH, contenido de agua, conservantes y microbiología, según el producto, con métodos **indicadores de estabilidad** validados.","La **frecuencia de análisis** en el estudio de largo plazo suele ser cada 3 meses durante el primer año, cada 6 meses durante el segundo y anual después, hasta cubrir la vida útil propuesta. En el acelerado se analizan como mínimo tres puntos, incluidos el inicial y el final, por ejemplo 0, 3 y 6 meses. La guía ICH Q1B agrega los estudios de **fotoestabilidad**."]},{"titulo":"Condiciones y cambio significativo","parrafos":["Las condiciones dependen de la **zona climática** donde se comercializa el producto (la verás en la clase siguiente). El estudio **acelerado** se hace a 40 °C y 75 % de humedad relativa durante 6 meses. Si en el acelerado ocurre un **cambio significativo** y el largo plazo se hace a 25 °C, se agrega un estudio **intermedio**.","ICH Q1A define el **cambio significativo** para productos: un cambio del 5 % en la valoración respecto al valor inicial, cualquier producto de degradación que supere su criterio de aceptación, fallas en aspecto, atributos físicos o funcionalidad, fallas de pH y fallas de disolución en las unidades analizadas, entre otros. La **vida útil** se propone a partir de los datos de largo plazo, con análisis estadístico (por ejemplo, regresión con intervalos de confianza) y una extrapolación limitada y justificada cuando los datos lo permiten."]}],"errores":[{"error":"Estudiar la estabilidad en un envase distinto al de comercialización.","correccion":"Usa el envase en que se comercializará el producto."},{"error":"Métodos que no indican estabilidad.","correccion":"Usa métodos validados que separen el activo de sus productos de degradación."}],"comprueba":[{"pregunta":"¿Cuáles son las condiciones del estudio acelerado?","respuesta":"40 °C y 75 % de humedad relativa durante 6 meses."},{"pregunta":"¿Qué es un cambio significativo en la valoración?","respuesta":"Un cambio del 5 % respecto al valor inicial."},{"pregunta":"¿Con qué frecuencia se analiza el largo plazo el primer año?","respuesta":"Cada 3 meses."}],"resumen":["Al menos **tres lotes**, en el **envase de comercialización**.","Largo plazo, **intermedio si aplica** y acelerado a **40 °C / 75 % HR**.","El **cambio significativo** y la estadística definen la vida útil."],"referencias":[{"cita":"ICH. Q1A(R2) Stability Testing of New Drug Substances and Products.","url":"https://database.ich.org/sites/default/files/Q1A%28R2%29%20Guideline.pdf"},{"cita":"ICH. Q1B Photostability Testing of New Drug Substances and Products.","url":"https://database.ich.org/sites/default/files/Q1B%20Guideline.pdf"},{"cita":"OMS. TRS 1010, Anexo 10: Stability testing of active pharmaceutical ingredients and finished pharmaceutical products (2018).","url":"https://extranet.who.int/prequal/sites/default/files/document_files/TRS1010_Annex10.pdf"},{"cita":"Revista Colombiana de Ciencias Químico-Farmacéuticas. El método de análisis para los estudios de estabilidad y de biodisponibilidad de medicamentos, parte II.","url":"https://revistas.unal.edu.co/index.php/rccquifa/article/download/56498/55451/287099"}],"imagenes":[{"ubicacion":"En la sección de condiciones","descripcion":"Tres cámaras de estabilidad ilustradas con sus condiciones (largo plazo, intermedio, acelerado) y calendarios de muestreo.","alt":"Condiciones de los estudios de estabilidad según ICH Q1A"}],"keywords":["estudios de estabilidad ich q1a","estabilidad acelerada 40 °c 75 %","cambio significativo estabilidad","diseño de estudios de estabilidad","frecuencia de análisis estabilidad","vida útil de medicamentos estabilidad"],"mapa":{"centro":"Un estudio de estabilidad","ramas":[{"titulo":"Qué se estudia","icono":"Layers","nodos":["Al menos 3 lotes","Envase de comercialización","Atributos que pueden cambiar"]},{"titulo":"Condiciones","icono":"Thermometer","nodos":["Largo plazo según la zona","Intermedio si aplica","Acelerado 40 °C / 75 % HR"]},{"titulo":"Frecuencia","icono":"CalendarClock","nodos":["Cada 3 meses el primer año","Cada 6 meses el segundo","Anual después"]},{"titulo":"Evaluación","icono":"LineChart","nodos":["Cambio significativo","Tendencias y regresión","Vida útil propuesta"]}]},"proceso":{"titulo":"Diseñar el protocolo de estabilidad de un producto nuevo","intro":"","pasos":[{"titulo":"Seleccionar lotes y envase","detalle":"Define al menos tres lotes representativos en el envase de comercialización.","icono":"Layers","evidencia":"Lista de lotes y envases."},{"titulo":"Definir condiciones","detalle":"Establece largo plazo según la zona climática, acelerado y, si aplica, intermedio.","icono":"Thermometer","evidencia":"Condiciones en el protocolo."},{"titulo":"Definir atributos y métodos","detalle":"Lista los atributos que pueden cambiar y los métodos indicadores de estabilidad.","icono":"ClipboardList","evidencia":"Especificación de estabilidad."},{"titulo":"Definir la frecuencia","detalle":"Programa los puntos de análisis de cada condición.","icono":"CalendarClock","evidencia":"Cronograma de muestreo."},{"titulo":"Colocar en cámaras","detalle":"Ubica las muestras en cámaras calificadas y monitoreadas.","icono":"Box","evidencia":"Registro de ingreso a cámaras."},{"titulo":"Evaluar y proponer vida útil","detalle":"Analiza tendencias y cambios significativos y propone la vida útil.","icono":"LineChart","evidencia":"Informe de estabilidad."}]},"caso":{"titulo":"Cambio significativo en el acelerado","contexto":"A los 6 meses en condición acelerada, la valoración de un producto bajó de 100,4 % a 94,8 %. El largo plazo, a los 6 meses, muestra 99,6 %.","pregunta":"¿Qué indica?","opciones":[{"texto":"Que el producto no sirve y debe reformularse.","correcta":false,"retro":"Un cambio significativo en el acelerado no invalida el producto: cambia cómo se evalúa y qué estudios se requieren."},{"texto":"Un cambio significativo en el acelerado (más del 5 %): según las condiciones de largo plazo, se requieren datos intermedios o una evaluación más conservadora de la vida útil, y se presta atención a las excursiones de temperatura.","correcta":true,"retro":"La guía define consecuencias para el cambio significativo: más datos y menos extrapolación."},{"texto":"Nada, porque el largo plazo cumple.","correcta":false,"retro":"El acelerado informa sobre el riesgo de excursiones y limita la extrapolación de la vida útil."}]}}$j$::jsonb;
