  -- 30. Zona climática IVb, normativa colombiana y vida útil
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un producto estable en Madrid, no en Barranquilla","texto":"Un producto importado tenía una vida útil de 36 meses demostrada a 25 °C y 60 % de humedad, las condiciones de un clima templado. En Colombia, donde muchas regiones son cálidas y húmedas, el mismo producto empezó a mostrar degradación antes de tiempo. La estabilidad no es universal: depende del clima donde vive el producto."},"objetivos":["Explicar la clasificación de zonas climáticas y la condición IVb.","Ubicar los requisitos colombianos de estabilidad: Resoluciones 3157 de 2018 y 1839 de 2020.","Relacionar las condiciones del estudio con la vida útil y el almacenamiento declarado."],"conceptos":[{"icono":"Globe","termino":"Zonas climáticas","definicion":"Clasificación del mundo según temperatura y humedad para definir las condiciones de los estudios de largo plazo."},{"icono":"Droplets","termino":"Zona IVb","definicion":"Clima cálido y muy húmedo, con condición de largo plazo de 30 °C y 75 % de humedad relativa."},{"icono":"Landmark","termino":"Normativa colombiana","definicion":"La Resolución 3157 de 2018, modificada por la Resolución 1839 de 2020, establece la guía para los estudios de estabilidad de medicamentos de síntesis química."},{"icono":"CalendarClock","termino":"Vida útil","definicion":"Periodo durante el cual el producto cumple su especificación en las condiciones de almacenamiento declaradas."}],"secciones":[{"titulo":"Zonas climáticas y la condición IVb","parrafos":["Para definir las condiciones de los estudios de largo plazo, el mundo se divide en **zonas climáticas** según su temperatura y humedad. Las zonas templadas (I y II) usan condiciones como 25 °C y 60 % de humedad; las cálidas usan 30 °C con distintas humedades. La guía de estabilidad de la OMS (TRS 1010, Anexo 10) incluye la zona **IVb**, cálida y muy húmeda, con condición de largo plazo de **30 °C y 75 % de humedad relativa**.","Colombia trabaja con las condiciones de la zona IVb para los estudios de largo plazo, por la presencia de regiones cálidas y húmedas en su territorio. Por eso un estudio hecho solo en condiciones templadas, como en el caso inicial, no demuestra la estabilidad del producto en el mercado colombiano."]},{"titulo":"La normativa colombiana y la vida útil","parrafos":["La **Resolución 3157 de 2018** del Ministerio de Salud estableció la guía para el desarrollo y la presentación de los estudios de estabilidad de los medicamentos de síntesis química, y la **Resolución 1839 de 2020** la modificó. Estas normas definen qué estudios se presentan para el registro sanitario, en qué condiciones y cómo se sustenta la vida útil. Antes de diseñar un estudio, consulta el texto vigente y sus anexos.","La **vida útil** que aparece en el rótulo, y la condición de almacenamiento (por ejemplo, «no mayor de 30 °C»), deben ser **coherentes con los datos**. Un programa de estabilidad continua, con al menos un lote por año, confirma después del registro que la vida útil se mantiene, y cualquier resultado fuera de especificación o de tendencia en estabilidad se investiga (lo verás en la unidad 5)."]}],"errores":[{"error":"Usar datos de zonas templadas para Colombia.","correccion":"Sustenta la estabilidad en condiciones de zona IVb."},{"error":"Rotular almacenamiento sin respaldo en los datos.","correccion":"Haz coherente el rótulo con las condiciones estudiadas."}],"comprueba":[{"pregunta":"¿Cuál es la condición de largo plazo de la zona IVb?","respuesta":"30 °C y 75 % de humedad relativa."},{"pregunta":"¿Qué normas colombianas regulan la estabilidad de medicamentos de síntesis química?","respuesta":"La Resolución 3157 de 2018 y su modificación, la Resolución 1839 de 2020."}],"resumen":["La estabilidad depende del **clima del mercado**.","Colombia: **zona IVb, 30 °C / 75 % HR**.","Resoluciones **3157 de 2018 y 1839 de 2020**; rótulo **coherente** con los datos."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 3157 de 2018: guía para los estudios de estabilidad de medicamentos de síntesis química.","url":"https://sidn.ramajudicial.gov.co/SIDN/NORMATIVA/TEXTOS_COMPLETOS/8_RESOLUCIONES/RESOLUCIONES%202018/MSPS%20Resoluci%C3%B3n%203157%20de%202018%20(Gu%C3%ADa%20para%20el%20desarrollo%20y%20presentaci%C3%B3n%20de%20los%20estudios%20de%20estabilidad%20de%20medicamentos%20de%20s%C3%ADntesis%20qu%C3%ADmica).pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1839 de 2020, que modifica la Resolución 3157 de 2018.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-1839-de-2020.pdf"},{"cita":"OMS. TRS 1010, Anexo 10: Stability testing of active pharmaceutical ingredients and finished pharmaceutical products (2018).","url":"https://extranet.who.int/prequal/sites/default/files/document_files/TRS1010_Annex10.pdf"},{"cita":"ICH. Q1A(R2) Stability Testing of New Drug Substances and Products.","url":"https://database.ich.org/sites/default/files/Q1A%28R2%29%20Guideline.pdf"}],"imagenes":[{"ubicacion":"En la sección de zonas","descripcion":"Mapa de Colombia ilustrado con un termómetro de 30 °C y una gota de 75 % de humedad, junto a un mapa del mundo coloreado por zonas climáticas.","alt":"Colombia en la zona climática IVb para estudios de estabilidad"}],"keywords":["zona climática ivb","estabilidad 30 °c 75 % humedad","resolución 3157 de 2018","resolución 1839 de 2020","estudios de estabilidad colombia invima","vida útil medicamentos colombia"],"mapa":{"centro":"Estabilidad para Colombia","ramas":[{"titulo":"Zonas","icono":"Globe","nodos":["I y II templadas","III cálida y seca","IVa cálida y húmeda","IVb cálida y muy húmeda"]},{"titulo":"Condición IVb","icono":"Droplets","nodos":["30 °C","75 % HR","Largo plazo"]},{"titulo":"Norma","icono":"Landmark","nodos":["Resolución 3157 de 2018","Resolución 1839 de 2020","Registro sanitario"]},{"titulo":"Rótulo","icono":"Tag","nodos":["Vida útil","Temperatura de almacenamiento","Coherente con los datos"]}]},"proceso":{"titulo":"Sustentar la vida útil de un producto para Colombia","intro":"","pasos":[{"titulo":"Identificar la zona","detalle":"Confirma que el mercado colombiano requiere condiciones de zona IVb.","icono":"Globe","evidencia":"Análisis de mercado y norma."},{"titulo":"Revisar la norma vigente","detalle":"Consulta la Resolución 3157 de 2018 y su modificación de 2020.","icono":"Landmark","evidencia":"Requisitos aplicables."},{"titulo":"Ejecutar o verificar el estudio","detalle":"Asegura datos de largo plazo a 30 °C y 75 % HR, además del acelerado.","icono":"Thermometer","evidencia":"Informes de estabilidad."},{"titulo":"Proponer la vida útil","detalle":"Propón la vida útil con base en los datos y su análisis.","icono":"CalendarClock","evidencia":"Propuesta justificada."},{"titulo":"Rotular coherentemente","detalle":"Declara vida útil y condición de almacenamiento consistentes con el estudio.","icono":"Tag","evidencia":"Arte del rótulo aprobado."},{"titulo":"Confirmar en el tiempo","detalle":"Mantén el programa de estabilidad continua.","icono":"LineChart","evidencia":"Estabilidad continua."}]},"caso":{"titulo":"Un dossier con datos a 25 °C","contexto":"Un titular quiere registrar en Colombia un producto con 36 meses de vida útil sustentados solo con datos de largo plazo a 25 °C y 60 % de humedad relativa.","pregunta":"¿Qué le falta?","opciones":[{"texto":"Nada: 36 meses de datos son suficientes.","correcta":false,"retro":"Los datos son de una zona templada; no demuestran el comportamiento a 30 °C y 75 % de humedad."},{"texto":"Datos en condiciones de zona IVb (30 °C / 75 % HR) según la normativa colombiana vigente, y una vida útil y una condición de almacenamiento coherentes con esos datos.","correcta":true,"retro":"La estabilidad se demuestra en las condiciones del mercado donde se vende el producto."},{"texto":"Solo agregar al rótulo «almacenar en lugar fresco».","correcta":false,"retro":"Una advertencia no reemplaza los datos en las condiciones requeridas."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Zona climática IVb, normativa colombiana y vida útil$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Zona climática IVb, normativa colombiana y vida útil$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 31. Introducción a la unidad: del dato a la decisión
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Un 93,8 % antes de cualquier repetición","texto":"Un laboratorio fabricante en Bogotá analiza un lote de tabletas de metformina de 850 mg. La valoración por HPLC da 93,8 % frente a una especificación de 95,0–105,0 %. La tentación es repetir enseguida. Lo correcto es otra cosa: el analista informa al jefe de laboratorio, se conservan las soluciones y empieza una investigación. Todo lo que aprendiste en el curso converge aquí: en convertir datos en una decisión defendible."},"objetivos":["Explicar cómo se transforman los resultados analíticos en una decisión de calidad.","Diferenciar un resultado fuera de especificación (OOS) de uno fuera de tendencia (OOT).","Distinguir la liberación analítica de la liberación final del lote."],"conceptos":[{"icono":"XCircle","termino":"OOS","definicion":"Resultado fuera de especificación: cae fuera de los criterios aprobados en el registro sanitario, la farmacopea o la especificación interna."},{"icono":"LineChart","termino":"OOT","definicion":"Resultado fuera de tendencia: cumple la especificación pero se aparta del comportamiento esperado, por ejemplo en estabilidad o en el historial de lotes."},{"icono":"FileCheck","termino":"Liberación analítica","definicion":"Declaración de control de calidad de que el lote cumple todas las especificaciones, documentada en el certificado de análisis."},{"icono":"Signature","termino":"Liberación final","definicion":"Decisión de la persona autorizada de liberar el lote al mercado, que considera además la documentación de fabricación."}],"secciones":[{"titulo":"OOS y OOT: dos señales distintas","parrafos":["Todo el trabajo del laboratorio converge en una pregunta: ¿el lote cumple y puede liberarse? Para responderla, cada resultado debe ser **confiable, trazable e íntegro**. Un resultado **fuera de especificación (OOS)** cae fuera de los criterios aprobados. Un resultado **fuera de tendencia (OOT)** cumple la especificación, pero se aparta del comportamiento esperado del producto. Ninguno de los dos puede descartarse sin investigación documentada.","La Resolución 3619 de 2013 exige que el laboratorio tenga procedimientos para investigar resultados fuera de especificación, revisar los registros analíticos antes de emitir un informe y conservar los datos primarios. La guía de la FDA sobre la investigación de resultados OOS, revisada en 2022, es la referencia técnica más usada: describe una **fase I** de investigación en el laboratorio y fases posteriores cuando no se encuentra un error de laboratorio."]},{"titulo":"Liberación analítica y liberación final","parrafos":["La **liberación analítica** es la declaración de control de calidad de que el lote cumple todas sus especificaciones, documentada en el **certificado de análisis**. La **liberación final** al mercado la realiza la **persona autorizada** dentro del sistema de calidad, según la Resolución 1160 de 2016, considerando además la revisión de la documentación de fabricación.","En el caso inicial, si la fase I demuestra un error de dilución documentado, el resultado se invalida y se repite; si no, el caso escala a una investigación completa y el lote queda en cuarentena. Durante una inspección del INVIMA, este expediente será de los primeros que se revisen. Las fases posteriores, el análisis de causa raíz en producción y las acciones correctivas se profundizan en los cursos de Desviaciones y CAPA y de Gestión de Riesgos."]}],"errores":[{"error":"Repetir un OOS «hasta que cumpla».","correccion":"Toda repetición debe estar justificada por una investigación documentada."},{"error":"Ignorar un OOT porque cumple la especificación.","correccion":"Un OOT es una señal temprana: investígalo para proteger la vida útil."}],"comprueba":[{"pregunta":"¿Qué diferencia hay entre OOS y OOT?","respuesta":"El OOS está fuera de especificación; el OOT cumple, pero se aparta de la tendencia esperada."},{"pregunta":"¿Quién hace la liberación final del lote al mercado?","respuesta":"La persona autorizada, considerando también la documentación de fabricación."}],"resumen":["OOS y OOT son **señales que se investigan**, nunca se descartan.","La fase I ocurre en el **laboratorio**, antes de repetir.","Liberación **analítica** (certificado) y **final** (persona autorizada)."],"referencias":[{"cita":"FDA. Investigating Out-of-Specification (OOS) Test Results for Pharmaceutical Production, Rev. 1 (2022).","url":"https://www.fda.gov/media/158416/download"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Embudo ilustrado: arriba datos y cromatogramas, al medio una lupa de investigación y abajo un certificado con sello de liberación.","alt":"Del dato analítico a la decisión de liberación"}],"keywords":["resultados fuera de especificación","oos y oot diferencia","liberación analítica de lotes","decisión de calidad laboratorio","investigación oos"],"mapa":{"centro":"Del dato a la decisión","ramas":[{"titulo":"Datos confiables","icono":"Fingerprint","nodos":["Íntegros y trazables","Revisados por otra persona","Datos primarios conservados"]},{"titulo":"Señales","icono":"AlertTriangle","nodos":["OOS: fuera de especificación","OOT: fuera de tendencia","Nunca se descartan sin investigar"]},{"titulo":"Investigación","icono":"Search","nodos":["Fase I en el laboratorio","Fases siguientes en el proceso","CAPA"]},{"titulo":"Decisión","icono":"Gavel","nodos":["Certificado de análisis","Liberación analítica","Liberación final por la persona autorizada"]}]},"proceso":{"titulo":"Primeros pasos ante un resultado fuera de especificación","intro":"","pasos":[{"titulo":"Detener y no repetir","detalle":"El analista no repite el análisis por su cuenta y no descarta soluciones.","icono":"Hand","evidencia":"Soluciones y datos conservados."},{"titulo":"Informar","detalle":"Informa de inmediato al jefe de laboratorio.","icono":"Users","evidencia":"Registro de notificación."},{"titulo":"Iniciar la fase I","detalle":"Se revisan cálculos, equipos, estándares, soluciones y la ejecución.","icono":"Search","evidencia":"Formato de investigación de fase I."},{"titulo":"Decidir según la evidencia","detalle":"Si hay error de laboratorio demostrado, se invalida y se repite; si no, se escala.","icono":"GitBranch","evidencia":"Conclusión de fase I."},{"titulo":"Retener el lote","detalle":"El lote permanece en cuarentena hasta cerrar la investigación.","icono":"Lock","evidencia":"Estado del lote."}]},"caso":{"titulo":"El 93,8 % de la metformina","contexto":"La valoración de un lote de metformina 850 mg da 93,8 % frente a 95,0–105,0 %. El analista propone repetir de inmediato con una nueva preparación de la muestra.","pregunta":"¿Qué corresponde?","opciones":[{"texto":"Repetir y reportar el nuevo resultado si cumple.","correcta":false,"retro":"Repetir sin investigar es «probar hasta que cumpla», una práctica que ninguna autoridad acepta."},{"texto":"Informar al jefe de laboratorio, conservar soluciones y datos e iniciar la fase I; repetir solo si la investigación lo justifica.","correcta":true,"retro":"La investigación decide si hay un error de laboratorio; la repetición viene después y documentada."},{"texto":"Rechazar el lote de inmediato.","correcta":false,"retro":"Antes de concluir, se investiga si el resultado refleja el lote o un error de laboratorio."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: del dato a la decisión$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: del dato a la decisión$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 32. Investigación de resultados fuera de especificación (OOS): fase I de laboratorio
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"La fiola equivocada","texto":"Un OOS de valoración por HPLC lleva a revisar todo: el equipo, el estándar, los cálculos. Al revisar el cuaderno, el jefe de laboratorio nota que el analista registró una fiola de 50 mL donde el método pedía 100 mL, y la fiola de 50 mL todavía está en la mesa con la solución. Es un error de laboratorio claro y documentado. La fase I existe para encontrar errores así, con evidencia, antes de concluir algo sobre el lote."},"objetivos":["Describir las responsabilidades del analista y del supervisor en la fase I.","Aplicar una lista de verificación de investigación de laboratorio.","Decidir cuándo un resultado puede invalidarse y cuándo se escala a la fase II."],"conceptos":[{"icono":"Search","termino":"Fase I","definicion":"Investigación en el laboratorio para determinar si hubo un error evidente de laboratorio: cálculos, equipos, estándares, soluciones, ejecución."},{"icono":"CheckCircle2","termino":"Causa asignable","definicion":"Error de laboratorio identificado y documentado que explica el resultado. Solo con causa asignable se invalida el resultado original."},{"icono":"Repeat","termino":"Repetición","definicion":"Nuevo análisis justificado por la investigación, según un plan definido antes de ejecutarlo, sin descartar el resultado original sin fundamento."},{"icono":"GitBranch","termino":"Escalamiento","definicion":"Si la fase I no encuentra error de laboratorio, la investigación pasa a la fase II, que incluye la revisión de la fabricación."}],"secciones":[{"titulo":"Qué se revisa en la fase I","parrafos":["La guía de la FDA sobre resultados OOS describe una **fase I** de investigación en el laboratorio. El **analista** informa de inmediato al supervisor, conserva las soluciones, el material y los datos, y no repite el análisis por su cuenta. El **supervisor** revisa con el analista, de forma objetiva y oportuna, si hubo un error evidente: que los **cálculos** estén correctos; que el **equipo** estuviera calificado y calibrado y que la **idoneidad del sistema** cumpliera; que el **estándar** fuera el correcto y vigente; que las **soluciones** se prepararan como dice el método (volúmenes, diluciones, reactivos); y que la **ejecución** siguiera el procedimiento.","Como en el caso de la fiola, la evidencia física (soluciones conservadas, material usado, registros) es lo que permite demostrar un error. Por eso conservar todo desde el primer momento es crítico: una solución descartada es una evidencia perdida."]},{"titulo":"Invalidar, repetir o escalar","parrafos":["Si la fase I identifica una **causa asignable** de laboratorio, documentada, el resultado original puede **invalidarse** y el análisis se repite según un plan definido. Si **no** se encuentra un error de laboratorio, el resultado se considera válido de forma preliminar y la investigación pasa a la **fase II**, que incluye la revisión de la fabricación y, si corresponde, análisis adicionales según un plan aprobado.","La guía rechaza prácticas como **probar hasta que cumpla**, promediar un resultado fuera de especificación con otros para ocultarlo, o usar pruebas estadísticas de valores atípicos en ensayos químicos para descartar un resultado sin causa. Un laboratorio que tiene muchos OOS invalidados por «error de laboratorio» debe revisar sus causas de fondo: entrenamiento, métodos o equipos."]}],"errores":[{"error":"Descartar soluciones antes de investigar.","correccion":"Conserva todas las evidencias desde el momento del OOS."},{"error":"Invalidar sin causa asignable documentada.","correccion":"Solo una causa demostrada permite invalidar el resultado original."},{"error":"Usar pruebas de valores atípicos para descartar un OOS químico.","correccion":"No se descarta un resultado químico por estadística sin causa."}],"comprueba":[{"pregunta":"¿Qué hace el analista ante un OOS?","respuesta":"Informa al supervisor, conserva soluciones y datos y no repite por su cuenta."},{"pregunta":"¿Cuándo se invalida un resultado OOS?","respuesta":"Cuando la fase I identifica y documenta una causa asignable de laboratorio."}],"resumen":["La fase I busca **errores de laboratorio con evidencia**.","Con causa asignable, **se invalida y se repite** según plan.","Sin causa, se **escala a la fase II**; nunca se prueba hasta que cumpla."],"referencias":[{"cita":"FDA. Investigating Out-of-Specification (OOS) Test Results for Pharmaceutical Production, Rev. 1 (2022).","url":"https://www.fda.gov/media/158416/download"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"FDA. Data Integrity and Compliance With Drug CGMP: Questions and Answers (2018).","url":"https://www.fda.gov/media/119267/download"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"}],"imagenes":[{"ubicacion":"En la sección de revisión","descripcion":"Mesa de laboratorio ilustrada con soluciones conservadas, una fiola resaltada, un cuaderno y una lupa, en la paleta de marca.","alt":"Evidencias conservadas en la fase I de una investigación OOS"}],"keywords":["investigación oos fase i","resultados fuera de especificación fda","causa asignable laboratorio","probar hasta que cumpla testing into compliance","investigación de laboratorio oos","guía fda oos 2022"],"mapa":{"centro":"Fase I de un OOS","ramas":[{"titulo":"Analista","icono":"UserCheck","nodos":["Informa de inmediato","Conserva soluciones","No repite por su cuenta"]},{"titulo":"Supervisor","icono":"Users","nodos":["Revisa con el analista","Evalúa evidencias","Decide con calidad"]},{"titulo":"Qué revisar","icono":"ClipboardList","nodos":["Cálculos","Equipo e idoneidad","Estándar y soluciones","Ejecución del método"]},{"titulo":"Resultado","icono":"GitBranch","nodos":["Causa asignable: invalidar y repetir","Sin causa: fase II","Todo documentado"]}]},"proceso":{"titulo":"Lista de verificación de la fase I","intro":"","pasos":[{"titulo":"Conservar evidencias","detalle":"Soluciones, material, viales y datos electrónicos quedan intactos.","icono":"Lock","evidencia":"Registro de conservación."},{"titulo":"Revisar cálculos","detalle":"Recalcula desde los datos primarios, incluidas diluciones y factores.","icono":"Calculator","evidencia":"Cálculos revisados."},{"titulo":"Revisar equipo e idoneidad","detalle":"Verifica calificación, calibración e idoneidad de la corrida.","icono":"Cpu","evidencia":"Registros del equipo."},{"titulo":"Revisar estándar y soluciones","detalle":"Confirma estándar vigente, preparación de soluciones y material volumétrico.","icono":"TestTube","evidencia":"Registros de preparación."},{"titulo":"Entrevistar al analista","detalle":"Reconstruye la ejecución paso a paso con el analista.","icono":"Users","evidencia":"Notas de la entrevista."},{"titulo":"Concluir","detalle":"Con causa asignable, invalida y repite según plan; sin ella, escala a fase II.","icono":"GitBranch","evidencia":"Informe de fase I aprobado."}]},"caso":{"titulo":"Sin error de laboratorio","contexto":"La fase I de un OOS de disolución no encuentra ningún error: cálculos, equipo, medio, estándar y ejecución están correctos.","pregunta":"¿Qué sigue?","opciones":[{"texto":"Repetir la disolución con otras seis tabletas y usar ese resultado.","correcta":false,"retro":"Sin causa asignable, el resultado original no se invalida; reemplazarlo con una repetición es probar hasta que cumpla."},{"texto":"Considerar el resultado válido de forma preliminar y escalar a la fase II, con revisión de la fabricación y análisis adicionales según un plan aprobado.","correcta":true,"retro":"La ausencia de error de laboratorio apunta a que el resultado puede reflejar el lote; se investiga el proceso."},{"texto":"Cerrar la investigación como «causa no identificada» y liberar.","correcta":false,"retro":"Un OOS sin causa de laboratorio no permite liberar: la investigación continúa."}]}}$j$::jsonb;
