  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 33. Resultados fuera de tendencia (OOT) en estabilidad y lotes
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Todavía cumple, pero ya avisó","texto":"En el estudio de estabilidad de un lote, la valoración da 99,1 %, 98,7 % y, a los 12 meses, 96,0 %. Sigue dentro de la especificación de 90,0–110,0 %. Pero los otros lotes del mismo producto pierden menos de 1 % en ese tiempo. Ese 96,0 % no es un OOS; es un OOT. Si se ignora, a los 24 meses puede convertirse en un retiro del mercado."},"objetivos":["Definir un resultado fuera de tendencia y por qué importa.","Describir métodos simples para detectar OOT en estabilidad y en lotes.","Gestionar un OOT con investigación proporcional al riesgo."],"conceptos":[{"icono":"LineChart","termino":"Tendencia esperada","definicion":"El comportamiento habitual del producto en el tiempo o entre lotes, construido con datos históricos."},{"icono":"AlertTriangle","termino":"OOT","definicion":"Resultado que cumple la especificación pero se aparta de la tendencia esperada de forma inusual."},{"icono":"Sigma","termino":"Métodos de detección","definicion":"Regresión con intervalos de predicción en estabilidad, cartas de control para lotes, comparación con el comportamiento de otros lotes."},{"icono":"Search","termino":"Investigación proporcional","definicion":"Se revisa el dato y, según el riesgo, el lote y el proceso, sin la misma urgencia que un OOS, pero con documentación."}],"secciones":[{"titulo":"Qué es y cómo detectarlo","parrafos":["Un **resultado fuera de tendencia (OOT)** cumple la especificación, pero se aparta del comportamiento esperado del producto. No hay una definición única en la normativa: cada laboratorio define en su procedimiento qué considera OOT y cómo lo detecta. La clave es tener una **tendencia esperada** construida con datos: cómo se comportan los lotes en estabilidad y qué variabilidad tienen los resultados de liberación.","En **estabilidad**, un método común es ajustar una regresión de los datos de cada lote y comparar los nuevos puntos con **intervalos de predicción** construidos con los datos históricos; un punto fuera del intervalo es un OOT. También se compara la pendiente de un lote con la de los demás. Entre **lotes de liberación**, se usan **cartas de control** con límites estadísticos y reglas para detectar rachas o desplazamientos."]},{"titulo":"Gestionar un OOT","parrafos":["Un OOT se gestiona con una investigación **proporcional al riesgo**. Primero se verifica que el dato sea correcto (cálculos, idoneidad, estándar), como en una fase I. Luego se evalúa el lote: ¿qué tan lejos está de la tendencia?, ¿qué pasaría si la tendencia continúa hasta el final de la vida útil?, ¿hay algo distinto en su fabricación o en sus materiales?","En el caso inicial, proyectar la pérdida de ese lote hasta los 24 meses podría llevarlo fuera de especificación. Las acciones posibles incluyen reforzar la vigilancia del lote con análisis adicionales, investigar su fabricación y, según el riesgo, tomar decisiones sobre su vida útil o su distribución. Un OOT detectado a tiempo es la mejor forma de evitar un OOS en el mercado."]}],"errores":[{"error":"No tener una tendencia de referencia.","correccion":"Construye tendencias con datos históricos de estabilidad y liberación."},{"error":"Tratar un OOT como si no existiera.","correccion":"Define en el procedimiento cómo detectarlo y gestionarlo."}],"comprueba":[{"pregunta":"¿Qué es un OOT?","respuesta":"Un resultado que cumple la especificación pero se aparta de la tendencia esperada del producto."},{"pregunta":"¿Qué método se usa para detectar OOT en estabilidad?","respuesta":"Regresión con intervalos de predicción y comparación de pendientes entre lotes."}],"resumen":["El OOT **cumple, pero avisa**.","Se detecta con **tendencias**, regresión y cartas de control.","Se gestiona con investigación **proporcional al riesgo**."],"referencias":[{"cita":"FDA. Investigating Out-of-Specification (OOS) Test Results for Pharmaceutical Production, Rev. 1 (2022).","url":"https://www.fda.gov/media/158416/download"},{"cita":"ICH. Q1A(R2) Stability Testing of New Drug Substances and Products.","url":"https://database.ich.org/sites/default/files/Q1A%28R2%29%20Guideline.pdf"},{"cita":"NIST/SEMATECH. e-Handbook of Statistical Methods, capítulo 4: Process Modeling.","url":"https://www.itl.nist.gov/div898/handbook/pmd/pmd.htm"},{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"}],"imagenes":[{"ubicacion":"En la sección de detección","descripcion":"Gráfico de estabilidad con bandas de predicción y un punto que cae fuera de la banda, marcado con un círculo turquesa.","alt":"Resultado fuera de tendencia en un estudio de estabilidad"}],"keywords":["resultados fuera de tendencia oot","oot en estabilidad","tendencias de estabilidad farmacéutica","intervalos de predicción estabilidad","cartas de control laboratorio","diferencia oos oot"],"mapa":{"centro":"Detectar antes de fallar","ramas":[{"titulo":"En estabilidad","icono":"CalendarClock","nodos":["Regresión por lote","Intervalos de predicción","Comparación entre lotes"]},{"titulo":"Entre lotes","icono":"BarChart3","nodos":["Cartas de control","Límites estadísticos","Patrones y rachas"]},{"titulo":"Gestión","icono":"Search","nodos":["Verificar el dato","Evaluar el lote","Proyectar al final de la vida útil"]},{"titulo":"Acción","icono":"ShieldCheck","nodos":["Vigilancia reforzada","Investigación de causa","Decisión sobre el lote"]}]},"proceso":{"titulo":"Gestión de un OOT de estabilidad","intro":"","pasos":[{"titulo":"Detectar","detalle":"El nuevo punto queda fuera del intervalo de predicción o la pendiente difiere de los demás lotes.","icono":"LineChart","evidencia":"Gráfico de tendencia."},{"titulo":"Verificar el dato","detalle":"Revisa cálculos, idoneidad, estándar y ejecución.","icono":"Search","evidencia":"Verificación documentada."},{"titulo":"Proyectar","detalle":"Estima el valor al final de la vida útil si la tendencia continúa.","icono":"Sigma","evidencia":"Proyección estadística."},{"titulo":"Investigar el lote","detalle":"Revisa fabricación, materiales y condiciones de la cámara.","icono":"FileSearch","evidencia":"Informe de investigación."},{"titulo":"Decidir acciones","detalle":"Vigilancia reforzada, investigación de causa o decisiones sobre el lote.","icono":"Gavel","evidencia":"Decisión documentada."}]},"caso":{"titulo":"El 96,0 % a los 12 meses","contexto":"Un lote en estabilidad pierde 3 % en 12 meses, cuando los demás lotes pierden menos de 1 %. El resultado cumple la especificación.","pregunta":"¿Qué haces?","opciones":[{"texto":"Nada: cumple la especificación.","correcta":false,"retro":"El patrón del lote es distinto al de los demás; si la tendencia sigue, puede fallar antes de vencer."},{"texto":"Registrarlo como OOT, verificar el dato, proyectar el comportamiento al final de la vida útil, investigar la fabricación del lote y reforzar su vigilancia.","correcta":true,"retro":"Un OOT permite actuar antes de un OOS en el mercado."},{"texto":"Repetir el análisis hasta obtener un valor más alto.","correcta":false,"retro":"Repetir para «mejorar» el dato oculta la señal y compromete la integridad."}]}}$j$::jsonb;
