    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 34. Revisión de datos y certificado de análisis
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El segundo par de ojos","texto":"Un analista cuidadoso calcula una valoración y obtiene 100,8 %. El revisor, al recorrer los datos, nota que el peso del estándar en el cálculo no coincide con el impreso de la balanza: se transcribió 25,12 mg en lugar de 25,21 mg. El resultado correcto es 100,4 %, igual dentro de especificación, pero el error existía. La revisión de datos es el filtro que detecta errores antes de que lleguen al paciente o al inspector."},"objetivos":["Aplicar una revisión de datos completa por una segunda persona.","Identificar los elementos obligatorios de un certificado de análisis.","Reconocer los riesgos de integridad de datos en la revisión."],"conceptos":[{"icono":"FileSearch","termino":"Revisión de datos","definicion":"Verificación por una segunda persona de datos primarios, cálculos, idoneidad, estándares, equipos, reactivos y coherencia entre registros electrónicos y en papel."},{"icono":"Fingerprint","termino":"Pista de auditoría","definicion":"Registro del sistema que muestra quién creó, modificó o borró datos y cuándo. Su revisión es parte de la revisión de datos electrónicos."},{"icono":"FileCheck","termino":"Certificado de análisis","definicion":"Documento que identifica el producto y el lote, la especificación y los métodos, los resultados con sus límites, la conclusión y la firma del responsable."},{"icono":"ShieldCheck","termino":"Integridad","definicion":"Que los datos reportados correspondan exactamente a los datos originales, completos y sin alteraciones no justificadas."}],"secciones":[{"titulo":"Qué revisa el revisor","parrafos":["La **revisión de datos** la hace una segunda persona, distinta del analista, antes de emitir el resultado. Verifica que los **cálculos** sean correctos y que los datos usados coincidan con los **datos primarios** (impresos de balanza, cromatogramas, registros del equipo); que la **idoneidad del sistema** cumpliera; que los **estándares** y **reactivos** fueran los correctos y estuvieran vigentes; que los **equipos** estuvieran calificados y calibrados; y que el método aplicado fuera la versión vigente.","En sistemas electrónicos, la revisión incluye la **pista de auditoría**: buscar reprocesos, cambios de integración, inyecciones no reportadas o secuencias abortadas, y verificar que estén justificados. La guía de la FDA y la guía PI 041 de PIC/S sobre integridad de datos describen lo que se espera. Una transcripción errónea, como la del caso inicial, es exactamente lo que la revisión debe detectar."]},{"titulo":"El certificado de análisis","parrafos":["El **certificado de análisis** es el documento que comunica los resultados. Debe incluir la identificación del producto y del lote, la fecha de análisis, las referencias a la especificación y a los métodos, los **resultados numéricos con sus límites**, la conclusión de **cumple o no cumple** y la firma de la persona responsable. La Resolución 3619 de 2013 exige que los informes se revisen y aprueben y que cualquier corrección sea trazable.","En un laboratorio externo certificado en BPL por el INVIMA, el certificado es además el producto contractual que se entrega al titular del registro. Ningún certificado se firma con desviaciones u OOS abiertos que afecten el lote."]}],"errores":[{"error":"Revisar solo el resultado final.","correccion":"Revisa desde los datos primarios y la pista de auditoría."},{"error":"Firmar certificados con investigaciones abiertas.","correccion":"Cierra cualquier desviación u OOS que afecte el lote antes de firmar."}],"comprueba":[{"pregunta":"¿Qué elementos debe tener un certificado de análisis?","respuesta":"Producto y lote, fecha, especificación y métodos, resultados con límites, conclusión y firma del responsable."},{"pregunta":"¿Qué se busca en la pista de auditoría?","respuesta":"Reprocesos, cambios de integración, inyecciones no reportadas y secuencias abortadas, y su justificación."}],"resumen":["La revisión de datos es el **segundo par de ojos**.","Incluye **datos primarios y pista de auditoría**.","El certificado se firma **sin investigaciones abiertas**."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"FDA. Data Integrity and Compliance With Drug CGMP: Questions and Answers (2018).","url":"https://www.fda.gov/media/119267/download"},{"cita":"PIC/S. PI 041: Good Practices for Data Management and Integrity in regulated GMP/GDP environments.","url":"https://picscheme.org/docview/4234"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"}],"imagenes":[{"ubicacion":"En la sección de revisión","descripcion":"Dos analistas ilustrados frente a una pantalla con un cromatograma y una pista de auditoría resaltada.","alt":"Revisión de datos y pista de auditoría en el laboratorio"}],"keywords":["revisión de datos analíticos","certificado de análisis","pista de auditoría laboratorio","integridad de datos control de calidad","segunda revisión de resultados","contenido del certificado de análisis"],"mapa":{"centro":"Del dato al certificado","ramas":[{"titulo":"Datos primarios","icono":"Database","nodos":["Impresos y archivos originales","Cuadernos y hojas de trabajo","Pista de auditoría"]},{"titulo":"Verificaciones","icono":"FileSearch","nodos":["Cálculos","Idoneidad y equipos","Estándares y reactivos"]},{"titulo":"Coherencia","icono":"Scale","nodos":["Papel frente a electrónico","Transcripciones","Sin datos omitidos"]},{"titulo":"Certificado","icono":"FileCheck","nodos":["Producto y lote","Resultados y límites","Conclusión y firma"]}]},"proceso":{"titulo":"Revisión de datos de una valoración por HPLC","intro":"","pasos":[{"titulo":"Verificar el método y la versión","detalle":"Confirma que se usó la versión vigente del método.","icono":"BookOpen","evidencia":"Referencia del método."},{"titulo":"Revisar idoneidad","detalle":"Comprueba que todos los criterios de idoneidad cumplieran.","icono":"Gauge","evidencia":"Resultados de idoneidad."},{"titulo":"Cruzar datos primarios","detalle":"Compara pesos, volúmenes y áreas con impresos y archivos originales.","icono":"Scale","evidencia":"Cruce documentado."},{"titulo":"Recalcular","detalle":"Recalcula el resultado desde los datos primarios.","icono":"Calculator","evidencia":"Cálculo verificado."},{"titulo":"Revisar la pista de auditoría","detalle":"Busca reprocesos, cambios de integración e inyecciones no reportadas.","icono":"Fingerprint","evidencia":"Revisión de la pista de auditoría."},{"titulo":"Firmar o devolver","detalle":"Firma la revisión o devuelve con observaciones para corregir.","icono":"Signature","evidencia":"Revisión firmada."}]},"caso":{"titulo":"Una inyección que no aparece","contexto":"Al revisar la pista de auditoría de una corrida, el revisor encuentra una inyección de la muestra realizada antes de la secuencia oficial, que no aparece en el informe.","pregunta":"¿Qué corresponde?","opciones":[{"texto":"Ignorarla: fue una prueba del analista.","correcta":false,"retro":"Inyectar la muestra fuera de la secuencia y no reportarla es una señal clásica de problema de integridad."},{"texto":"Detener la aprobación, pedir explicación documentada, evaluar el resultado de esa inyección y, si no hay justificación, abrir una investigación de integridad de datos.","correcta":true,"retro":"Toda inyección de muestra es un dato que debe evaluarse; su omisión se investiga."},{"texto":"Borrar la inyección para que el informe quede limpio.","correcta":false,"retro":"Borrar datos es una falla grave de integridad."}]}}$j$::jsonb;
