  -- 35. Liberación analítica de un lote: caso integrador
  v_data := $j${"v":1,"duracion":35,"gancho":{"titulo":"Todo cumple… salvo un detalle","texto":"Un laboratorio de Medellín recibe para liberación un lote de suspensión oral de amoxicilina de 250 mg/5 mL. La especificación incluye aspecto, pH, valoración por HPLC, uniformidad de dosis en envase multidosis, recuento microbiano, ausencia de Escherichia coli y volumen entregable. Todos los resultados cumplen. En la revisión de datos, el supervisor detecta que el estándar secundario de amoxicilina tenía la recalificación vencida dos días antes del análisis. ¿Se firma el certificado?"},"objetivos":["Integrar los contenidos del curso para decidir la liberación analítica de un lote.","Aplicar las etapas de la liberación analítica conforme a la normativa colombiana.","Redactar la conclusión y la nota de revisión de un caso con desviación."],"conceptos":[{"icono":"ClipboardCheck","termino":"Ensayos completos","definicion":"Todos los ensayos de la especificación aprobada en el registro sanitario, ejecutados con la farmacopea vigente o el método validado."},{"icono":"FileSearch","termino":"Revisión de datos","definicion":"Cálculos, idoneidad, vigencia de estándares, calificación de equipos, preparación de reactivos y coherencia de registros."},{"icono":"AlertTriangle","termino":"Sin pendientes","definicion":"Ningún OOS ni desviación de laboratorio abierta que afecte el lote."},{"icono":"FileCheck","termino":"Certificado y cambio de estado","definicion":"Se emite el certificado y el lote pasa de cuarentena a aprobado analíticamente, para la decisión de la persona autorizada."}],"secciones":[{"titulo":"Las etapas de la liberación analítica","parrafos":["La liberación analítica no es un acto aislado al final del análisis, sino un proceso con etapas. **Primero**, el laboratorio verifica que se ejecutaron **todos** los ensayos de la especificación aprobada en el registro sanitario (identificación, valoración, impurezas, disolución, uniformidad de dosis, pruebas microbiológicas, entre otros), con la edición vigente de la farmacopea o el método validado. **Segundo**, una segunda persona hace la **revisión de datos**: cálculos, idoneidad, vigencia de estándares, calibración y calificación de equipos, preparación de reactivos y coherencia entre datos electrónicos y registros en papel.","**Tercero**, se confirma que no existen **OOS abiertos** ni **desviaciones de laboratorio** pendientes que afecten el lote. **Cuarto**, se emite el **certificado de análisis** con todos sus elementos. **Finalmente**, el lote cambia de estado en el sistema, de cuarentena a aprobado analíticamente, y pasa a la **persona autorizada** para la liberación final, según la Resolución 1160 de 2016. La Resolución 3619 de 2013 exige que los informes se revisen y aprueben, que los datos primarios se conserven y que cualquier corrección sea trazable."]},{"titulo":"El caso de la amoxicilina resuelto","parrafos":["En el caso, todos los resultados cumplen, pero el estándar secundario tenía la **recalificación vencida**. La decisión correcta **no es firmar** el certificado. Se abre una **desviación de laboratorio** y se evalúa el impacto: por ejemplo, repitiendo la valoración con un estándar vigente o recalificando el estándar y demostrando que seguía siendo apto en la fecha del análisis. Solo con evidencia documentada se procede a la liberación analítica.","La nota de revisión debe contar lo que pasó con hechos: qué se detectó, qué riesgo implicaba (un estándar fuera de vigencia puede haber cambiado su contenido y sesgar la valoración), qué se hizo para evaluarlo, qué resultado se obtuvo y qué acción preventiva se tomará (por ejemplo, alertas de vencimiento en el inventario de estándares). Así cierra el curso: un buen laboratorio no se mide por los lotes que cumplen, sino por cómo decide cuando algo no encaja."]}],"errores":[{"error":"Firmar con desviaciones abiertas.","correccion":"Cierra con evidencia cualquier desviación que afecte el lote."},{"error":"Liberar con ensayos pendientes.","correccion":"Verifica que todos los ensayos de la especificación estén completos y revisados."},{"error":"Notas de revisión vagas.","correccion":"Documenta hechos, riesgo, evaluación, resultado y acción preventiva."}],"comprueba":[{"pregunta":"¿Cuáles son las etapas de la liberación analítica?","respuesta":"Ensayos completos, revisión de datos, verificación de pendientes, emisión del certificado y cambio de estado."},{"pregunta":"¿Qué hace la persona autorizada después de la liberación analítica?","respuesta":"Decide la liberación final del lote al mercado, considerando también la documentación de fabricación."}],"resumen":["Liberar analíticamente es certificar que **todos los ensayos se hicieron bien y cumplen**.","La **revisión de datos** detecta errores antes de que lleguen al paciente.","Ninguna **desviación u OOS abierto** puede quedar pendiente al firmar."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 3619 de 2013: Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"FDA. Investigating Out-of-Specification (OOS) Test Results for Pharmaceutical Production, Rev. 1 (2022).","url":"https://www.fda.gov/media/158416/download"},{"cita":"OMS. TRS 943, Anexo 3: General guidelines for the establishment, maintenance and distribution of chemical reference substances.","url":"https://www.who.int/docs/default-source/medicines/norms-and-standards/guidelines/quality-control/trs943-annex3-establishmentmaintenance-distribution-chemica-reference-substances.pdf"},{"cita":"OMS. TRS 957, Anexo 1: WHO good practices for pharmaceutical quality control laboratories (2010).","url":"https://www.who.int/publications/m/item/trs957-annex1"}],"imagenes":[{"ubicacion":"Al inicio de la lectura","descripcion":"Frasco de suspensión de amoxicilina ilustrado con siete fichas de ensayo alrededor (aspecto, pH, valoración, uniformidad, recuento, E. coli, volumen) y un estándar con alerta de vencimiento.","alt":"Caso integrador de liberación analítica de una suspensión de amoxicilina"}],"keywords":["liberación analítica de un lote","caso integrador control de calidad","certificado de análisis liberación","liberación de lotes farmacéuticos","estándar vencido desviación","control de calidad caso práctico"],"mapa":{"centro":"Liberar analíticamente un lote","ramas":[{"titulo":"Ensayos","icono":"ClipboardCheck","nodos":["Especificación registrada","Métodos vigentes","Todos ejecutados"]},{"titulo":"Revisión","icono":"FileSearch","nodos":["Cálculos e idoneidad","Estándares y equipos","Pista de auditoría"]},{"titulo":"Pendientes","icono":"AlertTriangle","nodos":["OOS abiertos","Desviaciones de laboratorio","Investigaciones"]},{"titulo":"Cierre","icono":"FileCheck","nodos":["Certificado de análisis","Cambio de estado","Persona autorizada"]}]},"proceso":{"titulo":"Liberación analítica paso a paso","intro":"","pasos":[{"titulo":"Confirmar ensayos completos","detalle":"Verifica que se ejecutaron todos los ensayos de la especificación registrada.","icono":"ClipboardCheck","evidencia":"Lista de ensayos completada."},{"titulo":"Revisar los datos","detalle":"Una segunda persona revisa cálculos, idoneidad, estándares, equipos y registros.","icono":"FileSearch","evidencia":"Revisión firmada."},{"titulo":"Verificar pendientes","detalle":"Confirma que no haya OOS ni desviaciones abiertas que afecten el lote.","icono":"AlertTriangle","evidencia":"Estado de investigaciones."},{"titulo":"Gestionar lo encontrado","detalle":"Si aparece un problema, abre la desviación y evalúa el impacto con evidencia.","icono":"Search","evidencia":"Desviación y evaluación."},{"titulo":"Emitir el certificado","detalle":"Emite el certificado con resultados, límites, conclusión y firma.","icono":"FileCheck","evidencia":"Certificado de análisis."},{"titulo":"Cambiar el estado","detalle":"Cambia el estado a aprobado analíticamente y entrega a la persona autorizada.","icono":"Signature","evidencia":"Estado en el sistema."}]},"caso":{"titulo":"La amoxicilina y el estándar vencido","contexto":"Todos los resultados del lote de suspensión de amoxicilina cumplen. El estándar secundario usado en la valoración tenía la recalificación vencida dos días antes del análisis.","pregunta":"¿Cuál es la decisión correcta?","opciones":[{"texto":"Firmar el certificado: dos días no cambian nada y el lote cumple.","correcta":false,"retro":"Sin evidencia, no se sabe si el estándar seguía apto; firmar sería certificar un dato no respaldado."},{"texto":"No firmar todavía: abrir una desviación, evaluar el impacto con un estándar vigente o con la recalificación del estándar y, solo con evidencia documentada, emitir el certificado.","correcta":true,"retro":"La liberación analítica exige datos respaldados; la desviación se cierra con evidencia y con una acción preventiva."},{"texto":"Rechazar el lote.","correcta":false,"retro":"El problema es del estándar, no necesariamente del lote; se evalúa antes de decidir."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Liberación analítica de un lote: caso integrador$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Liberación analítica de un lote: caso integrador$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (121_experiencias_control_calidad.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Control de Calidad de Medicamentos$t$, v_n;
END $exp$;
